INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "繁荣", "is_correct": true, "explanation": "“繁荣”指城市经济兴旺，与“吸引了很多年轻人”相符，符合语境。"}, {"text": "垄断", "is_correct": false, "explanation": "语义：“垄断”指独占市场，不能用来说城市吸引年轻人。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”指长短，不能指城市的吸引力。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不能说城市的体重。"}], "explanations": {"繁荣": "“繁荣”指城市经济兴旺，与“吸引了很多年轻人”相符，符合语境。", "垄断": "语义：“垄断”指独占市场，不能用来说城市吸引年轻人。", "长度": "语义：“长度”指长短，不能指城市的吸引力。", "体重": "搭配：“体重”用于人或动物，不能说城市的体重。"}, "sentence_index": 0, "correct_answer": "繁荣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很繁荣，大家都怕他。", "explanation": "这里应该用〈暴躁〉。“繁荣”用于经济、事业或城市，形容人脾气急躁要用“暴躁”。"}, {"text": "他的肌肉很繁荣，经常健身。", "explanation": "这里应该用〈发达〉。“繁荣”用于经济、事业，形容人体肌肉发达要用“发达”。"}, {"text": "她的脸蛋很繁荣，大家都喜欢看。", "explanation": "这里应该用〈漂亮〉。“繁荣”指经济或事业蓬勃发展，形容人容貌好看要用“漂亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "繁荣", "is_correct": true, "explanation": "“繁荣”指文化兴旺发达，与“需要自由的环境”相符，符合语境。"}, {"text": "长度", "is_correct": false, "explanation": "语义：文化没有长度，“长度”不能指文化的状态。"}, {"text": "视力", "is_correct": false, "explanation": "语义：文化没有视力，“视力”不能用于描述文化。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”用于人，不能说文化的身高。"}], "explanations": {"繁荣": "“繁荣”指文化兴旺发达，与“需要自由的环境”相符，符合语境。", "长度": "语义：文化没有长度，“长度”不能指文化的状态。", "视力": "语义：文化没有视力，“视力”不能用于描述文化。", "身高": "搭配：“身高”用于人，不能说文化的身高。"}, "sentence_index": 6, "correct_answer": "繁荣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他性格很繁荣，大家都喜欢和他玩。", "explanation": "这里应该用〈活跃〉。“繁荣”指经济或事业兴旺，形容人性格开朗、爱说话要用“活跃”。"}, {"text": "他的求知欲很繁荣，每天都读很多书。", "explanation": "这里应该用〈旺盛〉。“繁荣”用于经济、文化、事业，形容欲望或精力充沛要用“旺盛”。"}, {"text": "这位老人很繁荣，但很节俭。", "explanation": "这里应该用〈富有〉。“繁荣”说经济或事业兴旺，形容人有钱要用“富有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇因为旅游业而慢慢繁荣下来。", "corrected_sentence": "这个小镇因为旅游业而慢慢繁荣起来。", "error_description": "补语错误。“繁荣”表示由弱变强，补语应用“起来”；“下来”表示由上向下或由动到静，不能说“繁荣下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地区的经济是繁荣。", "corrected_sentence": "这个地区的经济很繁荣。", "error_description": "错误：形容词“繁荣”作谓语时，“是”后要加“的”（“是繁荣的”），或直接用程度副词“很”（“很繁荣”）。“是繁荣”缺少“的”，不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1204569f-18de-4586-b2cd-e36c96a9ec29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20053, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明示", "is_correct": true, "explanation": "反义：“明示”指明白地表示，与“暗示”的间接方式正相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "无关：“拒绝”与“暗示”在任何义项上都不构成反义或近义关系。"}, {"text": "保存", "is_correct": false, "explanation": "无关：「保存」是把东西留存，与「暗示」没有反义关系。"}, {"text": "选择", "is_correct": false, "explanation": "无关：“选择”是挑拣，与“暗示”没有反义关系。"}], "correct_answer": "明示", "explanations": {"明示": "反义：“明示”指明白地表示，与“暗示”的间接方式正相反。", "拒绝": "无关：“拒绝”与“暗示”在任何义项上都不构成反义或近义关系。", "保存": "无关：「保存」是把东西留存，与「暗示」没有反义关系。", "选择": "无关：“选择”是挑拣，与“暗示”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20053, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明示", "is_correct": true, "explanation": "反义：“明示”指明白地表示，与“暗示”的间接方式正相反。"}, {"text": "承认", "is_correct": false, "explanation": "无关：“承认”是认可某个事实，与“暗示”没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：「搬运」是把东西从一处移到另一处，与「暗示」没有反义关系。"}, {"text": "询问", "is_correct": false, "explanation": "无关：“询问”是提出问题求答，与“暗示”没有反义关系。"}], "correct_answer": "明示", "explanations": {"明示": "反义：“明示”指明白地表示，与“暗示”的间接方式正相反。", "承认": "无关：“承认”是认可某个事实，与“暗示”没有反义关系。", "搬运": "无关：「搬运」是把东西从一处移到另一处，与「暗示」没有反义关系。", "询问": "无关：“询问”是提出问题求答，与“暗示”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20053, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用间接的方式表达想法或意思。", "primary_collocate": null, "pronunciation": "àn shì zhe", "ipa": "an˥˩ ʂɨ˥˩ ʈʂɤ", "syllable_count": 3, "sentences": [{"text": "他对这个方案只字不提，却在笔记本上反复划掉同一行字，暗示着心里并不认同。", "target_word": "暗示着", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他皱着眉头，暗示着对结果不满意。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板看了看表，暗示着会议该结束了。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直看门口，暗示着想早点回家。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的沉默暗示着他不同意这个办法。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈咳了一声，暗示着孩子别再说了。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不停地看手机，暗示着自己有急事。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理笑着摇头，暗示着不能答应这个要求。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把书合上，暗示着今天不想再聊了。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的语气暗示着事情还有变化。", "target_word": "暗示着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暗示", "label": "原形"}, {"form": "暗示了", "label": "体标（了）"}, {"form": "暗示过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "人用间接的话或动作表达自己的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53f15428-b18b-410e-8301-878efd0cd378') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20053, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垄断着", "is_correct": false, "explanation": "语义：「垄断」是独占、控制，不能用来表示「心里并不认同」这种想法，句意不通。"}, {"text": "暗示着", "is_correct": true, "explanation": "正确：「暗示着」表示不把话说出口、只通过动作透露想法，与「只字不提却反复划掉」的语境吻合。"}, {"text": "提高着", "is_correct": false, "explanation": "搭配：「提高」说的是水平、程度，不能说「提高心里并不认同」，句意不通。"}, {"text": "拒绝着", "is_correct": false, "explanation": "配价：「拒绝」的对象是请求或意见，「心里并不认同」不能作为被拒绝的对象，句意不通。"}], "explanations": {"垄断着": "语义：「垄断」是独占、控制，不能用来表示「心里并不认同」这种想法，句意不通。", "暗示着": "正确：「暗示着」表示不把话说出口、只通过动作透露想法，与「只字不提却反复划掉」的语境吻合。", "提高着": "搭配：「提高」说的是水平、程度，不能说「提高心里并不认同」，句意不通。", "拒绝着": "配价：「拒绝」的对象是请求或意见，「心里并不认同」不能作为被拒绝的对象，句意不通。"}, "sentence_index": 0, "correct_answer": "暗示着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经理下令暗示着大家明天加班。", "explanation": "这里应该用〈吩咐〉。“下令”要求把命令明说出来，“暗示”是不把话挑明，二者矛盾。"}, {"text": "他拍着桌子大声宣布，暗示着我明天来。", "explanation": "这里应该用〈通知〉。「大声宣布」是把事情明说出来，「暗示」是不挑明，二者矛盾。"}, {"text": "他逐字逐句地暗示着不同意。", "explanation": "这里应该用〈直言〉。“逐字逐句”要求原话照说，“暗示”是不把话挑明，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘲笑着", "is_correct": false, "explanation": "语义：“嘲笑”需要被笑的对象和可笑之处，“自己有急事”不能成为嘲笑的内容，句意不通。"}, {"text": "催促着", "is_correct": false, "explanation": "配价：“催促”的宾语是希望对方去做的事，“自己有急事”不能作为催促的对象。"}, {"text": "声明着", "is_correct": false, "explanation": "语义：「声明」是明确表态，与「不停地看手机」这种无声的间接方式相矛盾，且偏正式，不合语境。"}, {"text": "暗示着", "is_correct": true, "explanation": "正确：“暗示着”表示看手机的动作间接透露出自己有急事，与句意吻合。"}], "explanations": {"嘲笑着": "语义：“嘲笑”需要被笑的对象和可笑之处，“自己有急事”不能成为嘲笑的内容，句意不通。", "催促着": "配价：“催促”的宾语是希望对方去做的事，“自己有急事”不能作为催促的对象。", "声明着": "语义：「声明」是明确表态，与「不停地看手机」这种无声的间接方式相矛盾，且偏正式，不合语境。", "暗示着": "正确：“暗示着”表示看手机的动作间接透露出自己有急事，与句意吻合。"}, "sentence_index": 6, "correct_answer": "暗示着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校正式暗示着我们下周放假。", "explanation": "这里应该用〈通知〉。“正式”的通知要把内容明确说出，“暗示”是间接透露，二者矛盾。"}, {"text": "妈妈命令暗示着我别忘带钥匙。", "explanation": "这里应该用〈叮嘱〉。“命令”要求把话明确说出，“暗示”是不把话挑明，二者矛盾。"}, {"text": "会议上他直接念出结论，暗示着没有任何疑问。", "explanation": "这里应该用〈宣读〉。「直接念出结论」是明说，「暗示」是不挑明，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈摇摇头，暗示着了我不能去。", "corrected_sentence": "妈妈摇摇头，暗示着我不能去。", "error_description": "体标错误：“暗示着了”叠加了“着”和“了”。“暗示着”表示状态，“暗示了”表示完成，二者不能叠加；这里应改为“暗示着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的表情很严肃，暗示了着有事要发生。", "corrected_sentence": "他的表情很严肃，暗示着有事要发生。", "error_description": "体标错误：“了”被插在“暗示”和“着”之间。“暗示着”是一个整体的状态标记，中间不能插入“了”，应为“暗示着有事要发生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
