INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20054, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指在某个行业或领域中规模很大、实力很强、很有影响力的企业或人物。", "primary_collocate": null, "pronunciation": "jù tóu", "ipa": "tɕy˥˩ tʰou˧˥", "syllable_count": 2, "sentences": [{"text": "这种“技术公地”的繁荣，暗示着一种可能的未来：个人AI代理不再由科技巨头垄断定义，而是成为可被公众共同塑造的认知基础设施。", "target_word": "巨头", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司是手机行业的巨头。", "target_word": "巨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几家巨头都想开发新的电脑系统。", "target_word": "巨头", "complexity_tier": "T3", "furigana": "jǐ jiā jù tóu dōu xiǎng kāi fā xīn de diàn nǎo xì tǒng", "sentence_source": "generated"}, {"text": "他是石油行业有名的巨头。", "target_word": "巨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三大巨头今年都降低了价格。", "target_word": "巨头", "complexity_tier": "T3", "furigana": "sān dà jù tóu jīn nián dōu jiàng dī le jià gé", "sentence_source": "generated"}, {"text": "这个小公司想和行业巨头竞争。", "target_word": "巨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家巨头每年赚很多钱。", "target_word": "巨头", "complexity_tier": "T3", "furigana": "nà jiā jù tóu měi nián zhuàn hěn duō qián", "sentence_source": "generated"}, {"text": "那位老人曾经是银行业的巨头。", "target_word": "巨头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家巨头在全国开了上千家店。", "target_word": "巨头", "complexity_tier": "T3", "furigana": "zhè jiā jù tóu zài quán guó kāi le shàng qiān jiā diàn", "sentence_source": "generated"}, {"text": "巨头们开会讨论新的规则。", "target_word": "巨头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "科技巨头", "label": "复合"}, {"form": "行业巨头", "label": "复合"}], "register": "中性", "sense_fingerprint": "行业中规模大、影响力强的企业或人物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53f15428-b18b-410e-8301-878efd0cd378') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20054, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草根", "is_correct": false, "explanation": "语义：“草根”指普通民众，与“垄断定义”所含的强势地位正相反。"}, {"text": "原料", "is_correct": false, "explanation": "搭配：“垄断”搭配的是市场、资源等，“原料”不能被垄断定义。"}, {"text": "学徒", "is_correct": false, "explanation": "配价：“垄断定义”需要有权力的施事，“学徒”不具备这一条件。"}, {"text": "巨头", "is_correct": true, "explanation": "正确：“科技巨头”指规模大、实力强的科技企业，有能力垄断定义。"}], "explanations": {"草根": "语义：“草根”指普通民众，与“垄断定义”所含的强势地位正相反。", "原料": "搭配：“垄断”搭配的是市场、资源等，“原料”不能被垄断定义。", "学徒": "配价：“垄断定义”需要有权力的施事，“学徒”不具备这一条件。", "巨头": "正确：“科技巨头”指规模大、实力强的科技企业，有能力垄断定义。"}, "sentence_index": 0, "correct_answer": "巨头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的巨头比别人大一圈，戴帽子很费劲。", "explanation": "这里应该用〈大脑袋〉。“巨头”指行业或领域中规模和影响力都很大的企业或人物，不能用来形容头部的大小。"}, {"text": "这盆花的巨头开得很大，压得枝条都弯了。", "explanation": "这里应该用〈花盘〉。“巨头”指企业或人物，不能用来指花的头部。"}, {"text": "他的巨头很疼，需要去医院看看。", "explanation": "这里应该用〈脑袋〉。“巨头”指企业或人物，不能用来指人的头部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆一般不以营利为目的，不会“每年赚很多钱”。"}, {"text": "巨大", "is_correct": false, "explanation": "词类：“巨大”是形容词，不能接在“那家”之后作主语，句子不成立。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教室里的用品，不是企业，“那家黑板”说不通。"}, {"text": "巨头", "is_correct": true, "explanation": "正确：“那家巨头”指规模大、影响力强的企业，每年赚很多钱与之相符。"}], "explanations": {"图书馆": "语义：图书馆一般不以营利为目的，不会“每年赚很多钱”。", "巨大": "词类：“巨大”是形容词，不能接在“那家”之后作主语，句子不成立。", "黑板": "语义：“黑板”是教室里的用品，不是企业，“那家黑板”说不通。", "巨头": "正确：“那家巨头”指规模大、影响力强的企业，每年赚很多钱与之相符。"}, "sentence_index": 6, "correct_answer": "巨头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的巨头坏了，需要修理。", "explanation": "这里应该用〈机头〉。“巨头”指企业或人物，不能用来指机器的部件。"}, {"text": "这块蛋糕的巨头上有奶油。", "explanation": "这里应该用〈顶部〉。“巨头”指企业或人物，不能用来指蛋糕的上部。"}, {"text": "这只狗的巨头很大，看起来很凶。", "explanation": "这里应该用〈脑袋〉。“巨头”指企业或人物，不能用来指动物的头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是国内互联网行业的一只巨头。", "corrected_sentence": "她是国内互联网行业的一位巨头。", "error_description": "量词错误：“巨头”指人或企业，应用“位”或“个”，“只”用于动物等，不能用于此处；正确为“一位巨头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几家巨头们都在争夺这个市场。", "corrected_sentence": "几家巨头都在争夺这个市场。", "error_description": "多余后缀：“几家”已表示数量，后面不能再加复数后缀“们”；正确为“几家巨头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
