INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20055, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚精会神地看。", "primary_collocate": null, "pronunciation": "níng shì", "ipa": "niŋ˧˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "老师凝视着那份试卷，半天没有说话。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他凝视着远方，一句话也不说。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子凝视着窗外的雪，看得很认真。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人凝视这张旧照片，想起了往事。", "target_word": "凝视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她凝视着镜子里的自己。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生凝视着屏幕上的图像，眉头很紧。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家凝视了模特儿很久，才开始画。", "target_word": "凝视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他凝视过这幅画很多次。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明凝视着老师手里的实验瓶。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她凝视对方的眼睛，等着答案。", "target_word": "凝视", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "凝视着", "label": "体标"}, {"form": "凝视了", "label": "体标"}, {"form": "凝视过", "label": "体标"}, {"form": "凝視", "label": "繁体"}], "register": "书面", "sense_fingerprint": "聚精会神地看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb2f094-77d0-4e9f-8b03-ce3ad85679b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20055, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "凝视", "is_correct": true, "explanation": "正确：凝视 níng shì，意思是聚精会神地看。"}, {"text": "领事", "is_correct": false, "explanation": "lǐng（第三声）与 níng（第二声）声母与声调都不同，意思是外交官。"}, {"text": "明示", "is_correct": false, "explanation": "míng 与 níng 声母不同（m 与 n），意思是明确地表示出来。"}, {"text": "宁死", "is_correct": false, "explanation": "nìng 与 níng 声母韵母都相同，只差声调；sǐ（第三声）与 shì（第四声）声母不同（s 与 sh）。意思是宁可死去。"}, {"text": "凝思", "is_correct": false, "explanation": "sī 与 shì 声母不同（s 与 sh），声调也不同，意思是深入地思考。"}], "explanations": {"凝视": "正确：凝视 níng shì，意思是聚精会神地看。", "领事": "lǐng（第三声）与 níng（第二声）声母与声调都不同，意思是外交官。", "明示": "míng 与 níng 声母不同（m 与 n），意思是明确地表示出来。", "宁死": "nìng 与 níng 声母韵母都相同，只差声调；sǐ（第三声）与 shì（第四声）声母不同（s 与 sh）。意思是宁可死去。", "凝思": "sī 与 shì 声母不同（s 与 sh），声调也不同，意思是深入地思考。"}, "sentence_index": null, "correct_answer": "凝视"}, "level_3": {"options": [{"text": "凝视", "is_correct": true, "explanation": "正确：“老师凝视着那份试卷”中，“凝视”指聚精会神地看，与句意相合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，试卷不能煮，句意不成立。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲、戏曲，不能用于试卷，句意不成立。"}, {"text": "缝", "is_correct": false, "explanation": "语义：“缝”的对象是布料等物件，试卷不能缝，句意不成立。"}], "explanations": {"凝视": "正确：“老师凝视着那份试卷”中，“凝视”指聚精会神地看，与句意相合。", "煮": "语义：“煮”的对象是食物，试卷不能煮，句意不成立。", "唱": "搭配：“唱”的对象是歌曲、戏曲，不能用于试卷，句意不成立。", "缝": "语义：“缝”的对象是布料等物件，试卷不能缝，句意不成立。"}, "sentence_index": 0, "correct_answer": "凝视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他凝视了一圈房间，很快找到了空位。", "explanation": "这里应该用〈扫视〉。“扫视”是快速环顾一圈；“凝视”是长时间专注地看一处，不能用于环顾。"}, {"text": "他在网上凝视新闻，看得很快。", "explanation": "这里应该用〈浏览〉。在网上快速查看多条内容要用〈浏览〉；“凝视”强调长时间盯住一处，与“看得很快”矛盾。"}, {"text": "她认真凝视着音乐，陶醉其中。", "explanation": "这里应该用〈聆听〉。听音乐要用〈聆听〉；“凝视”只用于视觉，不用于听觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20055, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "凝视", "is_correct": true, "explanation": "正确：“画家……了模特儿很久，才开始画”需要表示专注地看，“凝视”最贴切。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”的对象是房间或地面，不能用于模特儿。"}, {"text": "叹", "is_correct": false, "explanation": "配价：“叹”是不及物动词，不带人作宾语。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”的对象是食物，不能用于模特儿。"}], "explanations": {"凝视": "正确：“画家……了模特儿很久，才开始画”需要表示专注地看，“凝视”最贴切。", "打扫": "语义：“打扫”的对象是房间或地面，不能用于模特儿。", "叹": "配价：“叹”是不及物动词，不带人作宾语。", "烤": "语义：“烤”的对象是食物，不能用于模特儿。"}, "sentence_index": 6, "correct_answer": "凝视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们约好在门口凝视，然后一起去吃饭。", "explanation": "这里应该用〈等候〉。“凝视”指聚精会神地看，不表示等人或见面；约好地点等人要用〈等候〉。"}, {"text": "她很快地凝视了对方一眼。", "explanation": "这里应该用〈瞥〉。“凝视”需要持续一段时间，与“很快”矛盾；快速看一眼要用〈瞥〉。"}, {"text": "她凝视着那碗粥，尝出了很甜的味道。", "explanation": "这里应该用〈品尝〉。“凝视”只表示用眼睛专注地看，尝味道要用〈品尝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20055, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她凝视着了海面，很久没有说话。", "corrected_sentence": "她凝视着海面，很久没有说话。", "error_description": "体标“了”多余：“凝视着”已有体标“着”，后面不能再加“了”，正确形式是“凝视着海面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20055, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她没有凝视没有那张照片，一直在想别的事。", "corrected_sentence": "她没有凝视那张照片，一直在想别的事。", "error_description": "否定词重复：一个句子里只需用一次“没有”，应说“她没有凝视那张照片”，不说“她没有凝视没有那张照片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
