INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20057, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指眼前所见的景象和心中所生的情感。", "primary_collocate": null, "pronunciation": "cǐ qíng cǐ jǐng", "ipa": "tsʰɨ˨˩˦ tɕʰiŋ˧˥ tsʰɨ˨˩˦ tɕiŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "此情此景下，OpenClaw是否成为范本已非核心议题；真正关键的是，人类能否在智能代理的镜像中，重新确认自身存在的主体性。", "target_word": "此情此景", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "看着此情此景，她忍不住流下了眼泪。", "target_word": "此情此景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此情此景让我想起了小时候的家乡。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站在海边，此情此景真让人难忘。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对此情此景，他一句话也说不出来。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "此情此景，我一辈子都不会忘记。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友们在月下喝茶聊天，此情此景十分温暖。", "target_word": "此情此景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人望着远去的火车，此情此景令人心酸。", "target_word": "此情此景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一首诗，记下此情此景。", "target_word": "此情此景", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "离开故乡多年，此情此景让他心潮起伏。", "target_word": "此情此景", "complexity_tier": "T3", "furigana": "cǐ qíng cǐ jǐng", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "眼前的景象和由此产生的心情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c16dde-b3e4-4ca0-a198-05848c7b5269') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20057, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此情此景", "is_correct": true, "explanation": "正确：“此情此景”指眼前景象和由此产生的感受，作“下”前的成分，与句意相合。"}, {"text": "屋檐下", "is_correct": false, "explanation": "语义：“屋檐下”指具体的地点，与讨论智能代理和人类主体性的语境不合。"}, {"text": "树荫下", "is_correct": false, "explanation": "语义：“树荫下”是具体场所，无法引出“是否成为范本”这一抽象议题。"}, {"text": "眼皮子底下", "is_correct": false, "explanation": "语域：“眼皮子底下”是口语说法，与书面的论述语体不搭。"}], "explanations": {"此情此景": "正确：“此情此景”指眼前景象和由此产生的感受，作“下”前的成分，与句意相合。", "屋檐下": "语义：“屋檐下”指具体的地点，与讨论智能代理和人类主体性的语境不合。", "树荫下": "语义：“树荫下”是具体场所，无法引出“是否成为范本”这一抽象议题。", "眼皮子底下": "语域：“眼皮子底下”是口语说法，与书面的论述语体不搭。"}, "sentence_index": 0, "correct_answer": "此情此景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "看着老照片，他发出了此情此景。", "explanation": "搭配：这里应该用〈感慨〉。“发出”可以搭配“感慨”，此情此景是景象和感情，不能被“发出”。"}, {"text": "他对音乐很有此情此景。", "explanation": "搭配：这里应该用〈感觉〉。“有”后接的是可以拥有的感受，此情此景是固定说法，不能说“有此情此景”。"}, {"text": "这份合同的此情此景很严格。", "explanation": "语义：这里应该用〈条款〉。此情此景指眼前的景象和心中的感情，合同条文没有景象，也没有感情，应说“这份合同的条款很严格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此情此景", "is_correct": true, "explanation": "正确：“此情此景”指眼前景象和由此产生的感受，可以作句子主语，与“十分温暖”的情感相合。"}, {"text": "寒风刺骨的冬夜", "is_correct": false, "explanation": "语义：“寒风刺骨”与“十分温暖”语义相反，与句中的温馨场景矛盾。"}, {"text": "冷冰冰的数字", "is_correct": false, "explanation": "搭配：“温暖”形容氛围或情感，不能用来形容数字。"}, {"text": "这份说明书", "is_correct": false, "explanation": "语义：说明书与朋友们月下喝茶聊天的温馨场景无关。"}], "explanations": {"此情此景": "正确：“此情此景”指眼前景象和由此产生的感受，可以作句子主语，与“十分温暖”的情感相合。", "寒风刺骨的冬夜": "语义：“寒风刺骨”与“十分温暖”语义相反，与句中的温馨场景矛盾。", "冷冰冰的数字": "搭配：“温暖”形容氛围或情感，不能用来形容数字。", "这份说明书": "语义：说明书与朋友们月下喝茶聊天的温馨场景无关。"}, "sentence_index": 6, "correct_answer": "此情此景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到这个消息，他的此情此景很沉重。", "explanation": "搭配：这里应该用〈心情〉。此情此景是固定说法，不能用“他的”修饰，应说“他的心情很沉重”。"}, {"text": "我在湖边看见了一把此情此景。", "explanation": "量词：这里应该用〈种〉，不能用〈把〉。〈把〉用于有柄的器物，此情此景指眼前的景象和心中的感情，不能计量为“一把”。"}, {"text": "这辆自行车的此情此景很轻。", "explanation": "语义：这里应该用〈重量〉。此情此景指眼前的景象和心中的感情，不能用来形容自行车的轻重，应说“这辆自行车的重量很轻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "走进老屋，此情此景把我红了眼眶。", "corrected_sentence": "走进老屋，此情此景让我红了眼眶。", "error_description": "用词错误：“红了眼眶”这一结构不能接“把”字，表示使役应用“让”，正确说法是“此情此景让我红了眼眶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "此情此景的让老人想起了往事。", "corrected_sentence": "此情此景让老人想起了往事。", "error_description": "多余的“的”：“此情此景”作主语后直接接动词“让”，不能再加“的”。正确说法是“此情此景让老人想起了往事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
