INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20070, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "单位时间内完成的工作量或工作效果。", "primary_collocate": null, "pronunciation": "gōng zuò xiào lǜ", "ipa": "kʊŋ˥ tswo˥˩ ɕjɑʊ˥˩ ly˥˩", "syllable_count": 4, "sentences": [{"text": "虽然这能提高工作效率，但也让一些工作岗位变得不再需要。", "target_word": "工作效率", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "新软件让我们的工作效率提高了很多。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作效率很高，下午就做完了。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室太吵会影响工作效率。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想用新系统提高工作效率。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每个月都会算一次工作效率。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "休息好了，工作效率才会高。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说团队的工作效率比去年高。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器大大提高了工厂的工作效率。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们换了新电脑，工作效率明显提高。", "target_word": "工作效率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "单位时间内完成的工作量或效果，可提高、可影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1f4a47-9547-4776-9185-3bf29a88cb1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作效率", "is_correct": true, "explanation": "正确：“提高”的对象应是做事的快慢和成果，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高不会因为新技术而提高，句意不通。"}, {"text": "食欲", "is_correct": false, "explanation": "语义：新技术不能提高食欲，与句中讲的效益无关。"}, {"text": "工龄", "is_correct": false, "explanation": "搭配：“提高工龄”不合搭配，工龄一般说“延长”或“计算”，与句意也不合。"}], "explanations": {"工作效率": "正确：“提高”的对象应是做事的快慢和成果，符合句意。", "身高": "语义：身高不会因为新技术而提高，句意不通。", "食欲": "语义：新技术不能提高食欲，与句中讲的效益无关。", "工龄": "搭配：“提高工龄”不合搭配，工龄一般说“延长”或“计算”，与句意也不合。"}, "sentence_index": 0, "correct_answer": "工作效率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们这个月的工作效率很大。", "explanation": "这里应该用〈工作量〉。效率用“高”或“低”来描述，工作量才说“大”或“多”。"}, {"text": "这个药的工作效率很好。", "explanation": "这里应该用〈效果〉。“工作效率”指做事的快慢和成果，药物的作用要说“效果”。"}, {"text": "他的工作效率很强。", "explanation": "这里应该用〈能力〉。“强”形容能力，效率只说“高”或“低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作效率", "is_correct": true, "explanation": "正确：休息好了，做事的快慢和成果会更好，符合句意。"}, {"text": "房价", "is_correct": false, "explanation": "语义：房价与人的休息无关，句意不通。"}, {"text": "血压", "is_correct": false, "explanation": "语义：休息好了血压通常会降低，与“才会高”的意思相反。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温由天气决定，与人的休息无关，句意不通。"}], "explanations": {"工作效率": "正确：休息好了，做事的快慢和成果会更好，符合句意。", "房价": "语义：房价与人的休息无关，句意不通。", "血压": "语义：休息好了血压通常会降低，与“才会高”的意思相反。", "气温": "语义：气温由天气决定，与人的休息无关，句意不通。"}, "sentence_index": 6, "correct_answer": "工作效率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工作效率很笨。", "explanation": "这里应该用〈头脑〉。“笨”形容人的头脑，“工作效率”只说“高”或“低”，不能用“笨”。"}, {"text": "这辆汽车的工作效率很快。", "explanation": "这里应该用〈速度〉。效率用“高”或“低”描述，车的快慢要说“速度”。"}, {"text": "他每天的工作效率很长。", "explanation": "这里应该用〈工作时间〉。“长”形容时间的多少，效率只说“高”或“低”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次改革让我们的工作效率多了。", "corrected_sentence": "这次改革让我们的工作效率提高了。", "error_description": "错误：“多了”，应为“提高了”。效率的变化说“提高”或“降低”，不说“多”，“多”用于数量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车间换了新设备，工作效率提高地很明显。", "corrected_sentence": "车间换了新设备，工作效率提高得很明显。", "error_description": "助词错误：表示程度的补语要用“得”，写作“提高得很明显”。“地”用于状语，不能放在动词后面作补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
