INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20071, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们从事工作的职位或位置。", "primary_collocate": null, "pronunciation": "gōng zuò gǎng wèi", "ipa": "kʊŋ˥ tswo˥˩ kɑŋ˨˩˦ weɪ˥˩", "syllable_count": 4, "sentences": [{"text": "虽然这能提高工作效率，但也让一些工作岗位变得不再需要。", "target_word": "工作岗位", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这家公司有三十个新的工作岗位。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找到了一个满意的工作岗位。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给毕业生提供了很多工作岗位。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作岗位需要会说英语的人。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工厂创造了一千多个工作岗位。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她换了工作岗位，现在在销售部。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个工作岗位都有自己的责任。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人想要稳定的工作岗位。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为公司关门，不少人失去了工作岗位。", "target_word": "工作岗位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "人在单位里担任的职位，可创造、可失去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a1f4a47-9547-4776-9185-3bf29a88cb1a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20071, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作岗位", "is_correct": true, "explanation": "这里指人从事工作的职位，“变得不再需要”的正是职位，与句意吻合。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是报酬，不能说“变得不再需要”，句中被取代的是职位。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是职位，不能被“让……变得不再需要”，与“工作效率”的语境不符。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能与“变得不再需要”搭配，句中应指职位。"}], "explanations": {"工作岗位": "这里指人从事工作的职位，“变得不再需要”的正是职位，与句意吻合。", "工资": "语义：工资是报酬，不能说“变得不再需要”，句中被取代的是职位。", "天气": "语义：天气不是职位，不能被“让……变得不再需要”，与“工作效率”的语境不符。", "年龄": "搭配：“年龄”不能与“变得不再需要”搭配，句中应指职位。"}, "sentence_index": 0, "correct_answer": "工作岗位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都要完成很多工作岗位。", "explanation": "此处把“工作岗位”当成了〈任务〉来用。工作岗位指职位本身，不能被“完成”；完成的是任务，应说“完成很多任务”。"}, {"text": "公司培养了很多工作岗位。", "explanation": "这里应该用〈人才〉。工作岗位是职位，不能被“培养”，应说培养人才。"}, {"text": "他的工作岗位是早上九点到晚上六点。", "explanation": "这里应该用〈工作时间〉。工作岗位指职位本身，不能用来表示上班的时段，时段要说工作时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20071, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作岗位", "is_correct": true, "explanation": "这里指她的工作职位，“换了”与后文“现在在销售部”前后呼应。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：发型是外貌，不是职位，与“现在在销售部”无关。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“换”后接的是可以更换的职位或物件，“天空”不能被更换，句意不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜不是职位，“换了眼镜，现在在销售部”前后语义不通。"}], "explanations": {"工作岗位": "这里指她的工作职位，“换了”与后文“现在在销售部”前后呼应。", "发型": "体貌：发型是外貌，不是职位，与“现在在销售部”无关。", "天空": "搭配：“换”后接的是可以更换的职位或物件，“天空”不能被更换，句意不通。", "眼镜": "语义：眼镜不是职位，“换了眼镜，现在在销售部”前后语义不通。"}, "sentence_index": 6, "correct_answer": "工作岗位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个工作岗位明天要去北京出差。", "explanation": "此处把“工作岗位”当成了〈人〉来用。职位本身不会出差，应说“他明天要去北京出差”。"}, {"text": "这个工作岗位昨晚考了全班第一名。", "explanation": "此处把“工作岗位”当成了〈学生〉来用。职位不会参加考试，应说“他昨晚考了全班第一名”。"}, {"text": "这个工作岗位长得很高，需要用梯子才能看到。", "explanation": "此处把“工作岗位”当成了〈人〉来用。职位不会长个子，“长得很高”说的是人的身高；职位说“高”指级别，不指身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个公司今年新增了两条工作岗位。", "corrected_sentence": "这个公司今年新增了两个工作岗位。", "error_description": "量词错误：“工作岗位”应与量词“个”搭配，“条”用于细长物体，不能计量岗位。正确说法是“两个工作岗位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家工厂裁掉了五颗工作岗位。", "corrected_sentence": "那家工厂裁掉了五个工作岗位。", "error_description": "量词错误：“工作岗位”应用量词“个”计量，“颗”用于粒状小物，不能计量职位。正确说法是“五个工作岗位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a5c2b32-6777-4a54-a7ca-acda70d34102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
