INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20077, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府依法向个人或企业征收的货币或实物，用于提供公共服务。", "primary_collocate": null, "pronunciation": "shuì", "ipa": "ʂweɪ˥˩", "syllable_count": 1, "sentences": [{"text": "同时，也有讨论认为，政府可能需要向使用人工智能的企业收更多的税，再用这些钱帮助受影响的工人。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我每个月都要交税。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司今年交了很多税。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西付的钱里，有一部分是税。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工资要先扣税，再发给他。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家用税来修路和建学校。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子的时候，要交一笔税。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "税太高，小店的老板很不高兴。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有交税，所以被罚了钱。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府今年少收了税，钱不够用。", "target_word": "税", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "税收", "label": "复合"}, {"form": "税款", "label": "复合"}, {"form": "纳税", "label": "复合"}], "register": "中性", "sense_fingerprint": "政府依法征收的钱，用于公共服务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '938960e5-f255-4470-af12-4986b8304979') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20077, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "税", "is_correct": true, "explanation": "税（shuì）：政府依法征收的钱，正是此义。"}, {"text": "水", "is_correct": false, "explanation": "shuǐ（第三声）与 shuì（第四声）声调不同，意思是水。"}, {"text": "谁", "is_correct": false, "explanation": "shuí（第二声）与 shuì（第四声）声调不同，意思是谁。"}, {"text": "岁", "is_correct": false, "explanation": "suì 与 shuì 声母不同（s 与 sh），意思是年龄单位。"}], "explanations": {"税": "税（shuì）：政府依法征收的钱，正是此义。", "水": "shuǐ（第三声）与 shuì（第四声）声调不同，意思是水。", "谁": "shuí（第二声）与 shuì（第四声）声调不同，意思是谁。", "岁": "suì 与 shuì 声母不同（s 与 sh），意思是年龄单位。"}, "sentence_index": null, "correct_answer": "税"}, "level_3": {"options": [{"text": "税", "is_correct": true, "explanation": "税：政府向企业征收的钱，与“向使用人工智能的企业收更多的税”相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是企业付给员工的钱，不是企业要交给政府的钱。"}, {"text": "房子", "is_correct": false, "explanation": "配价：“收”的宾语应是钱款，“房子”不能被“收”。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是学生交给学校的钱，与政府向企业征收的语境不符。"}], "explanations": {"税": "税：政府向企业征收的钱，与“向使用人工智能的企业收更多的税”相符。", "工资": "语义：工资是企业付给员工的钱，不是企业要交给政府的钱。", "房子": "配价：“收”的宾语应是钱款，“房子”不能被“收”。", "学费": "语义：学费是学生交给学校的钱，与政府向企业征收的语境不符。"}, "sentence_index": 0, "correct_answer": "税"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去医院看病，交了很多税。", "explanation": "这里应该用〈费用〉。税是政府依法征收的，看病交的钱是费用。"}, {"text": "他闯红灯，被警察收了很多税。", "explanation": "这里应该用〈罚款〉。税是依法征收用于公共服务的，违章被罚的钱是罚款。"}, {"text": "他每个月都把一部分工资交给希望小学，这笔钱是税。", "explanation": "这里应该用〈捐款〉。税是依法强制征收的，自愿交给学校的钱是捐款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20077, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "税", "is_correct": true, "explanation": "税（shuì）：政府依法征收的钱，正是此义。"}, {"text": "随", "is_correct": false, "explanation": "suí 与 shuì 声母不同（s 与 sh），声调也不同，意思是跟随。"}, {"text": "碎", "is_correct": false, "explanation": "suì 与 shuì 声母不同（s 与 sh），意思是破碎。"}, {"text": "瑞", "is_correct": false, "explanation": "ruì 与 shuì 声母不同（r 与 sh），意思是吉祥。"}], "explanations": {"税": "税（shuì）：政府依法征收的钱，正是此义。", "随": "suí 与 shuì 声母不同（s 与 sh），声调也不同，意思是跟随。", "碎": "suì 与 shuì 声母不同（s 与 sh），意思是破碎。", "瑞": "ruì 与 shuì 声母不同（r 与 sh），意思是吉祥。"}, "sentence_index": null, "correct_answer": "税"}, "level_3": {"options": [{"text": "税", "is_correct": true, "explanation": "税：政府征收的钱，与“买房子的时候，要交一笔税”相符。"}, {"text": "学费", "is_correct": false, "explanation": "语义：买房子时不交学费，学费是学生交给学校的钱。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是进入场所的费用，买房子时不会交门票。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：买房子时不会被罚款，“罚款”与买房的语境不符。"}], "explanations": {"税": "税：政府征收的钱，与“买房子的时候，要交一笔税”相符。", "学费": "语义：买房子时不交学费，学费是学生交给学校的钱。", "门票": "语义：门票是进入场所的费用，买房子时不会交门票。", "罚款": "语义：买房子时不会被罚款，“罚款”与买房的语境不符。"}, "sentence_index": 6, "correct_answer": "税"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去看展览，交了一笔税买门票。", "explanation": "这里应该用〈门票〉。税是政府依法征收的，进场买票的钱是门票。"}, {"text": "他每个月都向银行交一笔税，那是房贷的利息。", "explanation": "这里应该用〈利息〉。税是政府依法征收的，付给银行的房贷利息不是税。"}, {"text": "他去银行存钱，交了一笔税作为手续费。", "explanation": "这里应该用〈手续费〉。税是政府依法征收的，银行收取的服务费是手续费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚开公司，还没交税过。", "corrected_sentence": "他刚开公司，还没交过税。", "error_description": "错误在于“过”的位置。“过”应紧跟动词，说“交过税”，不能放在宾语“税”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的税交很及时。", "corrected_sentence": "这家店的税交得很及时。", "error_description": "错误在于“交很及时”缺少补语标记“得”。正确说法是“交得很及时”，“得”连接动词和补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5292da8-fd78-4714-8e8c-11cef0901870') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
