INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在生活、学习或工作中遇到的麻烦、阻碍或不容易解决的问题。", "primary_collocate": null, "pronunciation": "kùn nan", "ipa": "kʰwən˥˩ nan", "syllable_count": 2, "sentences": [{"text": "有些人年纪大了，学习上会遇到更多困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在生活中遇到了很多困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有困难的时候，可以给我打电话。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家一起努力，终于克服了这个困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚到国外的时候，语言是最大的困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师常常帮助学生解决学习上的困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司现在遇到了资金方面的困难。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要怕困难，只要不放弃，总会有办法。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家里有困难，所以没有去旅行。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对困难，我们不能只是等别人来帮忙。", "target_word": "困难", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词（一个困难）"}, {"form": "困难户", "label": "复合"}, {"form": "困難", "label": "繁体"}], "register": "中性", "sense_fingerprint": "困难：生活、学习、工作中遇到的麻烦与阻碍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3cf8ff-25c5-4d6f-b0ac-df147fb79767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20080, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "容易", "is_correct": false, "explanation": "词性：「容易」是形容词，不能作「遇到更多」的宾语，句子不通。"}, {"text": "困难", "is_correct": true, "explanation": "正确。「遇到更多困难」指学习时会碰到更多阻碍，与「年纪大了」的语境一致。"}, {"text": "机会", "is_correct": false, "explanation": "语义：「机会」是有利的时机，与「年纪大了、学习更费力」的语境相反。"}, {"text": "好处", "is_correct": false, "explanation": "语义：「好处」指有利的方面，与「遇到更多」的困境语境不符，句意不通。"}], "explanations": {"容易": "词性：「容易」是形容词，不能作「遇到更多」的宾语，句子不通。", "困难": "正确。「遇到更多困难」指学习时会碰到更多阻碍，与「年纪大了」的语境一致。", "机会": "语义：「机会」是有利的时机，与「年纪大了、学习更费力」的语境相反。", "好处": "语义：「好处」指有利的方面，与「遇到更多」的困境语境不符，句意不通。"}, "sentence_index": 0, "correct_answer": "困难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是找我的困难，真让人烦。", "explanation": "这里应该用〈毛病〉。「找毛病」指挑别人的缺点，「困难」不能这样用。"}, {"text": "这台电脑有困难，经常死机。", "explanation": "这里应该用〈故障〉。「困难」指人遇到的麻烦或阻碍，机器出问题应说「有故障」，不能说机器有困难。"}, {"text": "我遇到了一只困难，正在想办法。", "explanation": "这里应该用〈个〉。「只」用于动物或成对器官之一，不用于困难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20080, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好处", "is_correct": false, "explanation": "语义：「好处」指有利的方面，与「遇到」的负面处境相反，句意不通。"}, {"text": "困难", "is_correct": true, "explanation": "正确。「遇到……的困难」指资金上遇到的不容易之处，与句意一致。"}, {"text": "成功", "is_correct": false, "explanation": "搭配：「成功」一般说「取得成功」，不说「遇到……的成功」。"}, {"text": "成就", "is_correct": false, "explanation": "语义：「成就」指取得的成绩，与「遇到」的情境不符。"}], "explanations": {"好处": "语义：「好处」指有利的方面，与「遇到」的负面处境相反，句意不通。", "困难": "正确。「遇到……的困难」指资金上遇到的不容易之处，与句意一致。", "成功": "搭配：「成功」一般说「取得成功」，不说「遇到……的成功」。", "成就": "语义：「成就」指取得的成绩，与「遇到」的情境不符。"}, "sentence_index": 6, "correct_answer": "困难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他又惹了一大堆困难，大家都很头疼。", "explanation": "这里应该用〈麻烦〉。「惹麻烦」是常用说法，「惹困难」不通顺。"}, {"text": "他在考试中犯了一个困难。", "explanation": "这里应该用〈错误〉。「犯错误」是固定搭配，「犯困难」不通。"}, {"text": "这次他吃了不少困难。", "explanation": "这里应该用〈苦头〉。「吃苦头」是固定说法，「吃困难」不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他遇到了一只困难，但很快就解决了。", "corrected_sentence": "他遇到了一个困难，但很快就解决了。", "error_description": "量词错误：「困难」应搭配「个」，「只」多用于动物，不能用于困难。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们遇到了一位困难，但不能轻易放弃。", "corrected_sentence": "他们遇到了一个困难，但不能轻易放弃。", "error_description": "量词错误：「困难」应搭配「个」，「位」只用于人，不能用来数困难。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把家搬到别处去居住。", "primary_collocate": null, "pronunciation": "bān jiā", "ipa": "pan˥ tɕja˥", "syllable_count": 2, "sentences": [{"text": "而且，新工作可能在别的城市，搬家也不容易。", "target_word": "搬家", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我们下个月要搬家，现在正在收拾东西。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友今天搬家，我去帮他拿箱子。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为工作太远，他们决定搬家。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家以后，我离学校近多了。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们一家刚搬家，邻居还不认识。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子要上新学校，所以我们打算搬家。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家的时候，他的旧书差点丢了。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套房子太小了，我想搬家。", "target_word": "搬家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家前，妈妈把不用的衣服都送人了。", "target_word": "搬家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搬了家", "label": "体标：了"}, {"form": "搬过家", "label": "体标：过"}, {"form": "搬个家", "label": "离合：插入量词"}], "register": "中性", "sense_fingerprint": "搬家：把家搬到别处去居住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3cf8ff-25c5-4d6f-b0ac-df147fb79767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "搬家", "is_correct": true, "explanation": "搬家 bān jiā，把家搬到别处去居住，即本题目标词。"}, {"text": "半价", "is_correct": false, "explanation": "bàn jià 两个音节的声调都与 bān jiā 不同（第四声对第一声），意思是打折后的价格。"}, {"text": "本家", "is_correct": false, "explanation": "běn（第三声）与 bān（第一声）韵母 en 与 an 不同，声调也不同，意思是同一宗族的人。"}, {"text": "返家", "is_correct": false, "explanation": "fǎn（第三声）与 bān（第一声）声母 f 与 b 不同，声调也不同，意思是回到家里。"}], "explanations": {"搬家": "搬家 bān jiā，把家搬到别处去居住，即本题目标词。", "半价": "bàn jià 两个音节的声调都与 bān jiā 不同（第四声对第一声），意思是打折后的价格。", "本家": "běn（第三声）与 bān（第一声）韵母 en 与 an 不同，声调也不同，意思是同一宗族的人。", "返家": "fǎn（第三声）与 bān（第一声）声母 f 与 b 不同，声调也不同，意思是回到家里。"}, "sentence_index": null, "correct_answer": "搬家"}, "level_3": {"options": [{"text": "搬家", "is_correct": true, "explanation": "正确：“搬家”指整个家迁到别的城市居住，与“新工作在别的城市”相呼应。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”与句中的“新工作”矛盾，句意不通。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”意味着不再工作，与“新工作”矛盾，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：「游泳」与「新工作在别的城市」毫无关系，句意不通。"}], "explanations": {"搬家": "正确：“搬家”指整个家迁到别的城市居住，与“新工作在别的城市”相呼应。", "失业": "语义：“失业”与句中的“新工作”矛盾，句意不通。", "退休": "语义：“退休”意味着不再工作，与“新工作”矛盾，句意不通。", "游泳": "语义：「游泳」与「新工作在别的城市」毫无关系，句意不通。"}, "sentence_index": 0, "correct_answer": "搬家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上搬家去公司上班。", "explanation": "这里应该用〈通勤〉。搬家指长期迁居住所，每天往返公司上班不叫搬家。"}, {"text": "我们春节搬家回老家过节。", "explanation": "这里应该用〈回老家〉。搬家指长期迁居，春节回老家探亲不叫搬家。"}, {"text": "他从书房搬家到了卧室。", "explanation": "这里不能用“搬家”。搬家指全家迁入另一处住所，同一套房子里换房间不说搬家，要说“搬到卧室”之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "搬家", "is_correct": true, "explanation": "正确：“搬家”指全家迁居，与“新学校”和“打算”相呼应。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指去学校读书，“我们”（家长）打算上学，句意不通。"}, {"text": "离婚", "is_correct": false, "explanation": "语义：“离婚”与“孩子要上新学校”的安排无关，句意不通。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”需要带搬运的对象，单用“我们打算搬运”不完整。"}], "explanations": {"搬家": "正确：“搬家”指全家迁居，与“新学校”和“打算”相呼应。", "上学": "语义：“上学”指去学校读书，“我们”（家长）打算上学，句意不通。", "离婚": "语义：“离婚”与“孩子要上新学校”的安排无关，句意不通。", "搬运": "配价：“搬运”需要带搬运的对象，单用“我们打算搬运”不完整。"}, "sentence_index": 6, "correct_answer": "搬家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这批货物今天搬家了。", "explanation": "这里应该用〈搬运〉。搬家的主语必须是人或家庭，货物不能搬家，要说“搬运”。"}, {"text": "他从这所学校搬家到另一所学校。", "explanation": "这里应该用〈转学〉。学生换学校要用转学，搬家只指家庭住所的迁移。"}, {"text": "病人昨天搬家到了市中心医院。", "explanation": "这里应该用〈转院〉。搬家只指家庭住所的迁移，病人换医院要用转院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下个月搬家北京。", "corrected_sentence": "我们下个月搬家到北京。", "error_description": "“搬家”后面接表示去向的地点时，要用介词“到”或“去”引出；这里漏了“到”，应说“搬家到北京”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把搬家以后，还没买新沙发。", "corrected_sentence": "我们搬家以后，还没买新沙发。", "error_description": "“搬家”是不及物的离合词，前面不能加“把”。“把”字句要求“把+宾语+动词”，这里的结构不成立，应去掉“把”，说“搬家以后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
