INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20082, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在预定时间或事情发生之前做好必要的准备工作。", "primary_collocate": null, "pronunciation": "tí qián zhǔn bèi", "ipa": "tʰi˧˥ tɕʰjɛn˧˥ ʈʂuən˨˩˦ pei˥˩", "syllable_count": 4, "sentences": [{"text": "专家提醒，社会必须提前准备，否则贫富差距可能会变得更大。", "target_word": "提前准备", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "明天要考试，你今晚最好提前准备。", "target_word": "提前准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行前，我们要提前准备好护照和机票。", "target_word": "提前准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司提前准备了会议要用的材料。", "target_word": "提前准备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台风要来了，居民们都在提前准备食物和水。", "target_word": "提前准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试以前，她提前准备了很多问题。", "target_word": "提前准备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，上课前要提前准备课本。", "target_word": "提前准备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈为春节提前准备了很多好吃的。", "target_word": "提前准备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人六点到，我们得提前准备晚饭。", "target_word": "提前准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛下个月开始，球队已经开始提前准备了。", "target_word": "提前准备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提前准备了", "label": "体标"}, {"form": "提前准备过", "label": "体标"}, {"form": "提前准备好", "label": "复合"}], "register": "中性", "sense_fingerprint": "事情发生或预定时间之前，先做好必要的准备工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3cf8ff-25c5-4d6f-b0ac-df147fb79767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提前准备", "is_correct": true, "explanation": "正确：“提前准备”指在事情发生之前做好准备，与“必须……否则贫富差距变大”相呼应。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“必须做好准备”的意思相反，句意不通。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“必须”以及“否则贫富差距可能变大”的逻辑相矛盾。"}, {"text": "忽视", "is_correct": false, "explanation": "语义：「忽视」与「社会必须……否则贫富差距可能变大」的要求相反，句意不通。"}], "explanations": {"提前准备": "正确：“提前准备”指在事情发生之前做好准备，与“必须……否则贫富差距变大”相呼应。", "忘记": "语义：“忘记”与“必须做好准备”的意思相反，句意不通。", "放弃": "语义：“放弃”与“必须”以及“否则贫富差距可能变大”的逻辑相矛盾。", "忽视": "语义：「忽视」与「社会必须……否则贫富差距可能变大」的要求相反，句意不通。"}, "sentence_index": 0, "correct_answer": "提前准备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议结束以后，我们才提前准备会议材料。", "explanation": "这里应该用〈补充〉。“提前准备”指事情发生之前做准备，会议结束后材料只能补充，不能说提前准备。"}, {"text": "老师提前准备了这次考试的成绩。", "explanation": "这里应该用〈公布〉。“提前准备”指做准备工作，不能用来指事先发布考试成绩。"}, {"text": "这次地震提前准备了一周。", "explanation": "这里应该用〈发生〉。「准备」指做准备工作，地震是自然现象，不能被“准备”，只能说“提前发生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提前准备", "is_correct": true, "explanation": "正确：“提前准备”指在上课前做好准备，与“上课前要……课本”相呼应。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”与“上课前要准备课本”的目的相反，句意不通。"}, {"text": "撕掉", "is_correct": false, "explanation": "语义：“撕掉”与准备课本的意思相反，老师不会在这里要求撕掉课本。"}, {"text": "提前", "is_correct": false, "explanation": "配价：“提前”是修饰动词的状语，后面不能直接接“课本”作宾语，句意不通。"}], "explanations": {"提前准备": "正确：“提前准备”指在上课前做好准备，与“上课前要……课本”相呼应。", "丢失": "语义：“丢失”与“上课前要准备课本”的目的相反，句意不通。", "撕掉": "语义：“撕掉”与准备课本的意思相反，老师不会在这里要求撕掉课本。", "提前": "配价：“提前”是修饰动词的状语，后面不能直接接“课本”作宾语，句意不通。"}, "sentence_index": 6, "correct_answer": "提前准备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "气象台提前准备了明天的天气。", "explanation": "这里应该用〈预报〉。“准备”指做准备工作，不能用来指事先发布天气情况。"}, {"text": "医生提前准备了流感。", "explanation": "这里应该用〈预防〉。“准备”不能用于疾病本身，预先防止疾病要用预防。"}, {"text": "考试时间被提前准备了一周。", "explanation": "这里应该用〈调整〉。“提前准备”指做准备工作，不能用于时间本身；考试时间的变动要说“调整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天就要出发了，我们今晚得提前准备过行李。", "corrected_sentence": "明天就要出发了，我们今晚得提前准备行李。", "error_description": "错误形式：“提前准备过行李”。正确形式：“提前准备行李”。“过”表示曾经有过的经历，与“得”所表示的必须去做的事（将要发生）不搭配，应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们已经把提前准备好了晚饭。", "corrected_sentence": "他们已经提前准备好了晚饭。", "error_description": "“提前准备”是状中结构的动词短语，前面不能加“把”。“把”字句要求“把+宾语+动词”，这里结构不成立，应去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
