INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20085, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对问题进行深入、细致的思维活动。", "primary_collocate": null, "pronunciation": "sī kǎo", "ipa": "sɹ̩˥ kʰɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们必须思考：在人工智能时代，如何让更多人受益？", "target_word": "思考", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "做决定以前，你要好好思考。", "target_word": "思考", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师请大家思考这个问题。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐在窗边，安静地思考着未来。", "target_word": "思考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困难时，先停下来思考。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书让我思考了很多事情。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习不只是记住，还要学会思考。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他思考了很久，还是不知道怎么回答。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哲学家喜欢思考人生的意义。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子需要时间独立思考。", "target_word": "思考", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "思考了", "label": "体标"}, {"form": "思考着", "label": "体标"}, {"form": "思考过", "label": "体标"}, {"form": "思考思考", "label": "重叠"}], "register": "中性", "sense_fingerprint": "对问题进行深入、细致的思维活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f3cf8ff-25c5-4d6f-b0ac-df147fb79767') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20085, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思考", "is_correct": true, "explanation": "正确：“思考”表示对问题进行深入的思维活动，与“如何让更多人受益”的提问相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“：”后的问句作宾语。"}, {"text": "购买", "is_correct": false, "explanation": "配价：“购买”要求具体的物品作宾语，不能接一个问句。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与人工智能和受益的讨论无关，句意不通。"}], "explanations": {"思考": "正确：“思考”表示对问题进行深入的思维活动，与“如何让更多人受益”的提问相符。", "睡觉": "配价：“睡觉”是不及物动词，不能带“：”后的问句作宾语。", "购买": "配价：“购买”要求具体的物品作宾语，不能接一个问句。", "唱歌": "语义：“唱歌”与人工智能和受益的讨论无关，句意不通。"}, "sentence_index": 0, "correct_answer": "思考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很思考远方的父母。", "explanation": "这里应该用〈思念〉。思考是动词，一般不能受程度副词「很」修饰；想念亲人应说「很思念」。"}, {"text": "我思考喝一杯水。", "explanation": "这里应该用〈想〉。思考指动脑子想问题，不能表示想要做某事。"}, {"text": "他思考房间里的灰尘。", "explanation": "这里应该用〈打扫〉。思考是动脑子想问题，不能表示清扫灰尘这个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思考", "is_correct": true, "explanation": "正确：“学会思考”与前句“不只是记住”形成对比，句意通顺。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是自然现象，人不能学会下雨。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”表示事情出现，不能作为人主动学会的动作，不能接“学会”。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是生病，不是可以学会的技能。"}], "explanations": {"思考": "正确：“学会思考”与前句“不只是记住”形成对比，句意通顺。", "下雨": "语义：“下雨”是自然现象，人不能学会下雨。", "发生": "配价：“发生”表示事情出现，不能作为人主动学会的动作，不能接“学会”。", "感冒": "语义：“感冒”是生病，不是可以学会的技能。"}, "sentence_index": 6, "correct_answer": "思考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里很思考菜谱。", "explanation": "这里应该用〈看〉。「看菜谱」指阅读；思考是动脑子想问题，一般不能受程度副词「很」修饰。"}, {"text": "他思考了一双新鞋。", "explanation": "这里应该用〈穿〉。思考是动脑子想问题，不能表示穿鞋这个动作。"}, {"text": "他每天思考两顿饭。", "explanation": "这里应该用〈吃〉。思考不能表示吃饭的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "做决定以前，我们要好好思考了一下。", "corrected_sentence": "做决定以前，我们要好好思考一下。", "error_description": "错误在「了」：「要好好思考」指尚未发生的动作，与表示完成的「了」相矛盾；应去掉「了」，说「思考一下」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要认真得思考这个问题。", "corrected_sentence": "我们要认真思考这个问题。", "error_description": "错误形式：“认真得思考”。正确形式：“认真思考”。“得”是补语标记，不能放在动词前作状语，此处应直接说“认真思考”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a272a790-830f-4bd5-a3e2-ce1c82265682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受害", "is_correct": true, "explanation": "受害：与“受益”相反，指遭受损害"}, {"text": "散步", "is_correct": false, "explanation": "散步：与“受益”没有反义关系"}, {"text": "研究", "is_correct": false, "explanation": "研究：与“受益”没有反义关系"}, {"text": "出发", "is_correct": false, "explanation": "出发：与“受益”没有反义关系"}], "correct_answer": "受害", "explanations": {"受害": "受害：与“受益”相反，指遭受损害", "散步": "散步：与“受益”没有反义关系", "研究": "研究：与“受益”没有反义关系", "出发": "出发：与“受益”没有反义关系"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "受损", "is_correct": true, "explanation": "受损：与“受益”相反，指遭受损失或伤害"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：与“受益”没有反义关系"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：与“受益”没有反义关系"}, {"text": "启程", "is_correct": false, "explanation": "启程：与“受益”没有反义关系"}], "correct_answer": "受损", "explanations": {"受损": "受损：与“受益”相反，指遭受损失或伤害", "唱歌": "唱歌：与“受益”没有反义关系", "讨论": "讨论：与“受益”没有反义关系", "启程": "启程：与“受益”没有反义关系"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到好处；获得利益。", "primary_collocate": null, "pronunciation": "shòu yì", "ipa": "ʂoʊ⁵¹ i⁵¹", "syllable_count": 2, "sentences": [{"text": "我们必须思考：在人工智能时代，如何让更多人受益？", "target_word": "受益", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "多读书的人，一辈子都会受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个新政策让很多农民受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的建议让我受益很多。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从这次谈话中受益不少。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新路修好后，附近的居民都受益了。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经常运动，身体会受益。", "target_word": "受益", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们从免费午餐中受益。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从朋友的经验里受益过。", "target_word": "受益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好英语，你以后会受益的。", "target_word": "受益", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "受益人", "label": "复合"}, {"form": "受益者", "label": "复合"}, {"form": "受益了", "label": "体标"}], "register": "中性", "sense_fingerprint": "从某事或某人那里得到好处、获得利益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ade6ce41-a0e9-49cf-8af0-3740ac5cd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益（shòu yì）：得到好处，与听到的读音一致"}, {"text": "收益", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，收益指所得的利润或收入"}, {"text": "手艺", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，手艺指手工技能"}, {"text": "寿衣", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，寿衣指为去世者准备的衣服"}, {"text": "兽医", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，兽医指给动物看病的人"}], "explanations": {"受益": "受益（shòu yì）：得到好处，与听到的读音一致", "收益": "shōu（第一声）与 shòu（第四声）声调不同，收益指所得的利润或收入", "手艺": "shǒu（第三声）与 shòu（第四声）声调不同，手艺指手工技能", "寿衣": "yī（第一声）与 yì（第四声）声调不同，寿衣指为去世者准备的衣服", "兽医": "yī（第一声）与 yì（第四声）声调不同，兽医指给动物看病的人"}, "sentence_index": null, "correct_answer": "受益"}, "level_3": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益：得到好处，符合“让更多人……”的语境"}, {"text": "受伤", "is_correct": false, "explanation": "语义：“受伤”指遭受伤害，与这里要表达的好处相反"}, {"text": "吃亏", "is_correct": false, "explanation": "语义：“吃亏”指遭受损失，与“受益”的意思相反"}, {"text": "挨骂", "is_correct": false, "explanation": "语义：“挨骂”指受到责备，与“让更多人……”所指的好处不符，句意不通。"}], "explanations": {"受益": "受益：得到好处，符合“让更多人……”的语境", "受伤": "语义：“受伤”指遭受伤害，与这里要表达的好处相反", "吃亏": "语义：“吃亏”指遭受损失，与“受益”的意思相反", "挨骂": "语义：“挨骂”指受到责备，与“让更多人……”所指的好处不符，句意不通。"}, "sentence_index": 0, "correct_answer": "受益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次培训让我受益了很多经验。", "explanation": "这里应该用〈获得〉。受益是不及物动词，后面不能直接带“经验”作宾语；获得可以带宾语"}, {"text": "这家公司今年的受益增加了很多。", "explanation": "这里应该用〈收益〉。收益是名词，指所得的利润；受益是动词，不能作名词用"}, {"text": "他因为长期熬夜，身体受益了很多。", "explanation": "这里应该用〈受损〉。受益表示得到好处，长期熬夜带来的是伤害，应说“受损”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受益", "is_correct": true, "explanation": "受益：得到好处，符合“经常运动”的健康效果"}, {"text": "衰老", "is_correct": false, "explanation": "语义：经常运动有助于延缓衰老，“衰老”与好处相反"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是坏结果，与“经常运动”的好处相反"}, {"text": "变丑", "is_correct": false, "explanation": "体貌：“变丑”说的是外貌，与“身体会……”的健康语境不合"}], "explanations": {"受益": "受益：得到好处，符合“经常运动”的健康效果", "衰老": "语义：经常运动有助于延缓衰老，“衰老”与好处相反", "生病": "语义：“生病”是坏结果，与“经常运动”的好处相反", "变丑": "体貌：“变丑”说的是外貌，与“身体会……”的健康语境不合"}, "sentence_index": 6, "correct_answer": "受益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动对身体受益。", "explanation": "这里应该用〈有益〉。“对身体”之后要接形容词“有益”；受益是动词，表示得到好处，不能这样用"}, {"text": "这个月我的体重受益了三公斤。", "explanation": "这里应该用〈增加〉。受益指人得到好处，体重增加是数量变化，不能说受益；数量变化要用增加"}, {"text": "这个假期我们受益了很多乐趣。", "explanation": "这里应该用〈享受〉。受益是不及物动词，不能直接带“乐趣”作宾语；享受可以带宾语"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次培训被我受益很多。", "corrected_sentence": "这次培训让我受益很多。", "error_description": "错误：用“被”字句。“受益”是不及物动词，不能用于被动结构，应说“这次培训让我受益很多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们从这次活动中受益着不少。", "corrected_sentence": "学生们从这次活动中受益了不少。", "error_description": "错误：体标用错。表示已经得到的好处要用“了”，应说“从这次活动中受益了不少”，不说“受益着不少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c60899f1-e56a-4535-96d2-aa943636429c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
