INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20087, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "信息准确清楚，没有错误或混乱", "primary_collocate": null, "pronunciation": "gān jìng", "ipa": "kan˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "数据要干净，不能乱。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这份表格里的数据很干净，没有错误。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据清理以后，变得很干净。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代码写得很干净，别人一看就懂。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名单整理得很干净，每个名字都清楚。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把数据弄干净，再做分析。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做账要做得干净，每一笔都不能错。", "target_word": "干净", "complexity_tier": "T3", "furigana": "gān jìng", "sentence_source": "generated"}, {"text": "这些资料不干净，里面有很多重复的内容。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干净的数据能让结果更准确。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "笔记写得很干净，没有一处错误。", "target_word": "干净", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干净了", "label": "体标"}, {"form": "不干净", "label": "否定"}, {"form": "更干净", "label": "比较"}], "register": "中性", "sense_fingerprint": "数据、资料等信息准确清楚、没有错误混乱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e5e0e04-19d0-4826-8ae8-48040290f7a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20087, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干净", "is_correct": true, "explanation": "干净指数据没有错误或混乱，与“不能乱”的要求相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容人多声响大，数据不能热闹，与“不能乱”相冲突。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容物体的质地，不能用来形容数据。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或颜色，不能用来形容数据的质量。"}], "explanations": {"干净": "干净指数据没有错误或混乱，与“不能乱”的要求相符。", "热闹": "语义：“热闹”形容人多声响大，数据不能热闹，与“不能乱”相冲突。", "柔软": "搭配：“柔软”形容物体的质地，不能用来形容数据。", "明亮": "语义：“明亮”形容光线或颜色，不能用来形容数据的质量。"}, "sentence_index": 0, "correct_answer": "干净"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的温度很干净。", "explanation": "这里应该用〈适宜〉。温度要说高低或舒适与否，干净只用于信息或资料没有错误、混乱。"}, {"text": "这只猫的脾气很干净。", "explanation": "这里应该用〈温顺〉。脾气要说温顺或暴躁，干净不能形容性情。"}, {"text": "这场比赛的观众人数很干净。", "explanation": "这里应该用〈多〉。人数的多少要说多或少，干净只用于信息或资料没有错误、混乱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20087, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干净", "is_correct": true, "explanation": "干净指账目没有错误或混乱，与“每一笔都不能错”的要求一致。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”指做事马虎，与“每一笔都不能错”的要求相冲突。"}, {"text": "花哨", "is_correct": false, "explanation": "语义：“花哨”形容外表华丽，不能用来形容做账的质量。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多形容声音或笑容，不能用于做账。"}], "explanations": {"干净": "干净指账目没有错误或混乱，与“每一笔都不能错”的要求一致。", "粗糙": "语义：“粗糙”指做事马虎，与“每一笔都不能错”的要求相冲突。", "花哨": "语义：“花哨”形容外表华丽，不能用来形容做账的质量。", "甜美": "搭配：“甜美”多形容声音或笑容，不能用于做账。"}, "sentence_index": 6, "correct_answer": "干净"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布的价格很干净。", "explanation": "这里应该用〈便宜〉。价格的高低要说贵或便宜，干净只用于信息或资料没有错误、混乱。"}, {"text": "这条河的水位很干净。", "explanation": "这里应该用〈高〉。水位的高低要说高或低，干净只用于信息或资料没有错误、混乱。"}, {"text": "这份报告的字数很干净。", "explanation": "这里不能用〈干净〉形容字数，应说“合适”或“够”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把这份名单干净，再交给他。", "corrected_sentence": "请把这份名单弄干净，再交给他。", "error_description": "错误形式：把这份名单干净；正确形式：把这份名单弄干净。“把”字句中的“干净”作结果，前面需要动词，如“弄”，不能直接跟在宾语后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些数据我还弄没干净。", "corrected_sentence": "这些数据我还没弄干净。", "error_description": "错误形式：还弄没干净；正确形式：还没弄干净。否定词“没”要放在动词“弄”之前，表示动作还没有完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独享", "is_correct": true, "explanation": "独享：独自享有，不给别人用，与“分享”相对。"}, {"text": "修改", "is_correct": false, "explanation": "“修改”指改动内容，与“分享”没有相对关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“分享”不构成反义。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指使有条理，与“分享”不构成反义。"}], "correct_answer": "独享", "explanations": {"独享": "独享：独自享有，不给别人用，与“分享”相对。", "修改": "“修改”指改动内容，与“分享”没有相对关系。", "观察": "“观察”指仔细看，与“分享”不构成反义。", "整理": "“整理”指使有条理，与“分享”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独享", "is_correct": true, "explanation": "独享：独自享有，不给别人用，与“分享”相对。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把东西从一处移到另一处，与“分享”不构成反义。"}, {"text": "邀请", "is_correct": false, "explanation": "“邀请”指请人来或参加，与“分享”不构成反义。"}, {"text": "打印", "is_correct": false, "explanation": "“打印”指把文件印在纸上，与“分享”不构成反义。"}], "correct_answer": "独享", "explanations": {"独享": "独享：独自享有，不给别人用，与“分享”相对。", "搬运": "“搬运”指把东西从一处移到另一处，与“分享”不构成反义。", "邀请": "“邀请”指请人来或参加，与“分享”不构成反义。", "打印": "“打印”指把文件印在纸上，与“分享”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将信息或资源提供给他人使用", "primary_collocate": null, "pronunciation": "fēn xiǎng", "ipa": "fən˥ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "比如，系统需要说明哪些数据用来改进产品，哪些可能分享给合作伙伴。", "target_word": "分享", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "老师把这份学习资料分享给了全班同学。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以把这个视频分享给朋友看。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要求员工不要随便分享客户的信息。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在网上分享了很多学习方法。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个文件分享给我，我也想看看。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他愿意分享自己的旅行照片和路线。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以和别人分享电脑里的文件。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李分享了一个很有用的网站。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家把有用的资料分享到群里。", "target_word": "分享", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分享了", "label": "体标"}, {"form": "分享过", "label": "体标"}, {"form": "分享着", "label": "体标"}, {"form": "分享会", "label": "复合"}, {"form": "分享者", "label": "复合"}], "register": "中性", "sense_fingerprint": "分享：把信息、资料等资源提供给他人使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e5e0e04-19d0-4826-8ae8-48040290f7a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分享", "is_correct": true, "explanation": "分享 fēn xiǎng：把信息、资源提供给他人使用，正确答案。"}, {"text": "芬香", "is_correct": false, "explanation": "芬香 fēn xiāng（第一声）与 分享 fēn xiǎng（第三声）第二个音节声调不同，意思是香气浓郁。"}, {"text": "焚香", "is_correct": false, "explanation": "焚香 fén xiāng（第二声、第一声）与 分享 fēn xiǎng 两个音节的声调都不同，意思是点燃香料。"}, {"text": "分项", "is_correct": false, "explanation": "分项 fēn xiàng（第四声）与 分享 fēn xiǎng（第三声）第二个音节声调不同，意思是按项目分开。"}], "explanations": {"分享": "分享 fēn xiǎng：把信息、资源提供给他人使用，正确答案。", "芬香": "芬香 fēn xiāng（第一声）与 分享 fēn xiǎng（第三声）第二个音节声调不同，意思是香气浓郁。", "焚香": "焚香 fén xiāng（第二声、第一声）与 分享 fēn xiǎng 两个音节的声调都不同，意思是点燃香料。", "分项": "分项 fēn xiàng（第四声）与 分享 fēn xiǎng（第三声）第二个音节声调不同，意思是按项目分开。"}, "sentence_index": null, "correct_answer": "分享"}, "level_3": {"options": [{"text": "分享", "is_correct": true, "explanation": "分享：把数据提供给合作伙伴使用，与句中“可能……给合作伙伴”相符。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”与“分享”意思相反，句意变成不让合作伙伴知道，与“说明”的语境不符。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”是护着、不受侵害，与把数据交给伙伴的意思不合。"}, {"text": "收集", "is_correct": false, "explanation": "语义：“收集”是聚拢起来，不是提供给别人，与“给合作伙伴”的意思不合。"}], "explanations": {"分享": "分享：把数据提供给合作伙伴使用，与句中“可能……给合作伙伴”相符。", "隐瞒": "语义：“隐瞒”与“分享”意思相反，句意变成不让合作伙伴知道，与“说明”的语境不符。", "保护": "语义：“保护”是护着、不受侵害，与把数据交给伙伴的意思不合。", "收集": "语义：“收集”是聚拢起来，不是提供给别人，与“给合作伙伴”的意思不合。"}, "sentence_index": 0, "correct_answer": "分享"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸和妈妈一起分享家务。", "explanation": "这里应该用〈分担〉。分享指把信息、资源提供给他人使用，家务要用分担。"}, {"text": "警察分享了这批货。", "explanation": "这里应该用〈没收〉。没收是把物品强行收归公有，分享是把东西提供给他人使用，警察不会把货分享给别人。"}, {"text": "老师分享了那个学生。", "explanation": "这里应该用〈表扬〉。分享只能用于把东西或资料提供给他人使用，指称人时要用〈表扬〉这类动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分享", "is_correct": true, "explanation": "分享：把自己的照片和路线提供给别人看，与句意相符。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”只接食物，不能接“照片和路线”。"}, {"text": "咀嚼", "is_correct": false, "explanation": "语义：“咀嚼”指嚼碎食物，与照片、路线的意思不合。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：“吞下”指咽进口中的东西，与照片、路线不相容。"}], "explanations": {"分享": "分享：把自己的照片和路线提供给别人看，与句意相符。", "煮": "搭配：“煮”只接食物，不能接“照片和路线”。", "咀嚼": "语义：“咀嚼”指嚼碎食物，与照片、路线的意思不合。", "吞下": "语义：“吞下”指咽进口中的东西，与照片、路线不相容。"}, "sentence_index": 6, "correct_answer": "分享"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这首歌分享在手机里。", "explanation": "这里应该用〈收藏〉。收藏是自己留着保存，分享要提供给他人使用。"}, {"text": "大火分享了整座房子。", "explanation": "这里应该用〈摧毁〉。摧毁是毁坏东西，分享是把东西提供给他人使用，大火不会把房子分享给谁。"}, {"text": "他按时把书分享给了那张桌子。", "explanation": "这里应该用〈放在〉。分享的对象应是能使用东西的人，桌子不能接受分享，书应放在桌上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这份报告分享了给同事。", "corrected_sentence": "我把这份报告分享给了同事。", "error_description": "错误：“分享了给”；正确：“分享给了”。“给”是分享的补充成分，“了”应放在“给”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不分享过这个网站。", "corrected_sentence": "他没分享过这个网站。", "error_description": "错误：“不分享过”；正确：“没分享过”。表示没有过某种经历要用“没……过”，“不”不能与体标“过”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
