INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20095, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "属于某个领域特有的术语或知识", "primary_collocate": null, "pronunciation": "zhuān yè", "ipa": "ʈʂwan˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "因此，文字要简单清楚，避免用太专业的词。", "target_word": "专业", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这本书里有很多专业词，我看不懂。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用了一些专业的话，病人没听懂。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写给孩子的书，不要用专业术语。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章专业知识太多，我读了三遍。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "律师说了几个专业词，我只好上网查。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师先把这些专业词写在黑板上。", "target_word": "专业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看专业书的时候，我常常要查词典。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网站有专业词的解释，很方便。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说明书里的专业术语太多，大家都看不懂。", "target_word": "专业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "專業", "label": "繁体"}, {"form": "专业知识", "label": "复合"}], "register": "中性", "sense_fingerprint": "专业·形容词·属于某领域的特有术语或知识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79963f23-daa7-47ea-a422-83820dc3fd66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20095, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专业", "is_correct": true, "explanation": "专业：指属于某领域的术语。“太……的词”说的是词语过于术语化，与“避免”的语境相合。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场面或气氛，不能用来形容词语。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身材或高度，不能用来形容词语的难易。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“湿”形容含水多，不能用来形容词语。"}], "explanations": {"专业": "专业：指属于某领域的术语。“太……的词”说的是词语过于术语化，与“避免”的语境相合。", "热闹": "搭配：“热闹”形容场面或气氛，不能用来形容词语。", "矮": "体貌：“矮”形容身材或高度，不能用来形容词语的难易。", "湿": "搭配：“湿”形容含水多，不能用来形容词语。"}, "sentence_index": 0, "correct_answer": "专业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书写得很专业，孩子也能看懂。", "explanation": "这里应该用〈通俗〉。“专业”指术语多、难懂，与“孩子也能看懂”矛盾；“通俗”才表示易懂。"}, {"text": "我昨晚睡得很专业，一觉到天亮。", "explanation": "这里应该用〈香〉。“专业”指职业或专门领域的水平，不能用来评价睡眠；“睡得很香”才是睡得好的说法。"}, {"text": "这个词很专业，菜市场里的人天天都在说。", "explanation": "这里应该用〈口语〉。“专业”指属于某领域的术语，与“菜市场里的人天天都在说”的日常用语矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20095, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专业", "is_correct": true, "explanation": "专业：指属于某领域的术语，修饰“词”，与“写在黑板上”的课堂语境相合。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体能否看穿，不能用来修饰“词”。"}, {"text": "圆", "is_correct": false, "explanation": "体貌：“圆”形容形状，词语没有形状，说不通。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与“词”搭配后句子语义不通。"}], "explanations": {"专业": "专业：指属于某领域的术语，修饰“词”，与“写在黑板上”的课堂语境相合。", "透明": "搭配：“透明”形容物体能否看穿，不能用来修饰“词”。", "圆": "体貌：“圆”形容形状，词语没有形状，说不通。", "咸": "语义：“咸”指味道，与“词”搭配后句子语义不通。"}, "sentence_index": 6, "correct_answer": "专业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个柜子是专业的，别的东西不能放。", "explanation": "这里应该用〈专用〉。“专业”不表示“只供某种用途”，柜子不能说成“专业的”。"}, {"text": "他是这方面的专业，大家都请教他。", "explanation": "这里应该用〈专家〉。“专业”指所学或所从事的领域，不能指人。"}, {"text": "这个方法很专业，人人都会做。", "explanation": "这里应该用〈简单〉。“专业”指属于某领域的术语或知识，与“人人都会做”的日常方法不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇文章太专业过，我看不太懂。", "corrected_sentence": "这篇文章太专业了，我看不太懂。", "error_description": "“太”后的形容词“专业”应接语气助词“了”，写成“太专业了”；“过”表示经历，不能用在“太……”的程度结构里，“太专业过”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用专业地语言解释这个问题，大家都听不懂。", "corrected_sentence": "他用专业的语言解释这个问题，大家都听不懂。", "error_description": "“专业”修饰名词“语言”，应用“的”，写成“专业的语言”；“专业地”是副词结构，不能修饰名词，“专业地语言”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
