INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20097, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可以采取行动或表达意见的可能", "primary_collocate": null, "pronunciation": "jī huì", "ipa": "tɕi˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "如果系统做出重要决定，比如自动拒绝一个申请，用户应知道主要原因，并有机会申诉。", "target_word": "机会", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "开会的时候，每个人都有机会说话。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给了我一个机会，让我说说自己的看法。", "target_word": "机会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想找个机会跟经理谈谈这件事。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都希望有机会表达自己的意见。", "target_word": "机会", "complexity_tier": "T3", "furigana": "dà jiā dōu xī wàng yǒu jī huì biǎo dá zì jǐ de yì jiàn", "sentence_source": "generated"}, {"text": "这次会议上，他没有机会发言。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请给我一个机会，我想解释一下。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子也应该有机会说出自己的想法。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人有机会选择自己的治疗方法。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我一直没有机会告诉他我的决定。", "target_word": "机会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "機會", "label": "繁体"}, {"form": "个", "label": "量词"}, {"form": "次", "label": "量词"}], "register": "中性", "sense_fingerprint": "机会·名词·可以行动或表达意见的可能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79963f23-daa7-47ea-a422-83820dc3fd66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机会", "is_correct": true, "explanation": "机会：指可以做某事的可能，与“有……申诉”搭配，表示有可以申诉的机会。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能作为“有……申诉”的对象，句子说不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指身体的重量，不能作为申诉的对象。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”指冷热程度，不能与“申诉”搭配。"}], "explanations": {"机会": "机会：指可以做某事的可能，与“有……申诉”搭配，表示有可以申诉的机会。", "颜色": "搭配：“颜色”不能作为“有……申诉”的对象，句子说不通。", "体重": "体貌：“体重”指身体的重量，不能作为申诉的对象。", "温度": "搭配：“温度”指冷热程度，不能与“申诉”搭配。"}, "sentence_index": 0, "correct_answer": "机会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "现在机会很冷，我们别出去了。", "explanation": "这里应该用〈天气〉。“机会”是抽象的可能，不能用“冷”来形容。"}, {"text": "这次宴会是个正式的机会，大家都要穿西装。", "explanation": "这里应该用〈场合〉。“机会”指可以做某事的可能，“场合”指事情发生的环境，“正式的机会”说不通。"}, {"text": "这个机会穿在身上很合适。", "explanation": "这里应该用〈衣服〉。“机会”是抽象的可能，不能穿在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机会", "is_correct": true, "explanation": "机会：指可以做某事的可能，与“请给我一个……”搭配，表示给我一次解释的机会。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：“朋友”不能被“给”来表示解释的机会，句子语义不通。"}, {"text": "人", "is_correct": false, "explanation": "搭配：“人”不能作为可以解释的机会，“请给我一个人”说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”与“我想解释一下”没有关系，句子语义不通。"}], "explanations": {"机会": "机会：指可以做某事的可能，与“请给我一个……”搭配，表示给我一次解释的机会。", "朋友": "语义：“朋友”不能被“给”来表示解释的机会，句子语义不通。", "人": "搭配：“人”不能作为可以解释的机会，“请给我一个人”说不通。", "冰箱": "语义：“冰箱”与“我想解释一下”没有关系，句子语义不通。"}, "sentence_index": 6, "correct_answer": "机会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机会坏了，我们今天修不好。", "explanation": "这里应该用〈机器〉。“机会”是抽象的可能，不能指机械装置，也不能用“台”计量。"}, {"text": "他一下班就把机会放进冰箱。", "explanation": "这里应该用〈食物〉。“机会”是抽象的可能，不是可以放进冰箱的东西。"}, {"text": "他对这件事很机会，大家都很担心。", "explanation": "这里应该用〈紧张〉。“机会”是名词，不能用“很”修饰人的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于有了一机会去国外学习。", "corrected_sentence": "他终于有了一个机会去国外学习。", "error_description": "“机会”前的数量结构应为“一个机会”，写成“有了一个机会”；“一机会”漏了量词“个”，名词“机会”前的数词要带量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一直不有机会去北京旅游。", "corrected_sentence": "我一直没有机会去北京旅游。", "error_description": "否定“有”要用“没有”，写成“没有机会”；“不有”误用否定副词“不”，“不”不能用来否定“有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
