INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20100, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公司为规范行为而制定的正式规定", "primary_collocate": null, "pronunciation": "zhèng cè", "ipa": "ʈʂəŋ˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "最后，企业要制定明确的政策，并接受外部监督。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "公司的新政策从下个月开始执行。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项政策要求员工按时打卡。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理向大家说明了公司的休假政策。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根据公司政策，迟到三次要扣奖金。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新员工要先读懂公司的安全政策。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司修改了退货政策，时间改为七天。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政策对每位员工都一样。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须遵守公司的保密政策。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人事部正在研究新的加班政策。", "target_word": "政策", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项政策", "label": "量词"}, {"form": "政策性", "label": "复合"}], "register": "正式", "sense_fingerprint": "政策：公司为规范员工行为制定的正式规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e5e0e04-19d0-4826-8ae8-48040290f7a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政策", "is_correct": true, "explanation": "政策：企业为规范员工行为制定的正式规定，与“制定明确的”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“制定”不接“颜色”，“制定明确的颜色”说不通。"}, {"text": "人员", "is_correct": false, "explanation": "语义：“人员”不是可以制定的规定，句子意思不通。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“制定”不能与“体温”搭配，句子不通。"}], "explanations": {"政策": "政策：企业为规范员工行为制定的正式规定，与“制定明确的”搭配，符合句意。", "颜色": "搭配：“制定”不接“颜色”，“制定明确的颜色”说不通。", "人员": "语义：“人员”不是可以制定的规定，句子意思不通。", "体温": "搭配：“制定”不能与“体温”搭配，句子不通。"}, "sentence_index": 0, "correct_answer": "政策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司一共发布了三把政策。", "explanation": "这里应该用〈项〉。“把”用于有柄的东西，政策要用量词“项”计量。"}, {"text": "他下棋的政策很高明。", "explanation": "这里指下棋时的谋略，与公司或政府制定的正式规定不是同一个意思。"}, {"text": "这家餐厅的政策很好吃。", "explanation": "这里应该用〈菜〉。政策是正式规定，不能说好吃，应说菜好吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政策", "is_correct": true, "explanation": "政策：正式规定，与“修改了退货”搭配，指退货的规定，符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是种花草的地方，不能被修改成规定，句子不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“修改”不能接“心情”，“修改了退货心情”说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“修改”不能接“脚步”，句子不通。"}], "explanations": {"政策": "政策：正式规定，与“修改了退货”搭配，指退货的规定，符合句意。", "花园": "语义：“花园”是种花草的地方，不能被修改成规定，句子不通。", "心情": "搭配：“修改”不能接“心情”，“修改了退货心情”说不通。", "脚步": "搭配：“修改”不能接“脚步”，句子不通。"}, "sentence_index": 6, "correct_answer": "政策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对工作的政策很甜，从不迟到。", "explanation": "这里应该用〈态度〉。政策是正式规定，不能用“甜”形容，对工作的看法要用态度。"}, {"text": "这份报告提出了一座政策。", "explanation": "这里应该用〈项〉。“座”用于山、房屋等大型固定物，政策不能用。"}, {"text": "他在菜市场卖了两份政策。", "explanation": "这里应该用〈货物〉。政策是正式规定，不能当作商品买卖，不能说卖政策。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司制定了一把新的考勤政策。", "corrected_sentence": "公司制定了一项新的考勤政策。", "error_description": "错误：“一把”；正确：“一项”。“把”用于有柄的物品，政策应使用量词“项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项政策不执行过三年。", "corrected_sentence": "这项政策执行过三年。", "error_description": "错误：在“执行过”前加了“不”；正确：“这项政策执行过三年”。“过”表示经历，前面不能加“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
