INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20101, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "处理或管理数据的具体方式或步骤", "primary_collocate": null, "pronunciation": "zuò fǎ", "ipa": "tswo˥˩ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "总的来看，公开数据做法和算法原则，不是负担，而是建立长期信任的关键步骤。", "target_word": "做法", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司的数据管理做法很清楚。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先了解学校保存学生数据的做法。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院保护病人数据的做法让大家放心。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行删除旧数据的做法有三个步骤。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把公司处理数据的做法写成了文件。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站收集数据的做法不太清楚。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说这种整理数据的做法太慢了。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的数据管理做法比以前简单多了。", "target_word": "做法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想知道你们备份数据的做法。", "target_word": "做法", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "处理、管理数据时采用的具体方式或步骤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79963f23-daa7-47ea-a422-83820dc3fd66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20101, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "做法", "is_correct": true, "explanation": "正确。做法指处理或管理数据的具体方式或步骤，读作 zuò fǎ。"}, {"text": "做饭", "is_correct": false, "explanation": "fàn（第四声）与 fǎ（第三声）韵母与声调都不同，做饭指烧菜煮饭。"}, {"text": "作废", "is_correct": false, "explanation": "fèi（第四声）与 fǎ（第三声）韵母不同，作废指失去效力。"}, {"text": "奏法", "is_correct": false, "explanation": "声调混淆：zòu fǎ 与 zuò fǎ 仅首字声调不同，奏法指演奏乐器的方法。"}], "explanations": {"做法": "正确。做法指处理或管理数据的具体方式或步骤，读作 zuò fǎ。", "做饭": "fàn（第四声）与 fǎ（第三声）韵母与声调都不同，做饭指烧菜煮饭。", "作废": "fèi（第四声）与 fǎ（第三声）韵母不同，作废指失去效力。", "奏法": "声调混淆：zòu fǎ 与 zuò fǎ 仅首字声调不同，奏法指演奏乐器的方法。"}, "sentence_index": null, "correct_answer": "做法"}, "level_3": {"options": [{"text": "做法", "is_correct": true, "explanation": "正确。“公开数据的做法”指处理数据的具体方式，与“算法原则”并列，符合语境。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”不能与“公开数据”及“算法原则”并列，句子语义不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“公开数据”后不宜接“颜色”，两者不搭配。"}, {"text": "距离", "is_correct": false, "explanation": "语义：“距离”与“公开数据”及“算法原则”的关系不通，句子语义不对。"}], "explanations": {"做法": "正确。“公开数据的做法”指处理数据的具体方式，与“算法原则”并列，符合语境。", "钥匙": "语义：“钥匙”不能与“公开数据”及“算法原则”并列，句子语义不通。", "颜色": "搭配：“公开数据”后不宜接“颜色”，两者不搭配。", "距离": "语义：“距离”与“公开数据”及“算法原则”的关系不通，句子语义不对。"}, "sentence_index": 0, "correct_answer": "做法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们用一只做法保护了病人数据。", "explanation": "量词用错。“做法”应用〈种〉或〈个〉，〈只〉用于动物、器物等，不能用于“做法”。"}, {"text": "我们用一张做法整理了这些数据。", "explanation": "量词用错。〈张〉用于纸、桌子等平面物，不用于“做法”，应用〈种〉或〈个〉。"}, {"text": "老师用一台做法讲解了这个问题。", "explanation": "量词用错。〈台〉用于机器、仪器等，不用于“做法”，应用〈种〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20101, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做法", "is_correct": true, "explanation": "正确。“收集数据的做法”指收集数据的具体方式，与“不太清楚”搭配，符合语境。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不是可以用来描述“收集数据”的属性，句子语义不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”不能用来描述数据收集的方式，句子语义不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“收集数据的天气”搭配不当，“天气”不能作“收集数据”的修饰语。"}], "explanations": {"做法": "正确。“收集数据的做法”指收集数据的具体方式，与“不太清楚”搭配，符合语境。", "味道": "语义：“味道”不是可以用来描述“收集数据”的属性，句子语义不通。", "性格": "语义：“性格”不能用来描述数据收集的方式，句子语义不通。", "天气": "搭配：“收集数据的天气”搭配不当，“天气”不能作“收集数据”的修饰语。"}, "sentence_index": 6, "correct_answer": "做法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们用一辆做法备份了这些数据。", "explanation": "量词用错。〈辆〉用于车辆，不用于“做法”，应用〈种〉或〈个〉。"}, {"text": "我们用一颗做法备份了数据。", "explanation": "量词用错。〈颗〉用于颗粒状或球形的东西，不用于“做法”，应用〈种〉或〈个〉。"}, {"text": "老板用一把做法管理了数据。", "explanation": "量词用错。〈把〉用于有柄的工具等，不用于“做法”，应用〈种〉或〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们需要改进一只数据存储的做法。", "corrected_sentence": "我们需要改进一种数据存储的做法。", "error_description": "“做法”的量词应用“种”或“个”，不能用“只”（“只”多用于动物、器物等）。应说“一种数据存储的做法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们采用了一种备份数据做法。", "corrected_sentence": "他们采用了一种备份数据的做法。", "error_description": "“备份数据”修饰“做法”，中间需要结构助词“的”。应说“备份数据的做法”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c0637b4-a516-4149-95c7-5f1973d11154') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
