INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20102, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有目的地获取信息或数据用于分析或处理", "primary_collocate": null, "pronunciation": "cǎi jí", "ipa": "tsʰai˨˩˦ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "采集", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司通过问卷采集用户的意见。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器每分钟采集一次温度数据。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机会采集你的位置信息。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生采集了病人的心跳数据。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先采集数据，再做分析。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些数据是用无人机采集的。", "target_word": "采集", "complexity_tier": "T3", "furigana": "zhè xiē shù jù shì yòng wú rén jī cǎi jí de", "sentence_source": "generated"}, {"text": "学校不同意，就不能采集学生的个人信息。", "target_word": "采集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究小组采集过一千个人的声音。", "target_word": "采集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把采集到的资料整理好了。", "target_word": "采集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "采集了", "label": "完成体"}, {"form": "采集过", "label": "经历体"}, {"form": "采集器", "label": "复合词"}], "register": "中性", "sense_fingerprint": "采集：为分析或处理而获取信息、数据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048066ef-e0c6-43cd-971f-4df52a6c6dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做菜，与训练数据无关，句意不通。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的对象是房屋、空间，不说“数据的装修”。"}, {"text": "采集", "is_correct": true, "explanation": "正确：“数据的采集”指获取数据的环节，与后文“与使用”并列，句意通顺。"}, {"text": "种植", "is_correct": false, "explanation": "语义：数据不能种植，句子讨论的是数据获取与使用的合规问题。"}], "explanations": {"烹饪": "语义：烹饪是做菜，与训练数据无关，句意不通。", "装修": "搭配：“装修”的对象是房屋、空间，不说“数据的装修”。", "采集": "正确：“数据的采集”指获取数据的环节，与后文“与使用”并列，句意通顺。", "种植": "语义：数据不能种植，句子讨论的是数据获取与使用的合规问题。"}, "sentence_index": 0, "correct_answer": "采集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他早上采集了一杯咖啡。", "explanation": "这里应该用〈冲〉。采集指有目的地获取信息或数据，一杯咖啡要说冲。"}, {"text": "学校采集了一批新课本。", "explanation": "这里应该用〈采购〉。采集指有目的地获取信息或数据，买课本要说采购，不能说采集。"}, {"text": "我们把蛋糕采集了。", "explanation": "这里应该用〈烤〉。采集指有目的地获取信息或数据，蛋糕要说烤，不能说采集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烘焙", "is_correct": false, "explanation": "语义：无人机不能烘焙，烘焙是做点心的方法，句意不成立。"}, {"text": "缝制", "is_correct": false, "explanation": "语义：无人机不能缝制东西，句子描述的是获取数据的方式。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”的对象是枝叶、草坪等，不说“修剪数据”。"}, {"text": "采集", "is_correct": true, "explanation": "正确：无人机获取数据是常见的采集方式，与“用……的”结构相符。"}], "explanations": {"烘焙": "语义：无人机不能烘焙，烘焙是做点心的方法，句意不成立。", "缝制": "语义：无人机不能缝制东西，句子描述的是获取数据的方式。", "修剪": "搭配：“修剪”的对象是枝叶、草坪等，不说“修剪数据”。", "采集": "正确：无人机获取数据是常见的采集方式，与“用……的”结构相符。"}, "sentence_index": 6, "correct_answer": "采集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在网上采集了三本书。", "explanation": "这里应该用〈订购〉。采集用于获取数据或样本，书要通过订购得到。"}, {"text": "工人采集了一批啤酒。", "explanation": "这里应该用〈酿造〉。采集是获取已有的信息或样本，啤酒要通过酿造得到。"}, {"text": "雕刻家采集了一座雕像。", "explanation": "这里应该用〈雕刻〉。采集是获取已有的对象，雕像要通过雕刻制作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "研究人员已经采集了很多了用户数据。", "corrected_sentence": "研究人员已经采集了很多用户数据。", "error_description": "了的位置错误：完成体“了”应紧跟动词“采集”，“很多”后面不能再加“了”。写成“采集了很多了用户数据”是错误的，应为“采集了很多用户数据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批资料是我们在校园里采集。", "corrected_sentence": "这批资料是我们在校园里采集的。", "error_description": "结构助词缺失：“是……的”结构中，“的”不能省略，应为“采集的”，省略后句子不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
