INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使用某种工具或方法来有效应对复杂问题", "primary_collocate": null, "pronunciation": "lì yòng", "ipa": "li˥˩ joŋ˥˩", "syllable_count": 2, "sentences": [{"text": "工程师利用新技术解决了这个难题。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生利用这种方法，治好了很多病人。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察利用照片找到了那个人。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司利用大数据分析市场问题。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师利用游戏帮学生克服学习困难。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民利用科学方法解决了缺水问题。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要利用好工具，把复杂的问题变简单。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他利用软件整理了几千份资料。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员利用计算机模型预测天气变化。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校利用新系统管理考试成绩。", "target_word": "利用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "利用了", "label": "完成体"}, {"form": "利用过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用工具或方法有效解决复杂问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9e2f4-bad9-4d70-bb25-903be09d21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20104, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "利用", "is_correct": true, "explanation": "lì yòng：使用某种工具或方法，是正确答案。"}, {"text": "利于", "is_correct": false, "explanation": "lì yú 与 lì yòng 韵母不同（yú 与 yòng），意思是“对……有好处”。"}, {"text": "利益", "is_correct": false, "explanation": "lì yì 与 lì yòng 韵母不同（yì 与 yòng），意思是“好处”。"}, {"text": "利诱", "is_correct": false, "explanation": "lì yòu 与 lì yòng 韵母不同（yòu 与 yòng），意思是“用好处去引诱”。"}, {"text": "领用", "is_correct": false, "explanation": "lǐng yòng 第一音节的韵母和声调都不同（lǐng 与 lì），意思是“领取后使用”。"}], "explanations": {"利用": "lì yòng：使用某种工具或方法，是正确答案。", "利于": "lì yú 与 lì yòng 韵母不同（yú 与 yòng），意思是“对……有好处”。", "利益": "lì yì 与 lì yòng 韵母不同（yì 与 yòng），意思是“好处”。", "利诱": "lì yòu 与 lì yòng 韵母不同（yòu 与 yòng），意思是“用好处去引诱”。", "领用": "lǐng yòng 第一音节的韵母和声调都不同（lǐng 与 lì），意思是“领取后使用”。"}, "sentence_index": null, "correct_answer": "利用"}, "level_3": {"options": [{"text": "利用", "is_correct": true, "explanation": "利用：“利用新技术”表示把新技术当作手段，符合“解决了这个难题”的句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃新技术”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“新技术”作宾语。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔新技术”与“解决了这个难题”的句意相矛盾。"}], "explanations": {"利用": "利用：“利用新技术”表示把新技术当作手段，符合“解决了这个难题”的句意。", "吃": "搭配：“吃”的对象是食物，不能说“吃新技术”。", "哭": "配价：“哭”是不及物动词，不能带“新技术”作宾语。", "扔": "语义：“扔新技术”与“解决了这个难题”的句意相矛盾。"}, "sentence_index": 0, "correct_answer": "利用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工程师利用了这个难题，很快找到了答案。", "explanation": "这里应该用〈解决〉。利用的对象是工具或方法，难题要用“解决”。"}, {"text": "我们利用了这顿美味的晚餐。", "explanation": "这里应该用〈享用〉。“利用”强调把东西拿来派上用场，吃美食要用“享用”。"}, {"text": "我们利用了这次旅行的快乐。", "explanation": "这里应该用〈体验〉。“利用”强调拿来派上用场，感受快乐要用“体验”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20104, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "利用", "is_correct": true, "explanation": "lì yòng：使用某种工具或方法，是正确答案。"}, {"text": "弃用", "is_correct": false, "explanation": "qì yòng 与 lì yòng 声母不同（q 与 l），意思是“不再使用”。"}, {"text": "自用", "is_correct": false, "explanation": "zì yòng 与 lì yòng 声母不同（z 与 l），意思是“自己使用”。"}, {"text": "试用", "is_correct": false, "explanation": "shì yòng 与 lì yòng 声母不同（sh 与 l），意思是“试着使用”。"}, {"text": "日用", "is_correct": false, "explanation": "rì yòng 与 lì yòng 声母不同（r 与 l），意思是“日常使用的”。"}], "explanations": {"利用": "lì yòng：使用某种工具或方法，是正确答案。", "弃用": "qì yòng 与 lì yòng 声母不同（q 与 l），意思是“不再使用”。", "自用": "zì yòng 与 lì yòng 声母不同（z 与 l），意思是“自己使用”。", "试用": "shì yòng 与 lì yòng 声母不同（sh 与 l），意思是“试着使用”。", "日用": "rì yòng 与 lì yòng 声母不同（r 与 l），意思是“日常使用的”。"}, "sentence_index": null, "correct_answer": "利用"}, "level_3": {"options": [{"text": "利用", "is_correct": true, "explanation": "利用：“利用好工具”表示善于使用工具，与“把复杂的问题变简单”前后相合。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃好工具”与“把复杂的问题变简单”的句意相反。"}, {"text": "损坏", "is_correct": false, "explanation": "语义：“损坏好工具”与后半句的目的相矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“好工具”搭配，“唱好工具”不成词组。"}], "explanations": {"利用": "利用：“利用好工具”表示善于使用工具，与“把复杂的问题变简单”前后相合。", "放弃": "语义：“放弃好工具”与“把复杂的问题变简单”的句意相反。", "损坏": "语义：“损坏好工具”与后半句的目的相矛盾。", "唱": "搭配：“唱”不能与“好工具”搭配，“唱好工具”不成词组。"}, "sentence_index": 6, "correct_answer": "利用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家利用了这场美丽的日出。", "explanation": "这里应该用〈欣赏〉。“利用”强调拿来派用场，看景色要用“欣赏”。"}, {"text": "大家利用了这份心跳。", "explanation": "这里应该用〈感受〉。“利用”指拿来派上用场，心跳不是可供利用的工具或资源，要说“感受心跳”。"}, {"text": "他利用了一个美丽的梦。", "explanation": "这里应该用〈做〉。“利用”指拿来派上用场，梦是做出来的，要说“做了一个美丽的梦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程师很会好利用新工具来解决复杂问题。", "corrected_sentence": "工程师很会利用新工具来解决复杂问题。", "error_description": "“好”误置于动词“利用”之前，构成“很会好利用”，状语位置不通。“好”作补语时应紧跟动词之后（如“利用好”），此句只需去掉多余的“好”，直接说“很会利用新工具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师正在利用了新系统管理考试成绩。", "corrected_sentence": "老师正在利用新系统管理考试成绩。", "error_description": "“了”误加在“利用”后：“正在”表示动作进行中，不能与“了”同用，应说“正在利用新系统”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
