INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20111, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "适用于各种不同任务或用途的", "primary_collocate": null, "pronunciation": "tōng yòng", "ipa": "tʰʊŋ˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "OpenClaw 就是一个开源的通用人工智能代理项目。", "target_word": "通用", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这是一种通用的工具，什么活都能做。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个通用零件可以装在很多机器上。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了一个通用的充电器。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们需要一个通用的软件来处理文件。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个机器人是通用的，可以做很多种工作。", "target_word": "通用", "complexity_tier": "T3", "furigana": "zhè gè jī qì rén shì tōng yòng de, kě yǐ zuò hěn duō zhǒng gōng zuò.", "sentence_source": "generated"}, {"text": "这种接口是通用的，很多手机和电脑都能用。", "target_word": "通用", "complexity_tier": "T3", "furigana": "zhè zhǒng jiē kǒu shì tōng yòng de, hěn duō shǒu jī hé diàn nǎo dōu néng yòng.", "sentence_source": "generated"}, {"text": "这种通用模型不只会写文章，还会翻译。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想做一个通用的平台，让各行各业都能用。", "target_word": "通用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个通用的设计适合不同的用途。", "target_word": "通用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "通用型", "label": "复合"}, {"form": "通用性", "label": "复合"}], "register": "中性", "sense_fingerprint": "通用·适合多种任务或用途、功能不单一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d86f571-e8f9-490c-a880-a6de728f335c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：指适用于多种用途，修饰“人工智能代理项目”，意思是通用型。"}, {"text": "木制", "is_correct": false, "explanation": "语义：木制指由木材做成，不能用来修饰人工智能项目。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻指低温保存，不适用于人工智能代理项目。"}, {"text": "易碎", "is_correct": false, "explanation": "搭配：易碎多用于玻璃、瓷器等物品，不能用来形容人工智能项目。"}], "explanations": {"通用": "通用：指适用于多种用途，修饰“人工智能代理项目”，意思是通用型。", "木制": "语义：木制指由木材做成，不能用来修饰人工智能项目。", "冷冻": "语义：冷冻指低温保存，不适用于人工智能代理项目。", "易碎": "搭配：易碎多用于玻璃、瓷器等物品，不能用来形容人工智能项目。"}, "sentence_index": 0, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器是通用的，只能用来印刷。", "explanation": "这里应该用〈专用〉。通用指适用于多种用途，只能做一种用途时要说专用。"}, {"text": "这把钥匙是通用的，只能开我家的门。", "explanation": "这里应该用〈专属〉。通用指适用于多种场合，只开一扇门的钥匙要说专属。"}, {"text": "这位运动员是通用的，什么项目都能拿奖牌。", "explanation": "这里应该用〈全能〉。通用指适用于各种用途的物品或方法，形容人的多方面本领要说全能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通用", "is_correct": true, "explanation": "通用：说接口适用于很多手机和电脑，与“都能用”一致。"}, {"text": "定制", "is_correct": false, "explanation": "语义：定制指按特定需求制作，与“很多手机和电脑都能用”相矛盾。"}, {"text": "时尚", "is_correct": false, "explanation": "搭配：时尚多形容外观或款式，不用来说明接口的适用范围。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：柔软形容质地，不能用来说明接口能与很多设备兼容。"}], "explanations": {"通用": "通用：说接口适用于很多手机和电脑，与“都能用”一致。", "定制": "语义：定制指按特定需求制作，与“很多手机和电脑都能用”相矛盾。", "时尚": "搭配：时尚多形容外观或款式，不用来说明接口的适用范围。", "柔软": "搭配：柔软形容质地，不能用来说明接口能与很多设备兼容。"}, "sentence_index": 6, "correct_answer": "通用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套西装是通用的，只适合我一个人穿。", "explanation": "这里应该用〈定制〉。通用指不针对特定对象，只为一个人做的要说定制。"}, {"text": "这个接口是通用的，只有我们公司能用。", "explanation": "这里应该用〈独家〉。通用指各方都能使用，只允许一家使用要说独家。"}, {"text": "这件衣服是通用的，专为我的身材做的。", "explanation": "这里应该用〈量身定做〉。通用指不针对特定对象，专为某人身材制作要说量身定做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个转换头是通用地，各种设备都能接。", "corrected_sentence": "这个转换头是通用的，各种设备都能接。", "error_description": "“通用”作形容词，后面要用“的”，不能用“地”。正确：是通用的；错误：是通用地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套软件不通用，各行各业都能用。", "corrected_sentence": "这套软件很通用，各行各业都能用。", "error_description": "错误：“不通用”与后面的“各行各业都能用”自相矛盾（既说不通用，又说各行各业都能用）；应改为“很通用”，表示适用范围广。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20112, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20112, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20112, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不能、不懂得；也表示不可能发生（与“会”相对）。", "primary_collocate": null, "pronunciation": "bú huì", "ipa": "pu˧˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "有些人认为，公开AI代码不会带来安全风险。", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会游泳，所以不敢下水。", "target_word": "不会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不会骑自行车。", "target_word": "不会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别担心，这点小事不会影响比赛。", "target_word": "不会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天有大太阳，应该不会下雨。", "target_word": "不会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我从来不会做中国菜。", "target_word": "不会", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她这么认真，肯定不会迟到。", "target_word": "不会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟还小，不会自己穿衣服。", "target_word": "不会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他答应过我，不会把这件事告诉别人。", "target_word": "不会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字我不会写，请你教教我。", "target_word": "不会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "会不会", "label": "正反式"}], "register": "中性", "sense_fingerprint": "不会·没学过所以不能做，或表示事情不可能发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d86f571-e8f9-490c-a880-a6de728f335c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不会", "is_correct": true, "explanation": "不会：这里表示对将来情况的否定判断，符合“有些人认为……不会带来安全风险”的语境。"}, {"text": "不敢", "is_correct": false, "explanation": "语义：「不敢」表示胆怯，只能用于有意识的人，不能说「代码不敢带来风险」。"}, {"text": "不肯", "is_correct": false, "explanation": "语义：「不肯」表示拒绝，只用于人，代码不能拒绝带来风险。"}, {"text": "不愿", "is_correct": false, "explanation": "搭配：「不愿」的主语须是有意愿的人，「代码不愿带来风险」不通。"}], "explanations": {"不会": "不会：这里表示对将来情况的否定判断，符合“有些人认为……不会带来安全风险”的语境。", "不敢": "语义：「不敢」表示胆怯，只能用于有意识的人，不能说「代码不敢带来风险」。", "不肯": "语义：「不肯」表示拒绝，只用于人，代码不能拒绝带来风险。", "不愿": "搭配：「不愿」的主语须是有意愿的人，「代码不愿带来风险」不通。"}, "sentence_index": 0, "correct_answer": "不会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天不会来学校，所以没有见到老师。", "explanation": "这里应该用〈没有〉。「不会」表示将来不可能或不懂，说已经发生的事要用「没有」。"}, {"text": "他的眼睛不会看东西。", "explanation": "这里应该用〈看不见〉。「不会」表示不懂或学不会做某事，眼睛失去功能要用「看不见」。"}, {"text": "这几天工作很忙，我不会吃饭，只好饿着。", "explanation": "这里应该用〈没时间〉。「不会」表示不懂或不能做某事，因为忙而不吃饭要用「没时间」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不会", "is_correct": true, "explanation": "不会：这里表示「她」不可能迟到的判断，符合「这么认真」的语境。"}, {"text": "很会", "is_correct": false, "explanation": "语义：「很会」表示擅长，与「这么认真」的推断矛盾，句子说不通。"}, {"text": "常", "is_correct": false, "explanation": "语义：「常」表示经常，与「肯定」的判断和「认真」的描述不符。"}, {"text": "老", "is_correct": false, "explanation": "语域：「老」是口语说法，与前面书面化的「肯定」不协调，也与「这么认真」矛盾。"}], "explanations": {"不会": "不会：这里表示「她」不可能迟到的判断，符合「这么认真」的语境。", "很会": "语义：「很会」表示擅长，与「这么认真」的推断矛盾，句子说不通。", "常": "语义：「常」表示经常，与「肯定」的判断和「认真」的描述不符。", "老": "语域：「老」是口语说法，与前面书面化的「肯定」不协调，也与「这么认真」矛盾。"}, "sentence_index": 6, "correct_answer": "不会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不会他的电话号码，所以没法打电话给他。", "explanation": "这里应该用〈不知道〉。「不会」表示不懂怎么做，记不住或不清楚的信息要用「不知道」。"}, {"text": "这个字我不会写，所以我写得很好。", "explanation": "这里应该用〈擅长〉。「不会」表示不懂或不能做，与「写得很好」矛盾；说做得好要用「擅长」。"}, {"text": "明天你不会来上课，你必须来。", "explanation": "这里应该用〈不肯〉。「不会」预测将来不会发生，与「必须」的要求矛盾；表示拒绝要用「不肯」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他会不会唱歌吗？", "corrected_sentence": "他会不会唱歌？", "error_description": "错误：“会不会”已是正反疑问形式，句末不能再加“吗”；正确应为“他会不会唱歌？”，去掉“吗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没不会修电脑，我来帮他。", "corrected_sentence": "他不会修电脑，我来帮他。", "error_description": "错误：“不会”本身已表示否定，前面不能再加“没”，“没不会修电脑”属双重否定，不通；应删去“没”，为“他不会修电脑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f4c2542-30cc-416c-b1b7-d73960b58cfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
