INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20114, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "计算机中负责处理和执行逻辑推理的程序模块", "primary_collocate": null, "pronunciation": "yǐn qíng", "ipa": "in˨˩˦ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个系统由引擎、记忆模块和行动策略三部分组成。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏的引擎负责画面和声音。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个程序的引擎能自动判断对错。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件的引擎运行得太慢了。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的引擎让电脑游戏更好玩了。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用同一个引擎做了两个游戏。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "引擎收到问题后，会先分析再回答。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序员为这个应用换了新的引擎。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款游戏的引擎可以免费下载。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里的这个引擎负责计算结果。", "target_word": "引擎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推理引擎", "label": "复合"}, {"form": "搜索引擎", "label": "复合"}], "register": "中性", "sense_fingerprint": "软件中负责核心处理、运算或推理的程序模块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d46aa3-eeb1-4c0a-b496-7cdabfc5bb1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引擎", "is_correct": true, "explanation": "引擎是软件中负责处理和推理的程序模块，与“记忆模块”等并列的构件相符。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不是软件模块，与“记忆模块”并列在语义上不成立。"}, {"text": "木材", "is_correct": false, "explanation": "语义：木材是建筑或家具的原料，不是进行推理的程序构件。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“由……三部分组成”的并列部件须是软件模块，窗帘不能与之并列。"}], "explanations": {"引擎": "引擎是软件中负责处理和推理的程序模块，与“记忆模块”等并列的构件相符。", "手套": "语义：手套不是软件模块，与“记忆模块”并列在语义上不成立。", "木材": "语义：木材是建筑或家具的原料，不是进行推理的程序构件。", "窗帘": "搭配：“由……三部分组成”的并列部件须是软件模块，窗帘不能与之并列。"}, "sentence_index": 0, "correct_answer": "引擎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个程序用了一把新引擎，速度快了很多。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，软件中的程序模块要用“个”。"}, {"text": "我们给手机换了一辆新引擎。", "explanation": "这里应该用〈个〉。软件模块的量词是“个”，“辆”只用于车辆。"}, {"text": "这台吸尘器的引擎很吵。", "explanation": "这里应该用〈电机〉。吸尘器的动力部件通常叫电机，此处的〈引擎〉指软件中处理推理的程序模块，不能指家电部件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引擎", "is_correct": true, "explanation": "引擎是能接收问题并进行分析的程序模块，与“收到问题后先分析”相符。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶不能接收问题，也不会分析，句意不成立。"}, {"text": "茶杯", "is_correct": false, "explanation": "语义：茶杯没有分析问题的功能，与“先分析再回答”不符。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：“收到问题”的主语需要能接收信息，地毯不能与之搭配。"}], "explanations": {"引擎": "引擎是能接收问题并进行分析的程序模块，与“收到问题后先分析”相符。", "花瓶": "语义：花瓶不能接收问题，也不会分析，句意不成立。", "茶杯": "语义：茶杯没有分析问题的功能，与“先分析再回答”不符。", "地毯": "搭配：“收到问题”的主语需要能接收信息，地毯不能与之搭配。"}, "sentence_index": 6, "correct_answer": "引擎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们给游戏换了一张新引擎。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌面等扁平的东西，软件模块要用“个”。"}, {"text": "这台冰箱的引擎坏了，得请人来修。", "explanation": "这里应该用〈压缩机〉。冰箱的制冷部件叫压缩机，此处的〈引擎〉指软件中负责推理的程序模块，不能用于家电。"}, {"text": "这台电扇的引擎转得很快。", "explanation": "这里应该用〈马达〉。电扇等小型电器的动力部件通常叫马达，“引擎”一般指大型动力装置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆引擎需要经常更新。", "corrected_sentence": "这个引擎需要经常更新。", "error_description": "量词错误：软件模块的量词是“个”，“辆”只用于车辆。正确说法是“这个引擎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于把引擎改了好。", "corrected_sentence": "他终于把引擎改好了。", "error_description": "补语错误：结果补语“好”应紧跟动词，应说“改好”，不能说“改了好”。正确说法是“把引擎改好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e3990624-4451-427e-a3e3-e64c06faf824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
