INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20115, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "计算机或软件运行所依赖的基础系统环境", "primary_collocate": null, "pronunciation": "píng tái", "ipa": "pʰiŋ˧˥ tʰai˧˥", "syllable_count": 2, "sentences": [{"text": "这意味着，同一代理可在不同计算平台间无缝迁移，其长期记忆与行为模式不受底层模型更迭的影响。", "target_word": "平台", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "当代理能在不同平台上持续学习时，个体数据的隐私边界将面临根本性重构。", "target_word": "平台", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这个游戏可以在不同的平台上运行。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发新软件以前，要先选好平台。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个程序在手机平台上跑得很快。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的程序要同时支持电脑和手机两个平台。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换了新平台以后，旧软件打不开了。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在把旧系统搬到新的平台上。", "target_word": "平台", "complexity_tier": "T3", "furigana": "píngtái", "sentence_source": "generated"}, {"text": "这家公司开发的平台，很多程序都能在上面运行。", "target_word": "平台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一个软件在各个平台上，需要不同版本的安装包。", "target_word": "平台", "complexity_tier": "T3", "furigana": "píngtái", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "软件平台", "label": "复合"}], "register": "中性", "sense_fingerprint": "软件或程序运行所依赖的系统环境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53f15428-b18b-410e-8301-878efd0cd378') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20115, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "正确。“平台”指软件或系统运行所依赖的计算环境，符合“计算平台间迁移”的语境。"}, {"text": "平房", "is_correct": false, "explanation": "语义：“平房”指一层的房屋，与计算环境无关，“计算平房”不成立。"}, {"text": "台阶", "is_correct": false, "explanation": "语义：“台阶”指楼梯的一级，不能用于计算环境，句中的“计算台阶”没有意义。"}, {"text": "平原", "is_correct": false, "explanation": "语义：“平原”指地形，与计算机系统无关，不能说“计算平原”。"}], "explanations": {"平台": "正确。“平台”指软件或系统运行所依赖的计算环境，符合“计算平台间迁移”的语境。", "平房": "语义：“平房”指一层的房屋，与计算环境无关，“计算平房”不成立。", "台阶": "语义：“台阶”指楼梯的一级，不能用于计算环境，句中的“计算台阶”没有意义。", "平原": "语义：“平原”指地形，与计算机系统无关，不能说“计算平原”。"}, "sentence_index": 0, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在火车站的平台上等车。", "explanation": "这里的“平台”指车站的站台，是另一个意思，不是指软件或程序运行的基础环境。"}, {"text": "这个平台很高，爬上去需要一段时间。", "explanation": "这里的“平台”指地面上高起的平地，是另一个意思，不指计算机环境。"}, {"text": "他在屋顶的平台上晒衣服。", "explanation": "这里的“平台”指屋顶上平整的场地，是另一个意思，与软件运行的环境无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平台", "is_correct": true, "explanation": "正确。“换了新平台以后，旧软件打不开”说的是软件运行环境变了，符合该意思。"}, {"text": "平面", "is_correct": false, "explanation": "语义：“平面”指几何上的面，不能指软件运行的环境，“换了新平面”说不通。"}, {"text": "平地", "is_correct": false, "explanation": "语义：“平地”指平坦的土地，与软件运行无关，句子语义不通。"}, {"text": "台地", "is_correct": false, "explanation": "语义：“台地”指高原上的平坦地形，与计算机环境无关，不能用来描述软件的运行条件。"}], "explanations": {"平台": "正确。“换了新平台以后，旧软件打不开”说的是软件运行环境变了，符合该意思。", "平面": "语义：“平面”指几何上的面，不能指软件运行的环境，“换了新平面”说不通。", "平地": "语义：“平地”指平坦的土地，与软件运行无关，句子语义不通。", "台地": "语义：“台地”指高原上的平坦地形，与计算机环境无关，不能用来描述软件的运行条件。"}, "sentence_index": 6, "correct_answer": "平台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位候选人的竞选平台是减税。", "explanation": "这里的“平台”指竞选时提出的政治纲领，是另一个意思，与软件运行的基础环境无关。"}, {"text": "他在舞台式的平台上表演唱歌。", "explanation": "这里的“平台”指表演用的舞台，是另一个意思，与软件运行环境无关。"}, {"text": "这个平台的土很肥，可以种菜。", "explanation": "这里的“平台”指山坡上修成的平地，是另一个意思，与计算机环境无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个软件要不同的平台上运行才行。", "corrected_sentence": "这个软件要在不同的平台上运行才行。", "error_description": "错误在于漏掉了介词“在”。表示“运行的地点”时要说“在……平台上”，正确说法是“要在不同的平台上运行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块新平台很好用。", "corrected_sentence": "这个新平台很好用。", "error_description": "错误在于量词用错。“平台”作为计算环境应用量词“个”，说“这块”不对，正确说法是“这个新平台很好用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
