INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20116, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指出现有做法的问题并试图改变它", "primary_collocate": null, "pronunciation": "tiǎo zhàn", "ipa": "tʰiɑʊ̯˨˩˦ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "他敢于挑战老师的旧观点。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位年轻医生大胆挑战了传统的治疗方法。", "target_word": "挑战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李不怕挑战公司多年不变的规定。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写文章挑战大家都接受的看法。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们开始挑战学校的旧制度。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用新数据挑战了专家的结论。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敢于挑战权威的人，常常会遇到压力。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书挑战了人们对历史的老看法。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么总是挑战公司的老办法？", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直在挑战这种过时的做法。", "target_word": "挑战", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "挑战了", "label": "完成体"}, {"form": "挑战过", "label": "经历体"}, {"form": "挑战者", "label": "复合"}], "register": "中性", "sense_fingerprint": "对已有的观点、制度或做法提出质疑并想改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb2f094-77d0-4e9f-8b03-ce3ad85679b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "挑战", "is_correct": true, "explanation": "挑战：“敢于”后接对既有观点提出质疑，与“老师的旧观点”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“观点”作宾语，“敢于吃老师的旧观点”说不通。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽培植物，与“旧观点”毫无关系，句子说不通。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是物品或空间，不能用于观点。"}], "explanations": {"挑战": "挑战：“敢于”后接对既有观点提出质疑，与“老师的旧观点”搭配自然。", "吃": "搭配：“吃”不能带“观点”作宾语，“敢于吃老师的旧观点”说不通。", "种植": "语义：“种植”指栽培植物，与“旧观点”毫无关系，句子说不通。", "装饰": "搭配：“装饰”的对象是物品或空间，不能用于观点。"}, "sentence_index": 0, "correct_answer": "挑战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是挑战妻子做的饭，从来不满意。", "explanation": "这里应该用〈挑剔〉。挑剔指找毛病，挑战强调对既有观点、制度或做法提出质疑，不能用于评价饭菜的口味。"}, {"text": "她在店里挑战了一件新衣服。", "explanation": "这里应该用〈挑选〉。挑选指从多件物品中选取，挑战只用于对既有观点、制度或做法提出质疑。"}, {"text": "他挑战了两桶水回家。", "explanation": "这里应该用〈担〉。担指用肩膀挑着东西，挑战表示对既有做法提出质疑，不能用于担水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挑战", "is_correct": true, "explanation": "挑战：“敢于”与对权威提出挑战的意思相符，句子通顺。"}, {"text": "服从", "is_correct": false, "explanation": "语义：“敢于”强调有勇气做有风险的事，“服从”与之相反，句子自相矛盾。"}, {"text": "讨好", "is_correct": false, "explanation": "语义：“讨好”指迎合别人，与“敢于”的冒险含义相反。"}, {"text": "擦拭", "is_correct": false, "explanation": "语义：“擦拭”的对象是物体表面，不能用于“权威”，句子说不通。"}], "explanations": {"挑战": "挑战：“敢于”与对权威提出挑战的意思相符，句子通顺。", "服从": "语义：“敢于”强调有勇气做有风险的事，“服从”与之相反，句子自相矛盾。", "讨好": "语义：“讨好”指迎合别人，与“敢于”的冒险含义相反。", "擦拭": "语义：“擦拭”的对象是物体表面，不能用于“权威”，句子说不通。"}, "sentence_index": 6, "correct_answer": "挑战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总是挑战同事之间的关系，想让大家互相猜疑。", "explanation": "这里应该用〈离间〉。“离间”指使人与人之间产生隔阂；挑战用于观点、制度或做法，不能用于人际关系。"}, {"text": "他总是挑战两家的感情，让两家吵起来。", "explanation": "这里应该用〈挑拨〉。“挑拨”指从中制造矛盾；挑战的对象只能是观点、制度或做法，不能是感情。"}, {"text": "他总是挑战别人的私事，大家都很生气。", "explanation": "这里应该用〈打听〉。“打听”是探问别人的事情；挑战用于观点、制度或做法，不能用于私事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "年轻人正在挑战了传统的观念。", "corrected_sentence": "年轻人正在挑战传统的观念。", "error_description": "错误在“了”：“正在”表示动作正在进行，不能与表示完成的“了”同用。应去掉“了”，说“正在挑战传统的观念”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一直挑战这只不合理的规定。", "corrected_sentence": "他们一直挑战这项不合理的规定。", "error_description": "量词错误：“规定”应用“项”“条”等量词；“只”多用于动物或成对的物件，不能修饰“规定”。应说“这项不合理的规定”或“这条不合理的规定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
