INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "记录科学研究成果的书籍、论文等资料", "primary_collocate": null, "pronunciation": "wén xiàn", "ipa": "wən˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "老师要我们先梳理跨学科文献，再动笔写论文。", "target_word": "文献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写论文以前，我要先读很多文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文献介绍了新的研究方法。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在图书馆查找相关文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们把这个课题的文献按年份整理好。", "target_word": "文献", "complexity_tier": "T3", "furigana": "lǎo shī ràng wǒ men bǎ zhège kètí de wénxiàn àn niánfèn zhěnglǐ hǎo", "sentence_source": "generated"}, {"text": "研究生每周都要看几篇英文文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文献记录了实验的全部结果。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用了三个月读完这些医学文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "论文后面要列出所有引用的文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个领域的文献很多，我读不完。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一篇文献", "label": "量词"}, {"form": "一份文献", "label": "量词"}, {"form": "参考文献", "label": "复合"}, {"form": "文献综述", "label": "复合"}, {"form": "文獻", "label": "繁体"}], "register": "书面", "sense_fingerprint": "记录科研成果的书籍、论文等学术资料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb2f094-77d0-4e9f-8b03-ce3ad85679b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文献", "is_correct": true, "explanation": "正确：“文献”指科研成果的资料，与“梳理跨学科”的语境相合。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡不是可以梳理的学术资料，无法用于科研梳理。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“梳理”用于资料、思路、问题，不与“天气”搭配。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不是跨学科研究的对象，句中需要的是知识材料。"}], "explanations": {"文献": "正确：“文献”指科研成果的资料，与“梳理跨学科”的语境相合。", "咖啡": "语义：咖啡不是可以梳理的学术资料，无法用于科研梳理。", "天气": "搭配：“梳理”用于资料、思路、问题，不与“天气”搭配。", "体温": "语义：体温不是跨学科研究的对象，句中需要的是知识材料。"}, "sentence_index": 0, "correct_answer": "文献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天给这篇文献充了电，准备交给导师。", "explanation": "这里应该用〈手机〉。文献是文字资料，不能充电；需要充电的是手机等电子设备。"}, {"text": "请在表格里填写你的个人文献。", "explanation": "这里应该用〈资料〉。填写个人信息要说“个人资料”，文献专指学术或历史上的文字材料。"}, {"text": "请经理在这份文献上签字，然后交给财务。", "explanation": "这里应该用〈文件〉。需要签字的是公文或合同；文献指学术或历史文字资料，不用来签字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文献", "is_correct": true, "explanation": "正确：“文献”指记录实验成果的资料，与“记录了实验的全部结果”相合。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不能记录实验结果，句中的主语应是资料。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只用来报时，不记录实验数据。"}, {"text": "影子", "is_correct": false, "explanation": "搭配：“记录”不与“影子”搭配，影子不是可以被记录结果的载体。"}], "explanations": {"文献": "正确：“文献”指记录实验成果的资料，与“记录了实验的全部结果”相合。", "面包": "语义：面包不能记录实验结果，句中的主语应是资料。", "闹钟": "语义：闹钟只用来报时，不记录实验数据。", "影子": "搭配：“记录”不与“影子”搭配，影子不是可以被记录结果的载体。"}, "sentence_index": 6, "correct_answer": "文献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本文献的情节很吸引人。", "explanation": "这里应该用〈小说〉。文献是学术资料，没有情节；形容情节吸引人要用〈小说〉。"}, {"text": "这篇文献讲了一个小老鼠冒险的故事，孩子们都爱听。", "explanation": "这里应该用〈童话〉。文献是学术或历史资料，不讲虚构的小老鼠冒险；讲给孩子听的虚构故事要用〈童话〉。"}, {"text": "这篇文献的幽默让人发笑。", "explanation": "这里应该用〈文章〉。文献重在资料价值；形容幽默、令人发笑的要用〈文章〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我读了三只文献。", "corrected_sentence": "我读了三篇文献。", "error_description": "量词错误：“文献”应搭配“篇”，不能用“只”（“只”用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天读了完这份文献。", "corrected_sentence": "我昨天读完了这份文献。", "error_description": "补语位置错误：“读完”是动补结构，“了”应放在“完”之后，应说“读完了这份文献”，不说“读了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "资本", "is_correct": false, "explanation": "无关：资本指用于生产经营的钱或财产，与趋同无关。"}, {"text": "网络", "is_correct": false, "explanation": "无关：网络指相互连接的系统，与趋同没有反义关系。"}, {"text": "节奏", "is_correct": false, "explanation": "无关：节奏指有规律的快慢变化，与趋同无关。"}, {"text": "趋异", "is_correct": true, "explanation": "反义：趋异指事物朝不同方向发展，与趋同相对。"}], "correct_answer": "趋异", "explanations": {"资本": "无关：资本指用于生产经营的钱或财产，与趋同无关。", "网络": "无关：网络指相互连接的系统，与趋同没有反义关系。", "节奏": "无关：节奏指有规律的快慢变化，与趋同无关。", "趋异": "反义：趋异指事物朝不同方向发展，与趋同相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
