INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "多个个体的行为因相似目标而变得越来越一致", "primary_collocate": null, "pronunciation": "qū tóng", "ipa": "tɕʰy˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "更严峻的是，若大量代理基于相似优化目标自发演化，可能催生群体性的行为趋同，进而形成“分布式认知霸权”——表面上去中心化的系统，实质上演变为隐蔽的价值导向网络。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "投资者追逐同一个目标，行为渐渐趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想考高分，学习方法越来越趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了抢占市场，各家商店的促销行为趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目标相似使不同公司的决策出现趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多司机为了躲开堵车，行为渐渐趋同。", "target_word": "趋同", "complexity_tier": "T3", "furigana": "xǔ duō sī jī wèi le duǒ kāi dǔ chē xíng wéi jiàn jiàn qū tóng", "sentence_source": "generated"}, {"text": "同样想赢得比赛，几支球队的打法趋同了。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用户的购买行为因共同的需求而趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了得到更多点击，作者们的写法趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "求职者目标一致，简历的写法也趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趨同", "label": "繁体"}, {"form": "趋同化", "label": "派生"}, {"form": "趋同性", "label": "派生"}], "register": "书面", "sense_fingerprint": "趋同|多个个体因相似目标而行为越来越一致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b9558c-ba16-40e5-9481-34d3d74a317c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确。“群体性的行为趋同”指许多个体因相似目标而行为一致，正好引出后文的霸权。"}, {"text": "个性", "is_correct": false, "explanation": "语义：个性指个人的独特之处，与“群体性”的一致行为相反。"}, {"text": "乐趣", "is_correct": false, "explanation": "语义：乐趣是快乐的感受，不是可以“催生”的行为特征。"}, {"text": "独立", "is_correct": false, "explanation": "搭配：“行为独立”与“群体性”相矛盾，“独立”不能与“群体性的行为”搭配。"}], "explanations": {"趋同": "正确。“群体性的行为趋同”指许多个体因相似目标而行为一致，正好引出后文的霸权。", "个性": "语义：个性指个人的独特之处，与“群体性”的一致行为相反。", "乐趣": "语义：乐趣是快乐的感受，不是可以“催生”的行为特征。", "独立": "搭配：“行为独立”与“群体性”相矛盾，“独立”不能与“群体性的行为”搭配。"}, "sentence_index": 0, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "几家商店的促销活动趋同进行，顾客很方便。", "explanation": "这里应该用〈同时〉。同时指在同一时间发生；趋同强调不同个体逐渐靠拢，不能描述同时进行的活动。"}, {"text": "两家公司的股价趋同上涨，投资者很高兴。", "explanation": "这里应该用〈同步〉。同步指同时发生；趋同强调逐渐靠拢的过程，不能描述“上涨”这种同时的动作。"}, {"text": "他的购买习惯越来越趋同。", "explanation": "这里应该用〈改变〉。趋同需要多个个体因相似目标而靠拢，只说一个人的习惯，不能用趋同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确。几支球队目标一致，打法向同一方向靠拢，所以说打法趋同了。"}, {"text": "上涨", "is_correct": false, "explanation": "语义：上涨用于价格、数量，不用于打法，与“同样想赢得比赛”也不相符。"}, {"text": "降价", "is_correct": false, "explanation": "搭配：“降价”用于商品，不用于打法。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或物的重量，打法没有体重，句子不通。"}], "explanations": {"趋同": "正确。几支球队目标一致，打法向同一方向靠拢，所以说打法趋同了。", "上涨": "语义：上涨用于价格、数量，不用于打法，与“同样想赢得比赛”也不相符。", "降价": "搭配：“降价”用于商品，不用于打法。", "体重": "语义：体重指人或物的重量，打法没有体重，句子不通。"}, "sentence_index": 6, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两篇作文的内容大段趋同，老师一眼就看出来了。", "explanation": "这里应该用〈雷同〉。雷同指内容几乎一样，常带有抄袭的意味；趋同强调不同事物逐渐靠拢的过程。"}, {"text": "两家公司合并后，两个部门终于趋同在一起了。", "explanation": "这里应该用〈融合〉。融合指合为一体；趋同只指朝相同方向靠拢，不能说“在一起”。"}, {"text": "我的口味越来越趋同。", "explanation": "这里应该用〈改变〉。趋同需要多个不同个体朝同一方向靠拢，只说我的口味，不能用趋同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家店的促销行为趋同很得明显，顾客很难分辨。", "corrected_sentence": "两家店的促销行为趋同得很明显，顾客很难分辨。", "error_description": "补语结构错：“得”应紧跟在“趋同”后，正确说法是“趋同得很明显”，不能说“趋同很得明显”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些学生的作答方式出现了一只令人惊讶的趋同。", "corrected_sentence": "这些学生的作答方式出现了一种令人惊讶的趋同。", "error_description": "量词用错：“只”不能修饰趋同，应改为“种”，即“一种令人惊讶的趋同”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
