INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "木头是树的一部分，可以做成桌子、椅子。", "primary_collocate": null, "pronunciation": "mù tou", "ipa": "mu˥˩ tʰou", "syllable_count": 2, "sentences": [{"text": "这张桌子是木头做的。", "target_word": "木头", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "木头很轻，可以浮在水上。", "target_word": "木头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸用木头给我做了一把小椅子。", "target_word": "木头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木头放在水边太久，会慢慢变坏。", "target_word": "木头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天，我们在火里放了几块木头。", "target_word": "木头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种木头很硬，用刀切不动。", "target_word": "木头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小河上有一座木头桥。", "target_word": "木头", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从山上搬了一大根木头回家。", "target_word": "木头", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木头碰到火会烧起来。", "target_word": "木头", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们用木头和纸做一个小房子。", "target_word": "木头", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "根", "label": "量词"}, {"form": "木頭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "树木的材料，可以用来做家具和房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1994afce-084b-4c4b-8b0f-90dace7d412c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "木头", "is_correct": true, "explanation": "正确：木头是树的材料，可以用来做桌子，符合“是…做的”的语境。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是气体，没有固定形状，不能用来做桌子。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“是…做的”的材料须是固体，不能说“水做的桌子”。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵是天上的水汽，不能被加工成桌子。"}], "explanations": {"木头": "正确：木头是树的材料，可以用来做桌子，符合“是…做的”的语境。", "空气": "语义：空气是气体，没有固定形状，不能用来做桌子。", "水": "搭配：“是…做的”的材料须是固体，不能说“水做的桌子”。", "云朵": "语义：云朵是天上的水汽，不能被加工成桌子。"}, "sentence_index": 0, "correct_answer": "木头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家买了一只木头，放在院子里。", "explanation": "这里的量词用错了。应该用〈块〉或〈根〉。〈只〉用于动物或成对的东西，不用来数木头。"}, {"text": "公园里种了很多木头。", "explanation": "这里应该用〈树〉。〈树〉是活的植物，可以种；木头是砍下来的木材，不能种。"}, {"text": "院子里的木头长得很高，都快碰到屋顶了。", "explanation": "这里应该用〈树〉。〈木头〉指砍下来的木材，不能说活着的树长得很高；活着的树要用〈树〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木头", "is_correct": true, "explanation": "正确：木头可以用来造桥，“木头桥”指木头做的桥，符合语境。"}, {"text": "烟", "is_correct": false, "explanation": "语义：烟没有固定形状，无法用来造桥。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是从天上落下的水，不能用来造桥。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦是想象中的景象，不是可以用来造桥的材料。"}], "explanations": {"木头": "正确：木头可以用来造桥，“木头桥”指木头做的桥，符合语境。", "烟": "语义：烟没有固定形状，无法用来造桥。", "雨": "语义：雨是从天上落下的水，不能用来造桥。", "梦": "语义：梦是想象中的景象，不是可以用来造桥的材料。"}, "sentence_index": 6, "correct_answer": "木头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气很冷，他穿上了一块木头。", "explanation": "这里应该用〈外套〉。“穿”的对象是衣服，〈木头〉是木材，不能穿在身上。"}, {"text": "妈妈煮了几块木头当晚饭。", "explanation": "这里应该用〈萝卜〉。“煮”的对象应是食材，〈木头〉是木材，不能吃，也不能当晚饭。"}, {"text": "小狗喝完了那块木头。", "explanation": "这里应该用〈牛奶〉。“喝”的对象应是液体，〈木头〉是固体，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他砍下一只木头，搬回了家。", "corrected_sentence": "他砍下一根木头，搬回了家。", "error_description": "“木头”的量词应用“根”或“块”，不能用“只”。“只”用于动物或成对的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸把木头做了成一把椅子。", "corrected_sentence": "爸爸把木头做成一把椅子。", "error_description": "“做成”是复合动词，“了”不能插在“做”和“成”之间。应说“做成一把椅子”，不能说“做了成一把椅子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
