INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20130, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指很多很多人。", "primary_collocate": null, "pronunciation": "rén men", "ipa": "ʐən˧˥ mən", "syllable_count": 2, "sentences": [{"text": "下雨了，人们都回家了。", "target_word": "人们", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，人们都很高兴。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在人们常用手机买东西。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里，人们在唱歌跳舞。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们说，好人会有好事。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，人们应该爱护环境。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气很热，人们都想喝冰水。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个小城，人们过着安静的生活。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前人们坐火车去很远的地方。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的人们都在看那只大狗。", "target_word": "人们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "泛指许多人的群体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d8b840b-ee01-4694-9784-5eb6724c58e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人们", "is_correct": true, "explanation": "“人们”：泛指许多人，下雨时人们都回家，句子成立。"}, {"text": "石头们", "is_correct": false, "explanation": "语义：石头不会回家，与“下雨了”的语境不符。"}, {"text": "机器们", "is_correct": false, "explanation": "配价：“回家”的主语须是人或动物，不能是机器。"}, {"text": "桌子们", "is_correct": false, "explanation": "语义：桌子不能回家，句子无法成立。"}], "explanations": {"人们": "“人们”：泛指许多人，下雨时人们都回家，句子成立。", "石头们": "语义：石头不会回家，与“下雨了”的语境不符。", "机器们": "配价：“回家”的主语须是人或动物，不能是机器。", "桌子们": "语义：桌子不能回家，句子无法成立。"}, "sentence_index": 0, "correct_answer": "人们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的人们都在老家。", "explanation": "这里应该用〈家人〉。“人们”泛指社会上很多人，不能指自己的家人。"}, {"text": "他的人们今天都来了。", "explanation": "这里应该用〈手下〉。“人们”泛指很多人，不能指某人的部下。"}, {"text": "我们的人们正在开会。", "explanation": "这里应该用〈同事〉。“人们”泛指很多人，不能指自己单位里的同事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人们", "is_correct": true, "explanation": "“人们”：泛指的人，天气热时人们都想喝冰水，句子成立。"}, {"text": "窗户们", "is_correct": false, "explanation": "语义：窗户不能喝水，句子无法成立。"}, {"text": "电脑们", "is_correct": false, "explanation": "配价：“想喝”的主语须是有生命的人或动物，不能是电脑。"}, {"text": "房子们", "is_correct": false, "explanation": "语义：房子不能想喝水，句子不成立。"}], "explanations": {"人们": "“人们”：泛指的人，天气热时人们都想喝冰水，句子成立。", "窗户们": "语义：窗户不能喝水，句子无法成立。", "电脑们": "配价：“想喝”的主语须是有生命的人或动物，不能是电脑。", "房子们": "语义：房子不能想喝水，句子不成立。"}, "sentence_index": 6, "correct_answer": "人们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板的人们明天会来。", "explanation": "这里应该用〈员工〉。“人们”泛指很多人，不能指老板手下的员工。"}, {"text": "你的人们怎么还没到？", "explanation": "这里应该用〈朋友〉。“人们”泛指很多人，不能指你的某几位朋友。"}, {"text": "她的人们都住在城里。", "explanation": "这里应该用〈亲戚〉。“人们”泛指很多人，不能指她的亲戚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街上的三个人们都很忙。", "corrected_sentence": "街上的人们都很忙。", "error_description": "数量词错误：“人们”是复数，不能加“三个”。应说“街上的人们”，或改为“街上的三个人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的人们们都很友好。", "corrected_sentence": "这里的人们都很友好。", "error_description": "重复：“人们”已含复数“们”，不能再加“们”。应说“这里的人们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
