INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书的总称，指可供阅读的印刷出版物。", "primary_collocate": null, "pronunciation": "shū jí", "ipa": "ʂu˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "图书馆里有很多外语书籍。", "target_word": "书籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家书店专门出售二手书籍。", "target_word": "书籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把所有的书籍都捐给了学校。", "target_word": "书籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书籍按内容分类摆放，很容易找到。", "target_word": "书籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，书籍比衣服还重。", "target_word": "书籍", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "网上可以买到各种教育类书籍。", "target_word": "书籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古代书籍保存起来很不容易。", "target_word": "书籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校新买来很多书籍，放在阅览室里。", "target_word": "书籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位教授的书房里堆满了书籍。", "target_word": "书籍", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批书籍是从国外寄来的。", "target_word": "书籍", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "批", "label": "量词"}, {"form": "套", "label": "量词"}, {"form": "書籍", "label": "繁体"}], "register": "书面", "sense_fingerprint": "书籍：书的总称，可供阅读的出版物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff2dc4db-9995-4fb8-b9e3-e98d425bf1f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20148, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "书籍", "is_correct": true, "explanation": "书籍（shū jí）即正确答案。"}, {"text": "书记", "is_correct": false, "explanation": "shū jì（第四声）与 shū jí（第二声）第二音节声调不同，意思是书记。"}, {"text": "书脊", "is_correct": false, "explanation": "shū jǐ（第三声）与 shū jí（第二声）第二音节声调不同，意思是书脊。"}, {"text": "暑季", "is_correct": false, "explanation": "shǔ jì 与 shū jí 两个音节的声调都不同，意思是暑季、夏季。"}], "explanations": {"书籍": "书籍（shū jí）即正确答案。", "书记": "shū jì（第四声）与 shū jí（第二声）第二音节声调不同，意思是书记。", "书脊": "shū jǐ（第三声）与 shū jí（第二声）第二音节声调不同，意思是书脊。", "暑季": "shǔ jì 与 shū jí 两个音节的声调都不同，意思是暑季、夏季。"}, "sentence_index": null, "correct_answer": "书籍"}, "level_3": {"options": [{"text": "书籍", "is_correct": true, "explanation": "书籍：书的总称，与“外语”“图书馆”的语境相合。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“外语”修饰的应是可阅读或可学习的东西，钥匙不是，句子不通。"}, {"text": "家具", "is_correct": false, "explanation": "搭配：“家具”不与“外语”组合，“外语家具”不能说。"}, {"text": "桌椅", "is_correct": false, "explanation": "语义：桌椅没有外语版本，与“外语”的语义相冲突。"}], "explanations": {"书籍": "书籍：书的总称，与“外语”“图书馆”的语境相合。", "钥匙": "语义：“外语”修饰的应是可阅读或可学习的东西，钥匙不是，句子不通。", "家具": "搭配：“家具”不与“外语”组合，“外语家具”不能说。", "桌椅": "语义：桌椅没有外语版本，与“外语”的语义相冲突。"}, "sentence_index": 0, "correct_answer": "书籍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天练书籍，已经练了三年。", "explanation": "这里应该用〈书法〉。“练”的对象是字或技能，书法指写字的艺术；书籍是印刷品，不能用“练”。"}, {"text": "周末我去书籍逛了一下午。", "explanation": "这里应该用〈书店〉。“逛”的地点是商店或街道，书籍是印刷品，不能当作去逛的场所。"}, {"text": "我在书籍借了三本书。", "explanation": "这里应该用〈图书馆〉。“在……借”的地点要是图书馆这类场所，书籍不是场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书籍", "is_correct": true, "explanation": "书籍：书面的出版物总称，与“古代”“保存起来”的语境相合。"}, {"text": "人员", "is_correct": false, "explanation": "语义：“人员”是人，不能像物品一样被“保存起来”。"}, {"text": "方向", "is_correct": false, "explanation": "语义：“方向”不是有形的物品，无法“保存起来”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“古代天气”不成立，且天气也不能被“保存起来”。"}], "explanations": {"书籍": "书籍：书面的出版物总称，与“古代”“保存起来”的语境相合。", "人员": "语义：“人员”是人，不能像物品一样被“保存起来”。", "方向": "语义：“方向”不是有形的物品，无法“保存起来”。", "天气": "搭配：“古代天气”不成立，且天气也不能被“保存起来”。"}, "sentence_index": 6, "correct_answer": "书籍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民去年种了很多书籍，今年收成不错。", "explanation": "这里应该用〈蔬菜〉。“种”搭配植物，书籍不能种植。"}, {"text": "妈妈在厨房里煮书籍，准备晚饭。", "explanation": "这里把〈书籍〉当成了〈食材〉。书籍是供人阅读的印刷品，不能用“煮”来做饭，“煮”只用于食物。"}, {"text": "这批书籍很好喝，是从国外寄来的。", "explanation": "这里把〈书籍〉当成了〈饮料〉。书籍是供人阅读的出版物，不能用“好喝”来形容，“好喝”只用于饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从网上买了一条书籍。", "corrected_sentence": "他从网上买了一套书籍。", "error_description": "“书籍”前的量词用错了。“条”用于细长的东西，书籍应用“套”或“批”，不能用“条”来数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这批书籍们寄回了国内。", "corrected_sentence": "我把这批书籍寄回了国内。", "error_description": "“书籍”是总称，不能加“们”表示复数；应直接说“这批书籍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
