INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纸是用来写字画画的薄薄的东西。", "primary_collocate": null, "pronunciation": "zhǐ", "ipa": "ʈʂɨ˨˩˦", "syllable_count": 1, "sentences": [{"text": "请给我一张白纸。", "target_word": "纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在纸上写了他的名字。", "target_word": "纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有很多纸。", "target_word": "纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩用彩色纸做花。", "target_word": "纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸太薄了，不能画画。", "target_word": "纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把信写在一张红纸上。", "target_word": "纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发给我们每人一张纸。", "target_word": "纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请别把纸放在水边。", "target_word": "纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用纸折了一只小鸟。", "target_word": "纸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的纸很好，写字不会透。", "target_word": "纸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "紙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来写字画画的薄片材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35b906f-46d6-4de6-ad17-6696c52b793f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20156, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纸", "is_correct": true, "explanation": "正确答案：纸（zhǐ），意思是写字画画的薄片材料。"}, {"text": "直", "is_correct": false, "explanation": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是笔直。"}, {"text": "尺", "is_correct": false, "explanation": "chǐ 与 zhǐ 声母不同（ch 与 zh），意思是尺子。"}, {"text": "使", "is_correct": false, "explanation": "shǐ 与 zhǐ 声母不同（sh 与 zh），意思是使用。"}, {"text": "子", "is_correct": false, "explanation": "zǐ 与 zhǐ 声母不同（z 与 zh），意思是儿子或子女。"}], "explanations": {"纸": "正确答案：纸（zhǐ），意思是写字画画的薄片材料。", "直": "zhí（第二声）与 zhǐ（第三声）声调不同，意思是笔直。", "尺": "chǐ 与 zhǐ 声母不同（ch 与 zh），意思是尺子。", "使": "shǐ 与 zhǐ 声母不同（sh 与 zh），意思是使用。", "子": "zǐ 与 zhǐ 声母不同（z 与 zh），意思是儿子或子女。"}, "sentence_index": null, "correct_answer": "纸"}, "level_3": {"options": [{"text": "纸", "is_correct": true, "explanation": "正确：“一张白纸”，“张”用于纸张等平面物。"}, {"text": "碗", "is_correct": false, "explanation": "搭配：量词“张”不搭配“碗”，“一张白碗”不成立。"}, {"text": "雪", "is_correct": false, "explanation": "语义：“雪”不是可以用“一张”计量的材料，“一张白雪”语义不通。"}, {"text": "豆", "is_correct": false, "explanation": "搭配：“豆”用“粒”或“颗”计量，不能说“一张白豆”。"}], "explanations": {"纸": "正确：“一张白纸”，“张”用于纸张等平面物。", "碗": "搭配：量词“张”不搭配“碗”，“一张白碗”不成立。", "雪": "语义：“雪”不是可以用“一张”计量的材料，“一张白雪”语义不通。", "豆": "搭配：“豆”用“粒”或“颗”计量，不能说“一张白豆”。"}, "sentence_index": 0, "correct_answer": "纸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我吃了一张纸。", "explanation": "这里应该用〈饼〉。纸不能吃，“一张饼”才是正常说法。"}, {"text": "我买了一只纸。", "explanation": "这里应该用〈张〉。纸的量词是“张”，不能用“只”。"}, {"text": "妈妈用纸煮了一锅粥。", "explanation": "这里应该用〈米〉。纸不能用来煮东西，煮粥要用米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20156, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "纸", "is_correct": true, "explanation": "正确答案：纸（zhǐ），意思是写字画画的薄片材料。"}, {"text": "制", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是制作。"}, {"text": "齿", "is_correct": false, "explanation": "chǐ 与 zhǐ 声母不同（ch 与 zh），意思是牙齿。"}, {"text": "始", "is_correct": false, "explanation": "shǐ 与 zhǐ 声母不同（sh 与 zh），意思是开始。"}, {"text": "紫", "is_correct": false, "explanation": "zǐ 与 zhǐ 声母不同（z 与 zh），意思是紫色。"}], "explanations": {"纸": "正确答案：纸（zhǐ），意思是写字画画的薄片材料。", "制": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是制作。", "齿": "chǐ 与 zhǐ 声母不同（ch 与 zh），意思是牙齿。", "始": "shǐ 与 zhǐ 声母不同（sh 与 zh），意思是开始。", "紫": "zǐ 与 zhǐ 声母不同（z 与 zh），意思是紫色。"}, "sentence_index": null, "correct_answer": "纸"}, "level_3": {"options": [{"text": "纸", "is_correct": true, "explanation": "正确：“每人一张纸”，“张”用于纸张。"}, {"text": "笔", "is_correct": false, "explanation": "搭配：笔用“支”计量，量词“张”不搭配“笔”。"}, {"text": "水", "is_correct": false, "explanation": "语义：“水”不能用“一张”计量，“一张水”语义不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：书用“本”计量，不能说“一张书”。"}], "explanations": {"纸": "正确：“每人一张纸”，“张”用于纸张。", "笔": "搭配：笔用“支”计量，量词“张”不搭配“笔”。", "水": "语义：“水”不能用“一张”计量，“一张水”语义不通。", "书": "搭配：书用“本”计量，不能说“一张书”。"}, "sentence_index": 6, "correct_answer": "纸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在纸前整理头发。", "explanation": "这里应该用〈镜子〉。纸不能反射人影，不能用来照着整理头发。"}, {"text": "我买了一把纸。", "explanation": "这里应该用〈张〉。纸的量词是“张”，不能用“把”。"}, {"text": "他端着纸喝水。", "explanation": "这里应该用〈杯子〉。纸不能盛水，不能用来喝水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师发给我们两只纸。", "corrected_sentence": "老师发给我们两张纸。", "error_description": "错误形式：“两只纸”；正确形式：“两张纸”。纸的量词是“张”，“只”用于动物或成对、成个的东西，不能用来数纸。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给了我一张纸白。", "corrected_sentence": "他给了我一张白纸。", "error_description": "错误形式：“纸白”；正确形式：“白纸”。颜色形容词“白”是修饰语，要放在名词“纸”前面，不能放在后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20158, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结束", "is_correct": true, "explanation": "“开始”与“结束”是反义词，分别表示事情从这时起进行与到这时为止。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”与“开始”没有反义关系，它表示的是另一类活动。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”与“开始”没有反义关系，它表示的是头脑中的活动。"}, {"text": "收获", "is_correct": false, "explanation": "“收获”与“开始”没有反义关系，它表示得到成果。"}], "correct_answer": "结束", "explanations": {"结束": "“开始”与“结束”是反义词，分别表示事情从这时起进行与到这时为止。", "旅行": "“旅行”与“开始”没有反义关系，它表示的是另一类活动。", "思考": "“思考”与“开始”没有反义关系，它表示的是头脑中的活动。", "收获": "“收获”与“开始”没有反义关系，它表示得到成果。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20158, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结束", "is_correct": true, "explanation": "“开始”与“结束”是反义词，分别表示事情从这时起进行与到这时为止。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”与“开始”没有反义关系，它表示停下来放松。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”与“开始”没有反义关系，它表示深入探讨。"}, {"text": "种植", "is_correct": false, "explanation": "“种植”与“开始”没有反义关系，它表示栽种植物。"}], "correct_answer": "结束", "explanations": {"结束": "“开始”与“结束”是反义词，分别表示事情从这时起进行与到这时为止。", "休息": "“休息”与“开始”没有反义关系，它表示停下来放松。", "研究": "“研究”与“开始”没有反义关系，它表示深入探讨。", "种植": "“种植”与“开始”没有反义关系，它表示栽种植物。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20158, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "某件事或某个动作从某一时刻起进行。", "primary_collocate": null, "pronunciation": "kāi shǐ", "ipa": "kʰai˥ ʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "电影八点开始，我们快走吧。", "target_word": "开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始了，大家都很高兴。", "target_word": "开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天几点开始上课？", "target_word": "开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议已经开始十分钟了。", "target_word": "开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从上个月开始学中文。", "target_word": "开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一切都从今天开始。", "target_word": "开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，音乐会没法开始。", "target_word": "开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“现在开始考试。”", "target_word": "开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨开始下大了，我们进去吧。", "target_word": "开始", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们开始唱歌，教室里很热闹。", "target_word": "开始", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开始了", "label": "体标"}, {"form": "開始", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某件事或某个动作从这时起进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7740042-aad1-4fe5-9bfb-71d5cfaf9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开始", "is_correct": true, "explanation": "“开始”表示电影从八点起开始放映，与句意相符。"}, {"text": "出发", "is_correct": false, "explanation": "搭配：“出发”多用于人或车船，电影不说“八点出发”。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：电影不会在八点吃饭，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：电影不会在八点睡觉，与“快走吧”的语境不合。"}], "explanations": {"开始": "“开始”表示电影从八点起开始放映，与句意相符。", "出发": "搭配：“出发”多用于人或车船，电影不说“八点出发”。", "吃饭": "语义：电影不会在八点吃饭，句意不通。", "睡觉": "语义：电影不会在八点睡觉，与“快走吧”的语境不合。"}, "sentence_index": 0, "correct_answer": "开始"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这扇门开始了，屋里很亮。", "explanation": "这里应该用〈打开〉。开始指事情或动作从此进行，门被打开不能说“开始”。"}, {"text": "我开始了一个苹果，很好吃。", "explanation": "这里应该用〈洗〉。开始后面接的是动作或事情，不能直接带“一个苹果”这样的物体，要说“洗一个苹果”。"}, {"text": "我开始了三张桌子，擦得很快。", "explanation": "这里应该用〈擦〉。开始后面接的是事情或动作，“三张桌子”是物体，不能直接作它的宾语，要说“擦三张桌子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开始", "is_correct": true, "explanation": "“开始”表示音乐会从这时起进行，与“没法”的句意相符。"}, {"text": "发言", "is_correct": false, "explanation": "搭配：“发言”多用于人，音乐会不会“发言”。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：音乐会不能用来洗澡，与句意不合。"}, {"text": "写字", "is_correct": false, "explanation": "语义：音乐会上不会写字，句意不通。"}], "explanations": {"开始": "“开始”表示音乐会从这时起进行，与“没法”的句意相符。", "发言": "搭配：“发言”多用于人，音乐会不会“发言”。", "洗澡": "语义：音乐会不能用来洗澡，与句意不合。", "写字": "语义：音乐会上不会写字，句意不通。"}, "sentence_index": 6, "correct_answer": "开始"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我开始了电视，屋里很安静。", "explanation": "这里应该用〈关上〉。开始接的是动作或事情，不能直接带“电视”这样的物体。"}, {"text": "我开始了一杯水，觉得很舒服。", "explanation": "这里应该用〈喝〉。开始接的是动作或事情，不能直接带“一杯水”这样的物体。"}, {"text": "他开始了那把椅子，很结实。", "explanation": "这里应该用〈修好〉。开始接的是动作或事情，不能直接带“那把椅子”这样的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校下周开始了招生。", "corrected_sentence": "学校下周开始招生。", "error_description": "“下周”是将来的时间，“开始”后面不能加“了”。错误形式“开始了”应改为“开始”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨又开始了下。", "corrected_sentence": "雨又开始下了。", "error_description": "“了”的位置错误。“开始”后接动词时，“了”应放在整个动词短语末尾，错误形式“开始了下”应改为“开始下了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7041e5ae-641a-4e84-b391-c822496737a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
