INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20164, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手拿笔或别的东西在纸上写字。", "primary_collocate": null, "pronunciation": "shǒu xiě", "ipa": "ʂoʊ˨˩˦ ɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我喜欢手写日记，觉得很有感情。", "target_word": "手写", "complexity_tier": "T3", "furigana": "shǒu xiě", "sentence_source": "generated"}, {"text": "考试要手写，不能用电脑。", "target_word": "手写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求大家手写作业。", "target_word": "手写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很少有人手写信了。", "target_word": "手写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天手写一页字。", "target_word": "手写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡片是我手写的。", "target_word": "手写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手写的字让人觉得很亲切。", "target_word": "手写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你手写自己的名字。", "target_word": "手写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她手写了一份感谢信。", "target_word": "手写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我手写的速度比用手机打字慢。", "target_word": "手写", "complexity_tier": "T3", "furigana": "shǒu xiě", "sentence_source": "generated"}], "morphological_forms": [{"form": "手写了", "label": "完成体"}, {"form": "手写着", "label": "持续体"}, {"form": "手写过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用手拿笔在纸上写字，不用打字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecb8803a-6dd5-492a-a974-71a190af6a2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "手写", "is_correct": true, "explanation": "正确：手写日记是亲手写下的日记，与“很有感情”相合。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：清洗是洗去污物，与“喜欢”和“很有感情”的语境不相合。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：撕碎日记与“喜欢”“很有感情”的语境相反。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：“熨烫”用于衣物、布料，不说“熨烫日记”。"}], "explanations": {"手写": "正确：手写日记是亲手写下的日记，与“很有感情”相合。", "清洗": "语义：清洗是洗去污物，与“喜欢”和“很有感情”的语境不相合。", "撕碎": "语义：撕碎日记与“喜欢”“很有感情”的语境相反。", "熨烫": "搭配：“熨烫”用于衣物、布料，不说“熨烫日记”。"}, "sentence_index": 0, "correct_answer": "手写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在纸上手写了一只猫。", "explanation": "这里应该用〈画〉。手写指用手拿笔写字，在纸上画猫要用“画”。"}, {"text": "她手写了一条围巾。", "explanation": "这里应该用〈织〉。手写指用笔在纸上写字，围巾要用针线织成，应说“织”。"}, {"text": "他大声手写课文。", "explanation": "这里应该用〈朗读〉。手写是用笔写字，不能用来形容大声读课文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手写", "is_correct": true, "explanation": "正确：手写的字是亲笔写的字，让人觉得亲切。"}, {"text": "煎炸", "is_correct": false, "explanation": "语义：煎炸是用油加热食物，与“字”不相合。"}, {"text": "熬煮", "is_correct": false, "explanation": "语义：熬煮是用水长时间加热食物，与“字”不相合。"}, {"text": "熨平", "is_correct": false, "explanation": "搭配：“熨平”用于布料、衣物，不用于文字。"}], "explanations": {"手写": "正确：手写的字是亲笔写的字，让人觉得亲切。", "煎炸": "语义：煎炸是用油加热食物，与“字”不相合。", "熬煮": "语义：熬煮是用水长时间加热食物，与“字”不相合。", "熨平": "搭配：“熨平”用于布料、衣物，不用于文字。"}, "sentence_index": 6, "correct_answer": "手写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工匠在石头上手写了一朵花。", "explanation": "这里应该用〈雕刻〉。手写是用笔在纸上写字，在石头上刻花要用“雕刻”。"}, {"text": "他把衣服手写干净了。", "explanation": "这里应该用〈洗〉。手写是书写动作，不能用来表示洗涤衣物。"}, {"text": "他把墙手写成了白色。", "explanation": "这里应该用〈粉刷〉。手写是用笔写字，不能用来表示给墙涂成白色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他纸上手写了三个字。", "corrected_sentence": "他在纸上手写了三个字。", "error_description": "“纸上”作手写的处所时，前面要加介词“在”，应为“在纸上手写”；这里漏了“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把这封信手写很整齐。", "corrected_sentence": "她把这封信手写得很整齐。", "error_description": "手写带程度补语时，中间要加“得”，应为“手写得很整齐”；这里漏了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8f4eba04-2e57-41b1-9326-8b08de2c943c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
