INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20170, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "书是用来看的东西，上面有很多字和图画。", "primary_collocate": null, "pronunciation": "shū", "ipa": "ʂu˥", "syllable_count": 1, "sentences": [{"text": "我今天买了一本新书。", "target_word": "书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书很好看，我想再看一次。", "target_word": "书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有两本书和一支笔。", "target_word": "书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天晚上都看书。", "target_word": "书", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把书放在桌子上。", "target_word": "书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里的书很多，我常去借。", "target_word": "书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我买了一本有图画的书。", "target_word": "书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是谁的？", "target_word": "书", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在读一本关于猫的书。", "target_word": "书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的包里有三本书。", "target_word": "书", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "本", "label": "量词"}, {"form": "書", "label": "繁体"}, {"form": "书包", "label": "复合"}, {"form": "书店", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来阅读的成册书籍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d8b840b-ee01-4694-9784-5eb6724c58e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20170, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "书", "is_correct": true, "explanation": "正确答案：“书”（shū），即书籍。"}, {"text": "树", "is_correct": false, "explanation": "声调不同：“树”是 shù（第四声），与 shū（第一声）不同，意思是树。"}, {"text": "鼠", "is_correct": false, "explanation": "声调不同：“鼠”是 shǔ（第三声），与 shū（第一声）不同，意思是老鼠。"}, {"text": "沙", "is_correct": false, "explanation": "韵母不同：“沙”是 shā，韵母为 a，与 shū 的 u 不同，意思是沙子。"}], "explanations": {"书": "正确答案：“书”（shū），即书籍。", "树": "声调不同：“树”是 shù（第四声），与 shū（第一声）不同，意思是树。", "鼠": "声调不同：“鼠”是 shǔ（第三声），与 shū（第一声）不同，意思是老鼠。", "沙": "韵母不同：“沙”是 shā，韵母为 a，与 shū 的 u 不同，意思是沙子。"}, "sentence_index": null, "correct_answer": "书"}, "level_3": {"options": [{"text": "书", "is_correct": true, "explanation": "“书”：与“一本”搭配，表示买的书籍，句子成立。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：量词“本”只用于书册，不能用于鞋。"}, {"text": "苹果", "is_correct": false, "explanation": "搭配：量词“本”不能用于苹果，应说“个”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以买的、可数的东西，句子不成立。"}], "explanations": {"书": "“书”：与“一本”搭配，表示买的书籍，句子成立。", "鞋": "搭配：量词“本”只用于书册，不能用于鞋。", "苹果": "搭配：量词“本”不能用于苹果，应说“个”。", "空气": "语义：空气不是可以买的、可数的东西，句子不成立。"}, "sentence_index": 0, "correct_answer": "书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天晚上都喝书。", "explanation": "这里应该用〈水〉。“书”是用来看的，不能喝；喝的东西要用“水”。"}, {"text": "他每天晚上都洗书。", "explanation": "这里应该用〈衣服〉。“书”不能洗，洗的东西要用“衣服”。"}, {"text": "他每天晚上都切书。", "explanation": "这里应该用〈菜〉。“书”不能切，切的东西要用“菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20170, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "书", "is_correct": true, "explanation": "正确答案：“书”（shū），即书籍。"}, {"text": "数", "is_correct": false, "explanation": "声调不同：“数”是 shù（第四声），与 shū（第一声）不同，意思是数字。"}, {"text": "暑", "is_correct": false, "explanation": "声调不同：“暑”是 shǔ（第三声），与 shū（第一声）不同，意思是暑热。"}, {"text": "需", "is_correct": false, "explanation": "声母不同：“需”是 xū，声母为 x，与 shū 的 sh 不同，意思是需要。"}], "explanations": {"书": "正确答案：“书”（shū），即书籍。", "数": "声调不同：“数”是 shù（第四声），与 shū（第一声）不同，意思是数字。", "暑": "声调不同：“暑”是 shǔ（第三声），与 shū（第一声）不同，意思是暑热。", "需": "声母不同：“需”是 xū，声母为 x，与 shū 的 sh 不同，意思是需要。"}, "sentence_index": null, "correct_answer": "书"}, "level_3": {"options": [{"text": "书", "is_correct": true, "explanation": "“书”：有图画的书籍，与“买了一本”相符，句子成立。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不是有图画的印刷品，句子无法成立。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：量词“本”不能用于椅子。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：量词“本”不能用于牛奶，应说“瓶”或“盒”。"}], "explanations": {"书": "“书”：有图画的书籍，与“买了一本”相符，句子成立。", "小狗": "语义：小狗不是有图画的印刷品，句子无法成立。", "椅子": "搭配：量词“本”不能用于椅子。", "牛奶": "搭配：量词“本”不能用于牛奶，应说“瓶”或“盒”。"}, "sentence_index": 6, "correct_answer": "书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他戴着书去上学。", "explanation": "这里应该用〈眼镜〉。“书”不能戴，戴的东西要用“眼镜”。"}, {"text": "他穿着书去上学。", "explanation": "这里应该用〈鞋〉。“书”不能穿，穿的东西要用“鞋”。"}, {"text": "他骑着书去上学。", "explanation": "这里应该用〈自行车〉。“书”不能骑，骑的东西要用“自行车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天借了一个小书。", "corrected_sentence": "我昨天借了一本小书。", "error_description": "量词错误：“书”的量词是“本”，不能说“一个书”。应改为“一本小书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些本书很好看。", "corrected_sentence": "这些书很好看。", "error_description": "量词错误：“这些”后的复数名词前不能再加量词“本”，应说“这些书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
