INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人本来就有的本事或本领。", "primary_collocate": null, "pronunciation": "cái néng", "ipa": "tsʰaɪ˧˥ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他在音乐上很有才能。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师发现了这个孩子的才能。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都有自己的才能。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用自己的才能帮助了很多人。", "target_word": "才能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想找有才能的年轻人。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的才能表现在画画上。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王在工作中发挥了自己的才能。", "target_word": "才能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的才能让大家很佩服。", "target_word": "才能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师会帮学生发现自己的才能。", "target_word": "才能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一种才能，所以很会画画。", "target_word": "才能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "管理才能", "label": "复合词"}, {"form": "艺术才能", "label": "复合词"}], "register": "中性", "sense_fingerprint": "人天生具有的本事、本领", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d47bea1-7ac4-4021-b5ba-f873b2971d0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "才能", "is_correct": true, "explanation": "正确：“有才能”指天生具有的本事，符合句意。"}, {"text": "钱", "is_correct": false, "explanation": "语义：“有钱”指有财富，“在音乐上很有钱”与句意不合。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“力气”指体力，不说“在音乐上很有力气”。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“有时间”指空闲，与句中说的能力方面不合。"}], "explanations": {"才能": "正确：“有才能”指天生具有的本事，符合句意。", "钱": "语义：“有钱”指有财富，“在音乐上很有钱”与句意不合。", "力气": "搭配：“力气”指体力，不说“在音乐上很有力气”。", "时间": "语义：“有时间”指空闲，与句中说的能力方面不合。"}, "sentence_index": 0, "correct_answer": "才能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位作家才能横溢。", "explanation": "这里应该用〈才华〉。“才华横溢”是固定说法，“才能”不与“横溢”搭配。"}, {"text": "这台机器的才能很强。", "explanation": "这里应该用〈性能〉。才能指人的本事，机器的能力要说性能。"}, {"text": "他每天都在练习这项才能。", "explanation": "这里应该用〈技能〉。才能是天生具有的，不能靠练习获得，练习得来的要说技能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "才能", "is_correct": true, "explanation": "正确：“发挥自己的才能”是常见说法，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“发挥”后接的是才能、作用、优势，不说“发挥脾气”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“发挥”不能与“房子”搭配，句中说的是能力的施展。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是物品，不能被“发挥”，与“工作中”的能力施展不合。"}], "explanations": {"才能": "正确：“发挥自己的才能”是常见说法，符合句意。", "脾气": "搭配：“发挥”后接的是才能、作用、优势，不说“发挥脾气”。", "房子": "搭配：“发挥”不能与“房子”搭配，句中说的是能力的施展。", "汽车": "语义：汽车是物品，不能被“发挥”，与“工作中”的能力施展不合。"}, "sentence_index": 6, "correct_answer": "才能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有一块才能，所以很会画画。", "explanation": "这里量词用错。才能是抽象名词，不能用“块”，应说“一种才能”。"}, {"text": "她有一只才能，唱歌很好听。", "explanation": "这里量词用错。“只”用于动物或成对的物件，不用于才能，应说“一种才能”。"}, {"text": "老师发现了一颗才能。", "explanation": "这里量词用错。“颗”用于颗粒状的东西，才能是抽象的，应说“一种才能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很才能。", "corrected_sentence": "她很有才能。", "error_description": "错误：“很才能”。正确：“很有才能”。才能作谓语前要带动词“有”，省略“有”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师发现了这个学生的一条才能。", "corrected_sentence": "老师发现了这个学生的一种才能。", "error_description": "错误：“一条才能”。正确：“一种才能”。“条”用于细长的东西，才能是抽象的，应用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贵", "is_correct": true, "explanation": "“贵”与“便宜”意思相反，指价钱高、花钱多。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”说卫生状况，与价钱高低没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”说声音或环境，与“便宜”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容人的智力，与“便宜”没有反义关系。"}], "correct_answer": "贵", "explanations": {"贵": "“贵”与“便宜”意思相反，指价钱高、花钱多。", "干净": "“干净”说卫生状况，与价钱高低没有反义关系。", "安静": "“安静”说声音或环境，与“便宜”没有反义关系。", "聪明": "“聪明”形容人的智力，与“便宜”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贵", "is_correct": true, "explanation": "“贵”与“便宜”意思相反，指价钱高、花钱多。"}, {"text": "勇敢", "is_correct": false, "explanation": "“勇敢”形容人的品质，与“便宜”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”说排列或外观规整，与价钱高低没有反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "“结实”说物品耐用，与“便宜”没有反义关系。"}], "correct_answer": "贵", "explanations": {"贵": "“贵”与“便宜”意思相反，指价钱高、花钱多。", "勇敢": "“勇敢”形容人的品质，与“便宜”没有反义关系。", "整齐": "“整齐”说排列或外观规整，与价钱高低没有反义关系。", "结实": "“结实”说物品耐用，与“便宜”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西花的钱少。", "primary_collocate": null, "pronunciation": "pián yi", "ipa": "pʰiɛn˧˥ i", "syllable_count": 2, "sentences": [{"text": "这件衣服很便宜，只要三十块。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的水果比市场便宜。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买便宜一点儿的手机。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜又好吃又便宜。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋太便宜了，我买了两双。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种青菜在早市比较便宜。", "target_word": "便宜", "complexity_tier": "T3", "furigana": "zhè zhǒng qīngcài zài zǎoshì bǐjiào piányi", "sentence_source": "generated"}, {"text": "书店里的旧书很便宜。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁比打车便宜多了。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子不便宜，要八十块。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这家店的东西真便宜。", "target_word": "便宜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "便宜了", "label": "体标"}], "register": "口语", "sense_fingerprint": "东西价格低，花钱少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c8b8646-9bcc-4bda-9fbd-029237946042') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便宜", "is_correct": true, "explanation": "“便宜”说价钱低，与“只要三十块”相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容声音或环境，不能形容衣服的价钱。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”形容味道，衣服不能是甜的，句意不通。"}, {"text": "辛苦", "is_correct": false, "explanation": "搭配：“辛苦”形容人的劳累，不用来形容衣服。"}], "explanations": {"便宜": "“便宜”说价钱低，与“只要三十块”相符。", "安静": "语义：“安静”形容声音或环境，不能形容衣服的价钱。", "甜": "语义：“甜”形容味道，衣服不能是甜的，句意不通。", "辛苦": "搭配：“辛苦”形容人的劳累，不用来形容衣服。"}, "sentence_index": 0, "correct_answer": "便宜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市离我家很便宜。", "explanation": "这里应该用〈方便〉。便宜说价钱低；说距离近、去那里省事要用方便。"}, {"text": "这个问题很便宜，三言两语就解决了。", "explanation": "这里应该用〈简单〉。便宜说价钱低；说事情容易做、不费力要用简单。"}, {"text": "这座城市的气候很便宜。", "explanation": "这里应该用〈宜人〉。便宜说价钱低；形容气候、环境舒适要用宜人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便宜", "is_correct": true, "explanation": "“便宜”说价钱低，书店里的旧书价钱低，句意通顺。"}, {"text": "新鲜", "is_correct": false, "explanation": "语义：“新鲜”与“旧书”矛盾，不能说旧书新鲜。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”形容人或生物，不用来形容书。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”形容味道，书没有辣味，句意不通。"}], "explanations": {"便宜": "“便宜”说价钱低，书店里的旧书价钱低，句意通顺。", "新鲜": "语义：“新鲜”与“旧书”矛盾，不能说旧书新鲜。", "年轻": "搭配：“年轻”形容人或生物，不用来形容书。", "辣": "语义：“辣”形容味道，书没有辣味，句意不通。"}, "sentence_index": 6, "correct_answer": "便宜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这款软件操作很便宜。", "explanation": "这里应该用〈便捷〉。便宜说价钱低；说操作简单、使用快捷要用便捷。"}, {"text": "我们这次聚会很便宜，大家玩得很开心。", "explanation": "这里应该用〈热闹〉。便宜说价钱低；说聚会气氛好、很有生气要用热闹。"}, {"text": "这次考试的时间很便宜，大家都做完了。", "explanation": "这里应该用〈充足〉。便宜只说价钱低，不能形容时间；说时间够用要用充足。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些了水果今天便宜了。", "corrected_sentence": "这些水果今天便宜了。", "error_description": "“了”的位置错误：“了”不能插在定语“这些”和名词“水果”之间，删去这个多余的“了”即可。句末的“了”表示变化，应保留。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的衣服比商场便宜多得。", "corrected_sentence": "这家店的衣服比商场便宜得多。", "error_description": "错误：程度补语的语序错误，“便宜多得”应为“便宜得多”，“得”要紧跟动词或形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a53a4e43-2287-4146-a511-a2474c521273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
