INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20186, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使消息、疾病、文化等从一处或一人扩散到别处或别人。", "primary_collocate": null, "pronunciation": "chuán bō", "ipa": "ʈʂʰwan˧˥ po˥", "syllable_count": 2, "sentences": [{"text": "感冒病毒会通过空气传播。", "target_word": "传播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好消息很快在学校里传播开了。", "target_word": "传播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机让新闻传播得更快。", "target_word": "传播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚊子会传播一些疾病。", "target_word": "传播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种谣言在网上传播得很快。", "target_word": "传播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把中国文化传播到世界各地。", "target_word": "传播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗手可以减少细菌的传播。", "target_word": "传播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视和网络帮助知识传播。", "target_word": "传播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事在村子里传播了很多年。", "target_word": "传播", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种病不会通过握手传播。", "target_word": "传播", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传播了", "label": "体标"}, {"form": "传播着", "label": "体标"}, {"form": "传播过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，使消息、疾病、文化等从一处或一人扩散到别处或别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ceb66b7-4790-48b5-8313-3c93963dc888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传播", "is_correct": true, "explanation": "正确：“传播”表示病毒等在空气中向外扩散，与“通过空气”搭配自然。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生命体变大，不能表示病毒通过空气扩散。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”需要在水中进行，不能与“空气”搭配。"}, {"text": "呼吸", "is_correct": false, "explanation": "配价：“呼吸”的对象是空气本身，不能用“通过空气”表示病毒的扩散途径。"}], "explanations": {"传播": "正确：“传播”表示病毒等在空气中向外扩散，与“通过空气”搭配自然。", "生长": "语义：“生长”指生命体变大，不能表示病毒通过空气扩散。", "游泳": "搭配：“游泳”需要在水中进行，不能与“空气”搭配。", "呼吸": "配价：“呼吸”的对象是空气本身，不能用“通过空气”表示病毒的扩散途径。"}, "sentence_index": 0, "correct_answer": "传播"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们把作业传播给老师。", "explanation": "这里应该用〈传递〉。把东西从一人交到另一人用“传递”，“传播”指消息、疾病等向很多人扩散，不用于交作业。"}, {"text": "血液把氧气传播到全身。", "explanation": "这里应该用〈输送〉。通过血液或管道运送物质用“输送”，“传播”不用于运送氧气。"}, {"text": "他把数据传播到了电脑里。", "explanation": "这里应该用〈输入〉。把数据送进电脑用“输入”，“传播”指消息在许多人之间扩散，不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传播", "is_correct": true, "explanation": "正确：“传播”表示细菌等向外扩散，与“细菌的”和“减少”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：“颜色”是外观特征，细菌的颜色不能被“减少”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：细菌的名字与洗手带来的卫生效果无关，不能被“减少”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“减少”不能用于细菌的年龄，这里的意思是减少细菌的扩散。"}], "explanations": {"传播": "正确：“传播”表示细菌等向外扩散，与“细菌的”和“减少”的语境相符。", "颜色": "体貌：“颜色”是外观特征，细菌的颜色不能被“减少”。", "名字": "语义：细菌的名字与洗手带来的卫生效果无关，不能被“减少”。", "年龄": "语义：“减少”不能用于细菌的年龄，这里的意思是减少细菌的扩散。"}, "sentence_index": 6, "correct_answer": "传播"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用卡车把货物传播到外地。", "explanation": "这里应该用〈运输〉。用车船把货物运到别处用“运输”，“传播”指消息、疾病等扩散，不用于搬运货物。"}, {"text": "我把邮件传播给了老师。", "explanation": "这里应该用〈发送〉。把一封邮件送给某人用“发送”，“传播”指消息在很多人之间扩散，不用于单独一封邮件。"}, {"text": "医生把药液传播到血管里。", "explanation": "这里应该用〈注入〉。用针管等把液体送入体内用“注入”，“传播”不用于这种送入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个消息在公司里很快传播了开。", "corrected_sentence": "这个消息在公司里很快传播开了。", "error_description": "错误在于补语“开”的位置：“传播开”是动补结构，“了”应放在“开”之后。写成“传播了开”是错的，正确说法是“传播开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20186, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条消息在网上把传播得特别快。", "corrected_sentence": "这条消息在网上传播得特别快。", "error_description": "错误在于多加了“把”：“把”字句要求后面带处置对象，这里没有宾语，应去掉“把”，说“这条消息在网上传播得特别快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
