INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20196, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "印刷机是一种能把字印到纸上的机器。", "primary_collocate": null, "pronunciation": "yìn shuā jī", "ipa": "in˥˩ ʂwa˥ tɕi˥", "syllable_count": 3, "sentences": [{"text": "工厂里有一台大印刷机。", "target_word": "印刷机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台印刷机一分钟能印很多书。", "target_word": "印刷机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷机坏了，今天不能印报纸。", "target_word": "印刷机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查印刷机。", "target_word": "印刷机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷机把字印到纸上。", "target_word": "印刷机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家印刷厂买了一台新印刷机。", "target_word": "印刷机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前的印刷机很慢，现在的很快。", "target_word": "印刷机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷机一开，房间里就很吵。", "target_word": "印刷机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工厂里开印刷机。", "target_word": "印刷机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷机没有纸了，要再放一些。", "target_word": "印刷机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}], "register": "中性", "sense_fingerprint": "能把字和图印到纸上的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cff21b5d-b947-4065-949c-1c97782d2ed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印刷机", "is_correct": true, "explanation": "印刷机：能把字印到纸上的机器，符合“工厂里”和“一台大”的语境。"}, {"text": "奶茶", "is_correct": false, "explanation": "语义与量词：“奶茶”是饮品，量词用“杯”，不能用“台”，句子不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义与量词：“月亮”量词用“轮”，且不是工厂里的设备，句子不通。"}, {"text": "文章", "is_correct": false, "explanation": "量词与语义：“文章”量词用“篇”，不能用“台”，句子不通。"}], "explanations": {"印刷机": "印刷机：能把字印到纸上的机器，符合“工厂里”和“一台大”的语境。", "奶茶": "语义与量词：“奶茶”是饮品，量词用“杯”，不能用“台”，句子不通。", "月亮": "语义与量词：“月亮”量词用“轮”，且不是工厂里的设备，句子不通。", "文章": "量词与语义：“文章”量词用“篇”，不能用“台”，句子不通。"}, "sentence_index": 0, "correct_answer": "印刷机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用印刷机复印一份合同。", "explanation": "这里应该用〈复印机〉。印刷机用于大批量印刷，复印少量文件要用复印机。"}, {"text": "他每天用印刷机打印作业。", "explanation": "这里应该用〈打印机〉。印刷机是印刷厂用的大型设备，打印作业要用打印机。"}, {"text": "我们工厂买了一只新印刷机。", "explanation": "这里应该用〈台〉。印刷机属于机器，量词用“台”，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印刷机", "is_correct": true, "explanation": "印刷机：能把字印到纸上的机器，符合“以前”和“现在”对比速度的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能用“很慢”描述速度，句意不通。"}, {"text": "楼房", "is_correct": false, "explanation": "语义：“楼房”不存在快慢的变化，不能说“很慢”。"}, {"text": "眼神", "is_correct": false, "explanation": "搭配：“慢”与“眼神”不搭配，不能说“眼神很慢”。"}], "explanations": {"印刷机": "印刷机：能把字印到纸上的机器，符合“以前”和“现在”对比速度的语境。", "天气": "语义：“天气”不能用“很慢”描述速度，句意不通。", "楼房": "语义：“楼房”不存在快慢的变化，不能说“很慢”。", "眼神": "搭配：“慢”与“眼神”不搭配，不能说“眼神很慢”。"}, "sentence_index": 6, "correct_answer": "印刷机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在印刷机上班。", "explanation": "这里应该用〈印刷厂〉。人工作的地方要说“印刷厂”，印刷机是机器。"}, {"text": "这台印刷机每年出版很多书。", "explanation": "这里应该用〈出版社〉。印刷机只负责印刷，出版书籍要用“出版社”。"}, {"text": "他用印刷机写信。", "explanation": "这里应该用〈打字机〉。印刷机用于成批印刷，写信要用打字机或笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂的角落里有一条大印刷机。", "corrected_sentence": "工厂的角落里有一台大印刷机。", "error_description": "量词错误：“印刷机”是机器，量词要用“台”，不能用“条”，应说“一台大印刷机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台印刷机印的很快。", "corrected_sentence": "这台印刷机印得很快。", "error_description": "补语标记错误：表示“印得怎么样”的补语要用“得”，不用“的”，应说“印得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06e9b3d7-70e6-4769-b272-27bad7ef97aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
