INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20201, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机器是一种能帮人做事情的铁东西。", "primary_collocate": null, "pronunciation": "jī qì", "ipa": "tɕi˥ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "工厂里有很多大机器。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器坏了，需要修理。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器可以帮人做重复的工作。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器怎么开？请你教教我。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器一开，整个房间都很吵。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人每天要检查机器。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新机器比旧机器快两倍。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用机器收麦子。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器没有电就不能工作。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板花了很多钱买机器。", "target_word": "机器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台机器", "label": "量词"}, {"form": "一部机器", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，能代替人工作的机械装置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ceb66b7-4790-48b5-8313-3c93963dc888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20201, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机器", "is_correct": true, "explanation": "正确：“机器”指能帮人工作的装置，工厂里有很多大机器，语义与搭配都自然。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不会出现在工厂里，这里的语境是车间设备。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：“大”不修饰“语言”，说“大语言”不搭配。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：工厂里不会有海洋，与“工厂里有”的语境矛盾。"}], "explanations": {"机器": "正确：“机器”指能帮人工作的装置，工厂里有很多大机器，语义与搭配都自然。", "星星": "语义：星星不会出现在工厂里，这里的语境是车间设备。", "语言": "搭配：“大”不修饰“语言”，说“大语言”不搭配。", "海洋": "语义：工厂里不会有海洋，与“工厂里有”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "机器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把锤子是我最常用的机器。", "explanation": "这里应该用〈工具〉。锤子是手用的、不带动力的用具，应说“工具”，“机器”指有动力的装置。"}, {"text": "他学的是机器工程。", "explanation": "这里应该用〈机械〉。学科名称“机械工程”是固定说法，“机器”不用于这一名称。"}, {"text": "车间里新装了一只机器。", "explanation": "这里应该用〈台〉。机器作为装置的量词用“台”；“只”用于动物或特定的物件，不用于机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20201, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机器", "is_correct": true, "explanation": "正确：“新机器”与后半句“旧机器”相互比较，快慢的对象是机器，语义自然。"}, {"text": "花", "is_correct": false, "explanation": "语义：“花”是植物，不能拿来与旧机器比较快慢。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“电影”不能与旧机器比较工作速度，这里的比较对象应是机器。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“快两倍”说的是速度或效率，不与“小说”搭配。"}], "explanations": {"机器": "正确：“新机器”与后半句“旧机器”相互比较，快慢的对象是机器，语义自然。", "花": "语义：“花”是植物，不能拿来与旧机器比较快慢。", "电影": "语义：“电影”不能与旧机器比较工作速度，这里的比较对象应是机器。", "小说": "搭配：“快两倍”说的是速度或效率，不与“小说”搭配。"}, "sentence_index": 6, "correct_answer": "机器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校操场上摆着一套体育机器。", "explanation": "这里应该用〈器械〉。“体育器械”是固定说法，指健身用的器材；“机器”指有动力的装置，不用于健身器材。"}, {"text": "车上有一个安全机器，很重要。", "explanation": "这里应该用〈装置〉。“安全装置”是固定说法，“机器”指能工作的机械，不用于这种安全部件。"}, {"text": "汽车的机器显示速度。", "explanation": "这里应该用〈仪表〉。显示数值的部件是“仪表”，“机器”不用于指示速度的仪表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车间里那只机器坏了，需要修理。", "corrected_sentence": "车间里那台机器坏了，需要修理。", "error_description": "错误在于量词：“机器”用“台”计量，写成“那只机器”是错的，正确说法是“那台机器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台新机器把跑得特别快。", "corrected_sentence": "这台新机器跑得特别快。", "error_description": "错误在于多加了“把”：“跑”后面没有处置对象，不能用“把”字句，应去掉“把”，说“这台新机器跑得特别快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
