INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20210, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "小朋友去学校学习。", "primary_collocate": null, "pronunciation": "shàng xué", "ipa": "ʂɑŋ˥˩ ɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "我每天坐公交车上学。", "target_word": "上学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟今年六岁，下个月开始上学。", "target_word": "上学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明早上七点就去上学了。", "target_word": "上学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子上学以前，要先买书包。", "target_word": "上学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "女儿喜欢上学，因为学校有很多朋友。", "target_word": "上学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，爸爸开车送我上学。", "target_word": "上学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家离学校很远，走路上学要一个小时。", "target_word": "上学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天不用上学，我们去公园玩。", "target_word": "上学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她十岁才开始上学。", "target_word": "上学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外面下大雪，孩子们还是高高兴兴地去上学。", "target_word": "上学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上了学", "label": "体标"}, {"form": "上过学", "label": "体标"}, {"form": "上不了学", "label": "可能补语"}], "register": "口语", "sense_fingerprint": "孩子去学校学习", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7728ca8c-cc31-47be-a40d-da0fcf2ae697') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上学", "is_correct": true, "explanation": "正确：“坐公交车上学”指乘车去学校，与句意吻合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：坐公交车不能去游泳，与句中“坐公交车”的行为不符。"}, {"text": "做饭", "is_correct": false, "explanation": "搭配：“坐公交车”之后不能接“做饭”这类家务，搭配不当。"}, {"text": "种花", "is_correct": false, "explanation": "语义：公交车上不能种花，句意不通。"}], "explanations": {"上学": "正确：“坐公交车上学”指乘车去学校，与句意吻合。", "游泳": "语义：坐公交车不能去游泳，与句中“坐公交车”的行为不符。", "做饭": "搭配：“坐公交车”之后不能接“做饭”这类家务，搭配不当。", "种花": "语义：公交车上不能种花，句意不通。"}, "sentence_index": 0, "correct_answer": "上学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈是老师，每天八点上学。", "explanation": "这里应该用〈上班〉。上学指学生去学校学习，老师工作要说“上班”。"}, {"text": "小狗每天上学。", "explanation": "这里应该用〈散步〉。上学指小朋友去学校学习，小狗不能上学，应说“散步”。"}, {"text": "工厂下周上学。", "explanation": "这里应该用〈开工〉。上学的主语是学生，工厂开始生产应说“开工”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上学", "is_correct": true, "explanation": "正确：“走路上学”与“离学校很远”相呼应，指步行去学校所需的时间。"}, {"text": "修车", "is_correct": false, "explanation": "语义：“修车”与“走路”的路程无关，句意不通。"}, {"text": "洗衣服", "is_correct": false, "explanation": "搭配：“走路”不能与“洗衣服”搭配成一个行为。"}, {"text": "织毛衣", "is_correct": false, "explanation": "语义：“织毛衣”与“离学校很远”的路程无关，句意不通。"}], "explanations": {"上学": "正确：“走路上学”与“离学校很远”相呼应，指步行去学校所需的时间。", "修车": "语义：“修车”与“走路”的路程无关，句意不通。", "洗衣服": "搭配：“走路”不能与“洗衣服”搭配成一个行为。", "织毛衣": "语义：“织毛衣”与“离学校很远”的路程无关，句意不通。"}, "sentence_index": 6, "correct_answer": "上学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆出租车每天早上都上学。", "explanation": "这里应该用〈出车〉。“上学”的主语应是学生，出租车每天出去载客应说“出车”。"}, {"text": "我每晚睡前都上学。", "explanation": "这里应该用〈读书〉。上学指去学校学习，睡前在家看书不说“上学”。"}, {"text": "他每天在工地上学。", "explanation": "这里应该用〈上班〉。上学指去学校学习，在工地干活要说“上班”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他上学过三年，才去工作。", "corrected_sentence": "他上过三年学，才去工作。", "error_description": "错误形式：“上学过”，把体标“过”放在离合词“上学”之后。离合词的体标应插在“上”与“学”之间，正确形式为“上过三年学”，即把“过”移到“上”与“学”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他因为生病，这学期上学了不了。", "corrected_sentence": "他因为生病，这学期上不了学。", "error_description": "错误形式：“上学了不了”，把可能补语“不了”整个放在了离合词“上学”的“学”之后。可能补语应插在“上”与“学”之间，正确形式为“上不了学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4b033eb-cb43-4dec-bf2c-2807df4a1281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
