INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20212, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "孩子就是小男孩或小女孩。", "primary_collocate": null, "pronunciation": "hái zi", "ipa": "xaɪ̯˧˥ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "这个孩子很可爱。", "target_word": "孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家有两个孩子，都在上小学。", "target_word": "孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子在公园里玩。", "target_word": "孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子饿了，快给他做饭。", "target_word": "孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每天送孩子去上学。", "target_word": "孩子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个孩子才三岁，还不会写字。", "target_word": "孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子睡着了，请小声一点。", "target_word": "孩子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子哭了，因为他找不到妈妈。", "target_word": "孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的孩子喜欢画画，也喜欢唱歌。", "target_word": "孩子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，这个孩子学得很快。", "target_word": "孩子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "孩子们", "label": "复数"}], "register": "中性", "sense_fingerprint": "年纪还小的男孩或女孩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1994afce-084b-4c4b-8b0f-90dace7d412c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20212, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "孩子", "is_correct": true, "explanation": "“孩子”指年纪小的男孩或女孩，是本词。"}, {"text": "还是", "is_correct": false, "explanation": "háishi 与 háizi 第二音节声母不同（sh 与 z），意思是“还是”。"}, {"text": "牌子", "is_correct": false, "explanation": "páizi 与 háizi 首音节声母不同（p 与 h），意思是“牌子”。"}, {"text": "盒子", "is_correct": false, "explanation": "hézi 与 háizi 首音节韵母不同（e 与 ai），意思是“盒子”。"}], "explanations": {"孩子": "“孩子”指年纪小的男孩或女孩，是本词。", "还是": "háishi 与 háizi 第二音节声母不同（sh 与 z），意思是“还是”。", "牌子": "páizi 与 háizi 首音节声母不同（p 与 h），意思是“牌子”。", "盒子": "hézi 与 háizi 首音节韵母不同（e 与 ai），意思是“盒子”。"}, "sentence_index": null, "correct_answer": "孩子"}, "level_3": {"options": [{"text": "孩子", "is_correct": true, "explanation": "“孩子”指年纪小的男孩或女孩，符合“很可爱”的评价。"}, {"text": "病", "is_correct": false, "explanation": "语义：“病”指身体不适，不能用“可爱”来形容。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是测验活动，不能说“很可爱”。"}, {"text": "报告", "is_correct": false, "explanation": "搭配：“可爱”用于人或动物等能被喜爱的对象，不与“报告”搭配。"}], "explanations": {"孩子": "“孩子”指年纪小的男孩或女孩，符合“很可爱”的评价。", "病": "语义：“病”指身体不适，不能用“可爱”来形容。", "考试": "语义：“考试”是测验活动，不能说“很可爱”。", "报告": "搭配：“可爱”用于人或动物等能被喜爱的对象，不与“报告”搭配。"}, "sentence_index": 0, "correct_answer": "孩子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有一只孩子，很可爱。", "explanation": "这里应该用〈个〉。“只”用于动物或成对的东西，指人的“孩子”要用量词“个”。"}, {"text": "他是我的孩子，我们决定明年结婚。", "explanation": "这里应该用〈对象〉。“孩子”指年纪小的男孩或女孩，不能指要结婚的成年人。"}, {"text": "我的父母是我的孩子，我每天照顾他们。", "explanation": "这里应该用〈长辈〉。“孩子”指年纪小的男孩或女孩，不能指父母这样的成年人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孩子", "is_correct": true, "explanation": "“孩子”是会睡觉的小孩，与“睡着了”相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”没有生命，不能“睡着”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是无生命的物体，不会“睡着”。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“睡着”只用于人或动物，不与“作业”搭配。"}], "explanations": {"孩子": "“孩子”是会睡觉的小孩，与“睡着了”相符。", "桌子": "语义：“桌子”没有生命，不能“睡着”。", "窗户": "语义：“窗户”是无生命的物体，不会“睡着”。", "作业": "搭配：“睡着”只用于人或动物，不与“作业”搭配。"}, "sentence_index": 6, "correct_answer": "孩子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子是一本书，可以读。", "explanation": "“孩子”指人，指小男孩或小女孩，不能用来指书这类物品。"}, {"text": "那个孩子是一位八十岁的老爷爷，每天在公园里下棋。", "explanation": "“孩子”指年纪小的人，不能用来指八十岁的老人。"}, {"text": "那几位孩子是大学老师，他们每天给学生上课。", "explanation": "“孩子”指年纪小的人，不能指大学老师这样的成年人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子书的在桌子上。", "corrected_sentence": "孩子的书在桌子上。", "error_description": "“的”应紧跟定语“孩子”，说“孩子的书”；“孩子书的”是错误的语序。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子们在教室里画画。", "corrected_sentence": "这个孩子在教室里画画。", "error_description": "“这个”指单数，“孩子们”表示复数，二者不能搭配，应去掉“们”，说“这个孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "更慢", "is_correct": true, "explanation": "正确：“快”与“慢”相对，“更快”作比较时与“更慢”是反义。"}, {"text": "确实", "is_correct": false, "explanation": "无关：“确实”表示真实可信，与“更快”的速度比较没有反义关系。"}, {"text": "一直", "is_correct": false, "explanation": "无关：“一直”表示持续，与“更快”的速度比较没有反义关系。"}, {"text": "已经", "is_correct": false, "explanation": "无关：“已经”表示完成或已发生，与“更快”的速度比较没有反义关系。"}], "correct_answer": "更慢", "explanations": {"更慢": "正确：“快”与“慢”相对，“更快”作比较时与“更慢”是反义。", "确实": "无关：“确实”表示真实可信，与“更快”的速度比较没有反义关系。", "一直": "无关：“一直”表示持续，与“更快”的速度比较没有反义关系。", "已经": "无关：“已经”表示完成或已发生，与“更快”的速度比较没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "更慢", "is_correct": true, "explanation": "正确：“快”与“慢”相对，“更快”作比较时与“更慢”是反义。"}, {"text": "依然", "is_correct": false, "explanation": "无关：“依然”表示状态没有改变，与“更快”的速度比较没有反义关系。"}, {"text": "总是", "is_correct": false, "explanation": "无关：“总是”表示一贯如此，与“更快”的速度比较没有反义关系。"}, {"text": "突然", "is_correct": false, "explanation": "无关：“突然”表示出乎意料，与“更快”的速度比较没有反义关系。"}], "correct_answer": "更慢", "explanations": {"更慢": "正确：“快”与“慢”相对，“更快”作比较时与“更慢”是反义。", "依然": "无关：“依然”表示状态没有改变，与“更快”的速度比较没有反义关系。", "总是": "无关：“总是”表示一贯如此，与“更快”的速度比较没有反义关系。", "突然": "无关：“突然”表示出乎意料，与“更快”的速度比较没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容速度比原来更大。", "primary_collocate": null, "pronunciation": "gèng kuài", "ipa": "kɤŋ˥˩ kʰwaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "坐高铁去上海更快，我们别坐大巴吧。", "target_word": "更快", "complexity_tier": "T3", "furigana": "zuò gāo tiě qù shàng hǎi gèng kuài, wǒ men bié zuò dà bā ba", "sentence_source": "generated"}, {"text": "我想跑得更快一点。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新软件更快，打开文件很方便。", "target_word": "更快", "complexity_tier": "T3", "furigana": "zhè ge xīn ruǎn jiàn gèng kuài, dǎ kāi wén jiàn hěn fāng biàn", "sentence_source": "generated"}, {"text": "他每天练习，所以游得更快了。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车去更快，我们一起骑车吧。", "target_word": "更快", "complexity_tier": "T3", "furigana": "qí chē qù gèng kuài, wǒ men yì qǐ qí chē ba", "sentence_source": "generated"}, {"text": "网速变得更快了。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁去机场更快，路上不堵车。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你多练习，会进步得更快。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天跑得更快了，因为天气好。", "target_word": "更快", "complexity_tier": "T3", "furigana": "wǒ jīn tiān pǎo de gèng kuài le, yīn wèi tiān qì hǎo", "sentence_source": "generated"}, {"text": "风越来越大，船开得更快了。", "target_word": "更快", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "速度比原来或比别的更大，比较之后更快", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73bdc592-5317-4323-ab99-fe56d44fcace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更快", "is_correct": true, "explanation": "正确：“更快”表示高铁速度比大巴更大，与后句“别坐大巴”呼应。"}, {"text": "更慢", "is_correct": false, "explanation": "语义：“更慢”与“更快”意思相反，说高铁更慢与“别坐大巴”的建议矛盾。"}, {"text": "太慢", "is_correct": false, "explanation": "语义：“太慢”说高铁过慢，与“更快”的比较和“别坐大巴”的推荐矛盾。"}, {"text": "最慢", "is_correct": false, "explanation": "语义：“最慢”指所有之中最慢，与“别坐大巴”的推荐矛盾。"}], "explanations": {"更快": "正确：“更快”表示高铁速度比大巴更大，与后句“别坐大巴”呼应。", "更慢": "语义：“更慢”与“更快”意思相反，说高铁更慢与“别坐大巴”的建议矛盾。", "太慢": "语义：“太慢”说高铁过慢，与“更快”的比较和“别坐大巴”的推荐矛盾。", "最慢": "语义：“最慢”指所有之中最慢，与“别坐大巴”的推荐矛盾。"}, "sentence_index": 0, "correct_answer": "更快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的人数更快了。", "explanation": "这里应该用〈更多〉。“更快”说速度的变化，人数的增减要用“更多”或“更少”。"}, {"text": "这件衣服的价格更快了。", "explanation": "这里应该用〈更贵〉。价格的变化是高低，不说快慢，“更快”用错了对象。"}, {"text": "他每天练习，所以成绩更快了。", "explanation": "这里应该用〈更好〉。成绩的变化说高低，不说快慢，“更快”用错了对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更快", "is_correct": true, "explanation": "正确：“坐地铁去机场更快，路上不堵车”是速度比较，“更快”符合句意。"}, {"text": "很慢", "is_correct": false, "explanation": "语义：“很慢”与后句“路上不堵车”及“更快”的比较结论相反。"}, {"text": "稍慢", "is_correct": false, "explanation": "语义：“稍慢”说地铁较慢，与“坐地铁更快”的推荐矛盾。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”表示超出一般的程度，不能用在“去机场”后表示快慢比较。"}], "explanations": {"更快": "正确：“坐地铁去机场更快，路上不堵车”是速度比较，“更快”符合句意。", "很慢": "语义：“很慢”与后句“路上不堵车”及“更快”的比较结论相反。", "稍慢": "语义：“稍慢”说地铁较慢，与“坐地铁更快”的推荐矛盾。", "格外": "搭配：“格外”表示超出一般的程度，不能用在“去机场”后表示快慢比较。"}, "sentence_index": 6, "correct_answer": "更快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "气温更快了。", "explanation": "这里应该用〈更低〉。气温的变化说高低，不说快慢，“更快”用错了对象。"}, {"text": "他这次考试的错误更快了。", "explanation": "这里应该用〈更少〉。错误的变化要用“多、少”，不能说快慢。"}, {"text": "他这个月的工资更快了。", "explanation": "这里应该用〈更高〉。工资的变化说多少、高低，不说快慢，“更快”用错了对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他跑了更快了。", "corrected_sentence": "他跑得更快了。", "error_description": "“得”引出补语“更快了”，不能用“了”代替，应说“跑得更快了”，不能说“跑了更快了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的网速很更快了。", "corrected_sentence": "我的网速更快了。", "error_description": "“更”本身表示程度，不能再加“很”，应说“网速更快了”，不能说“很更快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
