INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20230, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把字或图画印在纸上。", "primary_collocate": null, "pronunciation": "yìn shuā", "ipa": "in˥˩ ʂwa˥", "syllable_count": 2, "sentences": [{"text": "这本书是在北京印刷的。", "target_word": "印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请工厂印刷了一百张海报。", "target_word": "印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门印刷课本。", "target_word": "印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的封面用红色印刷，很好看。", "target_word": "印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在印刷明天的报纸。", "target_word": "印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷以前，请再看一遍。", "target_word": "印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画太大了，没法印刷。", "target_word": "印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种纸印刷出来的字很清楚。", "target_word": "印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把名字印刷在卡片的右上角。", "target_word": "印刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司印刷过很多旅游地图。", "target_word": "印刷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "印刷过", "label": "体标"}, {"form": "印刷厂", "label": "复合"}, {"form": "印刷品", "label": "复合"}], "register": "中性", "sense_fingerprint": "用机器把文字或图画印到纸上，做成书报等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3a92634-fb21-491d-bc46-54f0ac3ab9c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印刷", "is_correct": true, "explanation": "印刷：用机器把字或图印在纸上，书是这样做出来的，符合语境。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪的动作，书不能被煮，句子不通。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”指栽培植物，书不能被种，句意不通。"}, {"text": "熬", "is_correct": false, "explanation": "搭配：“熬”多用于熬粥、熬药，不能说熬书。"}], "explanations": {"印刷": "印刷：用机器把字或图印在纸上，书是这样做出来的，符合语境。", "煮": "语义：“煮”是烹饪的动作，书不能被煮，句子不通。", "种": "语义：“种”指栽培植物，书不能被种，句意不通。", "熬": "搭配：“熬”多用于熬粥、熬药，不能说熬书。"}, "sentence_index": 0, "correct_answer": "印刷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用红色笔在纸上印刷了一朵花。", "explanation": "这里应该用〈画〉。印刷指用机器大量印出字或图，个人用笔画一朵花要用“画”。"}, {"text": "工厂印刷了很多玩具。", "explanation": "这里应该用〈生产〉。印刷只用于印字或图，制作玩具要用“生产”。"}, {"text": "妈妈印刷了一锅粥。", "explanation": "这里应该用〈煮〉。印刷是把字或图画印在纸上，煮粥要用“煮”，不能用印刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印刷", "is_correct": true, "explanation": "印刷：用机器把字或图印出来，画太大所以没法做，符合语境。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指穿衣服，画不能被穿，句子不通。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”指给人或动物吃东西，画不能被喂，句意不通。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”多用于熨烫衣物，不能说烫画。"}], "explanations": {"印刷": "印刷：用机器把字或图印出来，画太大所以没法做，符合语境。", "穿": "语义：“穿”指穿衣服，画不能被穿，句子不通。", "喂": "语义：“喂”指给人或动物吃东西，画不能被喂，句意不通。", "烫": "搭配：“烫”多用于熨烫衣物，不能说烫画。"}, "sentence_index": 6, "correct_answer": "印刷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师印刷了一声招呼。", "explanation": "这里应该用〈打〉。印刷只用于印字或图，打招呼要用“打”。"}, {"text": "妈妈印刷了一盘饺子。", "explanation": "这里应该用〈包〉。印刷只用于印字或图，包饺子要用“包”。"}, {"text": "工人印刷好了那辆自行车。", "explanation": "这里应该用〈修〉。印刷不能用于修理物品，修自行车要用“修”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂今天已经印刷了完这批书。", "corrected_sentence": "工厂今天已经印刷完了这批书。", "error_description": "补语位置错误：结果补语“完”应紧跟“印刷”，“了”放在其后，写成“印刷了完”不对，正确形式是“印刷完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们印刷了过很多宣传册。", "corrected_sentence": "他们印刷过很多宣传册。", "error_description": "体标错误：“了”和“过”不能同时用在动词后，表示经历应说“印刷过”，不说“印刷了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03dd0ea1-fddf-452b-b2a5-cbbda925e434') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
