INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20240, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "两个东西很像。", "primary_collocate": null, "pronunciation": "lèi sì", "ipa": "lei˥˩ sɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这两个故事很类似。", "target_word": "类似", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我也遇到过类似的问题。", "target_word": "类似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法和我的类似。", "target_word": "类似", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店和那家店的菜很类似。", "target_word": "类似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "类似的错误我也犯过。", "target_word": "类似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种水果的味道有点类似。", "target_word": "类似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的工作和老师的工作很类似。", "target_word": "类似", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个手机和我的类似，只是颜色不同。", "target_word": "类似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的经历很类似，都离开过家乡。", "target_word": "类似", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一个类似的例子。", "target_word": "类似", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "类似于", "label": "复合"}], "register": "中性", "sense_fingerprint": "两个事物在样子、性质上相近、很像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ae1b019-e3ac-4d0f-b5df-a846d13cad7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "类似", "is_correct": true, "explanation": "正确答案：表示两个东西很像，符合“这两个故事很……”的句意。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：故事不能“喜欢”，这里说的是两个故事相像。"}, {"text": "担心", "is_correct": false, "explanation": "搭配：“担心”一般用于有感情的人，不能说“故事很担心”。"}, {"text": "害怕", "is_correct": false, "explanation": "语义：故事不会“害怕”，句子说的是两个故事相像。"}], "explanations": {"类似": "正确答案：表示两个东西很像，符合“这两个故事很……”的句意。", "喜欢": "语义：故事不能“喜欢”，这里说的是两个故事相像。", "担心": "搭配：“担心”一般用于有感情的人，不能说“故事很担心”。", "害怕": "语义：故事不会“害怕”，句子说的是两个故事相像。"}, "sentence_index": 0, "correct_answer": "类似"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我类似我爸爸。", "explanation": "这里应该用〈像〉。“像”可以直接带人作宾语，“类似”不能直接带人作宾语，要说“和……类似”。"}, {"text": "这个价格类似三百块。", "explanation": "这里应该用〈接近〉。“接近”可以带数量，“类似”表示相像，不表示数量接近。"}, {"text": "这次考试类似很难。", "explanation": "这里应该用〈比较〉。“比较”可以修饰形容词表示程度；“类似”表示相像，不能修饰形容词表示程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "类似", "is_correct": true, "explanation": "正确答案：表示两份工作很相像，符合“很……”的句意。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：工作不会“讨厌”，句子讲的是两份工作相像。"}, {"text": "尊敬", "is_correct": false, "explanation": "配价：“尊敬”需要一个被尊敬的对象，“工作很尊敬”不成立。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：工作不能“怀念”，这里说的是两者相像。"}], "explanations": {"类似": "正确答案：表示两份工作很相像，符合“很……”的句意。", "讨厌": "语义：工作不会“讨厌”，句子讲的是两份工作相像。", "尊敬": "配价：“尊敬”需要一个被尊敬的对象，“工作很尊敬”不成立。", "怀念": "语义：工作不能“怀念”，这里说的是两者相像。"}, "sentence_index": 6, "correct_answer": "类似"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两件事类似重要。", "explanation": "这里应该用〈同样〉。“同样”可以修饰形容词，表示程度相同；“类似”不能修饰形容词表示程度。"}, {"text": "他类似生病了。", "explanation": "这里应该用〈似乎〉。“似乎”用于推测，“类似”表示相像，不能表示推测。"}, {"text": "类似下雨了。", "explanation": "这里应该用〈好像〉。“好像”用于推测，“类似”不能表示推测，不能说“类似下雨了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两件事和那件事类似于。", "corrected_sentence": "这两件事和那件事类似。", "error_description": "“类似于”是介词结构，后面必须带比较对象；这里缺少宾语，应去掉“于”，改为形容词“类似”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两件类似于的衣服很好看。", "corrected_sentence": "这两件类似的衣服很好看。", "error_description": "“类似于”后缺少比较对象，不能直接加“的”修饰名词，应改为“类似的衣服”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ec80ea24-c7e8-45f6-b780-2a4e3be9e95c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
