INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20242, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一件事做完，让它变好。", "primary_collocate": null, "pronunciation": "zuò chéng", "ipa": "tsuɔ˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这件事我们一定能做成。", "target_word": "做成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个困难的任务，我们一起做成了。", "target_word": "做成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么大的生意，他一个人做成了。", "target_word": "做成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了三年时间，终于把这件事做成了。", "target_word": "做成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要大家努力，这个计划就能做成。", "target_word": "做成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次合作很重要，我们一定要做成。", "target_word": "做成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做成了第一笔生意，很高兴。", "target_word": "做成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这件事很难做成。", "target_word": "做成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她希望这次会议能顺利做成。", "target_word": "做成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们终于做成了这个实验。", "target_word": "做成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做成了", "label": "体标"}], "register": "中性", "sense_fingerprint": "把事情做完并做好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35b906f-46d6-4de6-ad17-6696c52b793f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做成", "is_correct": true, "explanation": "正确：“做成”表示事情做完、做好，符合“这件事我们一定能”的语境。"}, {"text": "做饭", "is_correct": false, "explanation": "语义：“做饭”指烹饪食物，与“这件事”不搭配。"}, {"text": "做梦", "is_correct": false, "explanation": "搭配：“做梦”不能与“一定能”和“这件事”搭配，句子语义不通。"}, {"text": "做客", "is_correct": false, "explanation": "语义：“做客”指到别人家里作客，“这件事”不能去做客。"}], "explanations": {"做成": "正确：“做成”表示事情做完、做好，符合“这件事我们一定能”的语境。", "做饭": "语义：“做饭”指烹饪食物，与“这件事”不搭配。", "做梦": "搭配：“做梦”不能与“一定能”和“这件事”搭配，句子语义不通。", "做客": "语义：“做客”指到别人家里作客，“这件事”不能去做客。"}, "sentence_index": 0, "correct_answer": "做成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做成了一个错误。", "explanation": "这里应该用〈犯〉。“做成”指把事情做完、做好，“错误”要说“犯错误”。"}, {"text": "这个方法做成了作用。", "explanation": "这里应该用〈发挥〉。“做成”不能与“作用”搭配，应说“发挥作用”。"}, {"text": "他做成了一个好朋友。", "explanation": "这里应该用〈交到〉。“做成”指把事情办成或做出实物，结识朋友要说“交到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做成", "is_correct": true, "explanation": "正确：“做成了第一笔生意”，表示生意已经谈成。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“第一笔生意”作宾语。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”不能带宾语，“哭了第一笔生意”不成立。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象不能是“生意”，句子语义不通。"}], "explanations": {"做成": "正确：“做成了第一笔生意”，表示生意已经谈成。", "睡觉": "配价：“睡觉”是不及物动词，不能带“第一笔生意”作宾语。", "哭": "配价：“哭”不能带宾语，“哭了第一笔生意”不成立。", "唱": "语义：“唱”的对象不能是“生意”，句子语义不通。"}, "sentence_index": 6, "correct_answer": "做成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做成了这个问题。", "explanation": "这里应该用〈解决〉。“做成”指把事情做完、做好，“问题”要说“解决”。"}, {"text": "这项计划做成了审核。", "explanation": "这里应该用〈通过〉。“做成”不能与“审核”搭配，应说“通过审核”。"}, {"text": "我们做成了对手。", "explanation": "这里应该用〈打败〉。“做成”不能用来指战胜或击败对手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的计划终于做成了了。", "corrected_sentence": "他的计划终于做成了。", "error_description": "体标错误：“了”重复使用，句末只需一个“了”。正确形式：“做成了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事我一定做成得。", "corrected_sentence": "这件事我一定做得成。", "error_description": "错误形式：“做成得”；正确形式：“做得成”。可能补语的“得”要放在动词和结果补语“成”之间，不能放在“成”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
