INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20254, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不是特别的人，就和很多人一样。", "primary_collocate": null, "pronunciation": "pǔ tōng rén", "ipa": "/pʰu˨˩˦ tʰʊŋ˥ ɻən˧˥/", "syllable_count": 3, "sentences": [{"text": "我只是一个普通人，没有什么特别的本事。", "target_word": "普通人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来就是一个普通人。", "target_word": "普通人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "普通人每天都要上班，也要回家做饭。", "target_word": "普通人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西，普通人也买得起。", "target_word": "普通人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不是明星，只是一位普通人。", "target_word": "普通人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对普通人来说，买房子是大事。", "target_word": "普通人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位大老板平时穿得像普通人一样。", "target_word": "普通人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想做一个快乐的普通人。", "target_word": "普通人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "普通人很难一年去好几个国家玩。", "target_word": "普通人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事讲的是普通人的生活。", "target_word": "普通人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个普通人", "label": "量词：个"}, {"form": "一位普通人", "label": "量词：位"}], "register": "中性", "sense_fingerprint": "没有特殊身份或本领、和大多数人一样的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa75729c-4fdb-4353-ab48-5298e7732270') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普通人", "is_correct": true, "explanation": "正确：「普通人」指没有特殊身份或本领的人，与「没有什么特别的本事」相合。"}, {"text": "天才", "is_correct": false, "explanation": "语义：「天才」指特别有才能的人，与「没有什么特别的本事」矛盾。"}, {"text": "圣人", "is_correct": false, "explanation": "语域：「圣人」带有较强的书面和褒义色彩，不适合这种日常自述。"}, {"text": "专家", "is_correct": false, "explanation": "语义：「专家」指在某领域有专长的人，与「没有什么特别的本事」矛盾。"}], "explanations": {"普通人": "正确：「普通人」指没有特殊身份或本领的人，与「没有什么特别的本事」相合。", "天才": "语义：「天才」指特别有才能的人，与「没有什么特别的本事」矛盾。", "圣人": "语域：「圣人」带有较强的书面和褒义色彩，不适合这种日常自述。", "专家": "语义：「专家」指在某领域有专长的人，与「没有什么特别的本事」矛盾。"}, "sentence_index": 0, "correct_answer": "普通人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口站着一台普通人。", "explanation": "这里应该用〈个〉或〈位〉。「台」用于机器、电器，指人不能用。"}, {"text": "屋里坐着一只普通人。", "explanation": "这里应该用〈个〉或〈位〉。「只」用于动物，指人不能用。"}, {"text": "广场上有一棵普通人。", "explanation": "这里应该用〈个〉或〈位〉。「棵」用于植物，指人不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普通人", "is_correct": true, "explanation": "正确：「普通人」指身份平常的人，与「穿得像……一样」的描写相合。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：「老鼠」是动物，且含贬义，与「大老板」的身份不合。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：「大象」形容体型庞大，与「穿得像……一样」的服饰描写不合。"}, {"text": "水果", "is_correct": false, "explanation": "语义：「水果」是食物，不能用来指人的穿着打扮。"}], "explanations": {"普通人": "正确：「普通人」指身份平常的人，与「穿得像……一样」的描写相合。", "老鼠": "语义：「老鼠」是动物，且含贬义，与「大老板」的身份不合。", "大象": "体貌：「大象」形容体型庞大，与「穿得像……一样」的服饰描写不合。", "水果": "语义：「水果」是食物，不能用来指人的穿着打扮。"}, "sentence_index": 6, "correct_answer": "普通人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这群普通人在草原上吃草。", "explanation": "这里应该说〈羊群〉。「普通人」只指人，不指动物。"}, {"text": "这台电脑是一个普通人。", "explanation": "「普通人」只指人，不能用来指电脑这类物品。"}, {"text": "这棵大树是一个普通人。", "explanation": "「普通人」只指人，不能用来指树这类植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一只普通人。", "corrected_sentence": "她是一位普通人。", "error_description": "错误形式「一只普通人」：「只」用于动物，指人要用「位」或「个」，正确形式为「一位普通人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动邀请了三只普通人。", "corrected_sentence": "这次活动邀请了三个普通人。", "error_description": "错误形式「三只普通人」：「只」用于动物，指人要用「个」或「位」，正确形式为「三个普通人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70aec29e-79c5-4e49-bf56-6fbc2a9c38b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
