INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "寺庙是人们拜佛、念经的房子。", "primary_collocate": null, "pronunciation": "sì miào", "ipa": "sɨ˥˩ mjaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "山上有一座很老的寺庙。", "target_word": "寺庙", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我们去寺庙看看。", "target_word": "寺庙", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "寺庙里的和尚每天早上念经。", "target_word": "寺庙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人到寺庙里拜佛。", "target_word": "寺庙", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座寺庙已经有一千年了。", "target_word": "寺庙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在寺庙门口买了香。", "target_word": "寺庙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "寺庙很安静，我喜欢在那儿坐着。", "target_word": "寺庙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去寺庙是为了拜佛，不是玩。", "target_word": "寺庙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "寺庙旁边有一棵很大的树。", "target_word": "寺庙", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个小城的寺庙每年有很多游客。", "target_word": "寺庙", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "寺廟", "label": "繁体"}], "register": "中性", "sense_fingerprint": "供奉佛像、和尚生活并让人拜佛念经的建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d8b840b-ee01-4694-9784-5eb6724c58e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寺庙", "is_correct": true, "explanation": "正确。“寺庙”是供奉佛像、让人拜佛念经的建筑，与“山上”“很老”搭配自然。"}, {"text": "码头", "is_correct": false, "explanation": "语义：“码头”建在水边，山上不会有码头。"}, {"text": "港口", "is_correct": false, "explanation": "语义：“港口”是船只停靠的水边地方，与“山上”矛盾。"}, {"text": "海滩", "is_correct": false, "explanation": "搭配：“海滩”一般不用“座”来数，而且海滩在水边，与“山上”不合。"}], "explanations": {"寺庙": "正确。“寺庙”是供奉佛像、让人拜佛念经的建筑，与“山上”“很老”搭配自然。", "码头": "语义：“码头”建在水边，山上不会有码头。", "港口": "语义：“港口”是船只停靠的水边地方，与“山上”矛盾。", "海滩": "搭配：“海滩”一般不用“座”来数，而且海滩在水边，与“山上”不合。"}, "sentence_index": 0, "correct_answer": "寺庙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "很多人每周日去寺庙做弥撒。", "explanation": "这里应该用〈教堂〉。“寺庙”是拜佛念经的地方，弥撒是天主教仪式，应去教堂。"}, {"text": "我们去看了一条寺庙。", "explanation": "这里应该用〈座〉。寺庙的量词是〈座〉，用〈条〉是量词用错。"}, {"text": "他去寺庙看病。", "explanation": "这里应该用〈医院〉。寺庙是拜佛念经的地方，不是看病的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寺庙", "is_correct": true, "explanation": "正确。“寺庙”是安静的宗教场所，与“很安静”“我喜欢在那儿坐着”搭配自然。"}, {"text": "夜市", "is_correct": false, "explanation": "语义：夜市通常很热闹，与“很安静”的意思相反。"}, {"text": "工地", "is_correct": false, "explanation": "语义：工地施工时声音很大，不会“很安静”。"}, {"text": "菜市场", "is_correct": false, "explanation": "搭配：“安静”不常用来形容菜市场，菜市场一般说“热闹”。"}], "explanations": {"寺庙": "正确。“寺庙”是安静的宗教场所，与“很安静”“我喜欢在那儿坐着”搭配自然。", "夜市": "语义：夜市通常很热闹，与“很安静”的意思相反。", "工地": "语义：工地施工时声音很大，不会“很安静”。", "菜市场": "搭配：“安静”不常用来形容菜市场，菜市场一般说“热闹”。"}, "sentence_index": 6, "correct_answer": "寺庙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个小城的寺庙每年生产很多衣服。", "explanation": "这里应该用〈工厂〉。寺庙是拜佛念经的地方，不生产东西，不能说生产衣服。"}, {"text": "那个小城的寺庙每年关了很多犯人。", "explanation": "这里应该用〈监狱〉。寺庙不是关押人的地方，不能说关犯人。"}, {"text": "那个小城的寺庙每年起飞很多航班。", "explanation": "这里应该用〈机场〉。寺庙不是机场，不能说起飞航班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子旁边有两寺庙。", "corrected_sentence": "村子旁边有两座寺庙。", "error_description": "“寺庙”前面的数词后要带量词“座”，不能直接用数词加名词。正确是“两座寺庙”，错误是漏掉了“座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人每天寺庙里念经。", "corrected_sentence": "老人每天在寺庙里念经。", "error_description": "地点介词“在”不能省略。“寺庙里”表示处所，前面要加“在”，应说“在寺庙里念经”；漏掉“在”，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
