INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20266, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不再表示从今以后不这样做或不再发生。", "primary_collocate": null, "pronunciation": "bù zài", "ipa": "pu˥˩ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他不再抽烟。", "target_word": "不再", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不再担心考试了。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子长大了，不再需要妈妈送他上学。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气暖和以后，我们不再穿厚衣服。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他搬到北京以后，不再住在这里。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经不再生他的气了。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店太贵，我们以后不再来了。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说过的话，我不再相信。", "target_word": "不再", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病好了以后，奶奶不再每天吃药。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她决定不再给那个朋友打电话。", "target_word": "不再", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示以前有的动作或状态从现在起不继续、不重复", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20eaa319-c57d-469c-b2b7-b9adb94399fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不再", "is_correct": true, "explanation": "正确：“不再”表示以前抽烟、现在停止，与句意相符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词或心理动词，不修饰“抽烟”这类动作，“他很抽烟”不通。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”同样不修饰“抽烟”这类动作，不能说“非常抽烟”。"}, {"text": "太", "is_correct": false, "explanation": "语义：“太”表示程度过分，“抽烟”是一个动作而不是程度，“他太抽烟”不通。"}], "explanations": {"不再": "正确：“不再”表示以前抽烟、现在停止，与句意相符。", "很": "搭配：“很”修饰形容词或心理动词，不修饰“抽烟”这类动作，“他很抽烟”不通。", "非常": "搭配：“非常”同样不修饰“抽烟”这类动作，不能说“非常抽烟”。", "太": "语义：“太”表示程度过分，“抽烟”是一个动作而不是程度，“他太抽烟”不通。"}, "sentence_index": 0, "correct_answer": "不再"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小到大不再抽烟。", "explanation": "这里应该用〈从来不〉。“不再”表示以前有、现在停止，他从小到大都没抽过，应说“从来不”。"}, {"text": "我们第一次见面，他不再笑。", "explanation": "这里应该用〈一直没有〉。“不再”预设他以前笑过，而第一次见面时他一直没有笑，应说“一直没有笑”。"}, {"text": "我刚来中国，朋友们不再教我汉语了。", "explanation": "这里应该用〈还没〉。“不再”预设以前有过这种情况，我刚来中国，朋友们还没有教过我汉语，应说“朋友们还没教我汉语”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不再", "is_correct": true, "explanation": "正确：“不再”表示以后不再去这家店，与“太贵”的原因相符。"}, {"text": "更", "is_correct": false, "explanation": "搭配：“更”修饰形容词或其他副词，不修饰“来”，不能说“以后更来了”。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去有过的经历，与“以后”的将来时间矛盾，句子说不通。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与“以后”的将来时间矛盾。"}], "explanations": {"不再": "正确：“不再”表示以后不再去这家店，与“太贵”的原因相符。", "更": "搭配：“更”修饰形容词或其他副词，不修饰“来”，不能说“以后更来了”。", "曾经": "语义：“曾经”指过去有过的经历，与“以后”的将来时间矛盾，句子说不通。", "已经": "语义：“已经”表示动作已经完成，与“以后”的将来时间矛盾。"}, "sentence_index": 6, "correct_answer": "不再"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她第一次去北京，不再住在酒店里。", "explanation": "这里应该用〈从没〉。“不再”预设她以前住过酒店，而这是她第一次去北京，应说“她第一次去北京，从没住过酒店”。"}, {"text": "她经常不再给那个朋友打电话。", "explanation": "这里应该用〈又〉。“不再”表示停止，与表示反复的“经常”矛盾；要表示反复出现应说“她又经常给那个朋友打电话”。"}, {"text": "她刚认识那个朋友，就不再给他打电话了。", "explanation": "这里应该用〈第一次〉。“不再”预设以前打过电话，她刚认识那个朋友，这是第一次打，应说“她第一次给他打电话”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现在他不再了哭。", "corrected_sentence": "现在他不再哭了。", "error_description": "语序错误：“了”表示完成，要放在动词“哭”的后面，写成“不再了哭”不通，应改为“不再哭了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她决定不再会给那个朋友打电话了。", "corrected_sentence": "她决定不再给那个朋友打电话了。", "error_description": "多余成分：“不再”后面不能直接加助动词“会”，“不再会”不通；这里不需要“会”，应删去，写作“她决定不再给那个朋友打电话了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "超过", "is_correct": true, "explanation": "正确。“超过”与“不到”相反，表示超出某个数量，符合“不到二十个人”的反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“休息”指停止活动。"}, {"text": "喜欢", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“喜欢”指对人或事物有好感。"}, {"text": "同意", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“同意”指赞成某种意见。"}], "correct_answer": "超过", "explanations": {"超过": "正确。“超过”与“不到”相反，表示超出某个数量，符合“不到二十个人”的反义关系。", "休息": "与“不到”的任何义项都没有反义关系，“休息”指停止活动。", "喜欢": "与“不到”的任何义项都没有反义关系，“喜欢”指对人或事物有好感。", "同意": "与“不到”的任何义项都没有反义关系，“同意”指赞成某种意见。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "超过", "is_correct": true, "explanation": "正确。“超过”与“不到”相反，表示超出某个数量，符合“不到一半”的反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“散步”指慢慢地走着活动身体。"}, {"text": "洗澡", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“洗澡”指用水清洗身体。"}, {"text": "阅读", "is_correct": false, "explanation": "与“不到”的任何义项都没有反义关系，“阅读”指看书、看文字。"}], "correct_answer": "超过", "explanations": {"超过": "正确。“超过”与“不到”相反，表示超出某个数量，符合“不到一半”的反义关系。", "散步": "与“不到”的任何义项都没有反义关系，“散步”指慢慢地走着活动身体。", "洗澡": "与“不到”的任何义项都没有反义关系，“洗澡”指用水清洗身体。", "阅读": "与“不到”的任何义项都没有反义关系，“阅读”指看书、看文字。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "没有到达某个数量或程度。", "primary_collocate": null, "pronunciation": "bú dào", "ipa": "pu˧˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这个孩子不到五岁。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校不到一公里。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了不到十分钟就走了。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里不到二十个人。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书不到一百页。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不到半年，他就学会了开车。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的工资不到五千块。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨晚睡了不到三个小时。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不到两公里长。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天来的学生不到一半。", "target_word": "不到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量或程度还没有达到某个数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c21dd34c-16ba-43e7-a982-0b6076900aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不到", "is_correct": true, "explanation": "正确。不到 bú dào，表示没有达到某个数量或程度。"}, {"text": "不带", "is_correct": false, "explanation": "dài（第四声）与 dào 韵母不同（ai 与 ao），意思是不携带。"}, {"text": "步道", "is_correct": false, "explanation": "bù（第四声）与 bú（第二声）声调不同，意思是步行的道路。"}, {"text": "不倒", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，意思是不倒下。"}, {"text": "不掉", "is_correct": false, "explanation": "diào 比 dào 多了介音 i，韵母不同，意思是不掉落。"}], "explanations": {"不到": "正确。不到 bú dào，表示没有达到某个数量或程度。", "不带": "dài（第四声）与 dào 韵母不同（ai 与 ao），意思是不携带。", "步道": "bù（第四声）与 bú（第二声）声调不同，意思是步行的道路。", "不倒": "dǎo（第三声）与 dào（第四声）声调不同，意思是不倒下。", "不掉": "diào 比 dào 多了介音 i，韵母不同，意思是不掉落。"}, "sentence_index": null, "correct_answer": "不到"}, "level_3": {"options": [{"text": "不到", "is_correct": true, "explanation": "正确。“不到五岁”表示年龄还没有满五岁，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃五岁”。"}, {"text": "碰到", "is_correct": false, "explanation": "语义：“碰到”指接触或遇见，与年龄无关，“碰到五岁”句意不通。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“摸”指用手接触，不能用来表示年龄，句子不通。"}], "explanations": {"不到": "正确。“不到五岁”表示年龄还没有满五岁，符合句意。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃五岁”。", "碰到": "语义：“碰到”指接触或遇见，与年龄无关，“碰到五岁”句意不通。", "摸": "语义：“摸”指用手接触，不能用来表示年龄，句子不通。"}, "sentence_index": 0, "correct_answer": "不到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次数学不到及格，还得补考。", "explanation": "这里应该用〈没及格〉。“不到”表示未达到某个数量或标准，如“不到及格线”；说“不到及格”不自然，应说“没及格”。"}, {"text": "这次出差他不到回来。", "explanation": "这里应该用〈回不来〉。“不到”不能直接接动词作补语，表示无法回来要说“回不来”。"}, {"text": "这几天我都不到他的消息。", "explanation": "这里应该用〈收到〉。表示没有得到消息要说“收不到”或“没收到”，“不到”不能直接接“消息”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不到", "is_correct": true, "explanation": "正确。不到 bú dào，表示没有达到某个数量或程度。"}, {"text": "不料", "is_correct": false, "explanation": "liào（第四声）与 dào 声母不同（l 与 d），声调相同，意思是没想到。"}, {"text": "不抱", "is_correct": false, "explanation": "bào 与 dào 声母不同（b 与 d），声调相同，意思是不拥抱。"}, {"text": "布道", "is_correct": false, "explanation": "bù（第四声）与 bú（第二声）声调不同，dào 相同，意思是向人宣讲教义。"}], "explanations": {"不到": "正确。不到 bú dào，表示没有达到某个数量或程度。", "不料": "liào（第四声）与 dào 声母不同（l 与 d），声调相同，意思是没想到。", "不抱": "bào 与 dào 声母不同（b 与 d），声调相同，意思是不拥抱。", "布道": "bù（第四声）与 bú（第二声）声调不同，dào 相同，意思是向人宣讲教义。"}, "sentence_index": null, "correct_answer": "不到"}, "level_3": {"options": [{"text": "不到", "is_correct": true, "explanation": "正确。“不到五千块”表示工资还没有达到五千块，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能与“工资”搭配，“工资唱五千块”不通。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住或嚼碎，与工资无关，句子不通。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，后面不能直接带“五千块”作宾语。"}], "explanations": {"不到": "正确。“不到五千块”表示工资还没有达到五千块，符合句意。", "唱": "搭配：“唱”的对象是歌曲，不能与“工资”搭配，“工资唱五千块”不通。", "咬": "语义：“咬”指用牙齿夹住或嚼碎，与工资无关，句子不通。", "跑": "配价：“跑”是不及物动词，后面不能直接带“五千块”作宾语。"}, "sentence_index": 6, "correct_answer": "不到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题他不到做出来。", "explanation": "这里应该用〈做不出来〉。“不到”不能直接接动词作补语，表示做不出要说“做不出来”。"}, {"text": "这段时间，我一直不到他。", "explanation": "这里应该用〈见不到〉。“不到”后面接地点、时间或数量，不能直接带人作宾语，要说“见不到他”。"}, {"text": "因为堵车，我不到末班车了。", "explanation": "这里缺少动词“赶”，应说〈赶不到〉。“不到”单独不能接车次作宾语，要加“赶”构成“赶不到末班车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今年还不到了二十岁。", "corrected_sentence": "他今年还不到二十岁。", "error_description": "错误：在“不到”的“到”后多加了“了”。“不到”是动补结构，后面直接接数量，不能加“了”，应说“他今年还不到二十岁”，表示年龄还没有满二十岁。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们等了很不到半个小时。", "corrected_sentence": "我们等了不到半个小时。", "error_description": "错误：在“不到”前多加了程度副词“很”。“不到”表示时间未达到某个长度，前面不能加“很”，应说“我们等了不到半个小时”，表示等待时间不足半小时。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "迷信", "is_correct": true, "explanation": "正确：“科学”与“迷信”是一对反义词，前者讲究证据和规律，后者缺乏依据。"}, {"text": "音乐", "is_correct": false, "explanation": "“音乐”是艺术形式，与“科学”没有反义关系。"}, {"text": "运动", "is_correct": false, "explanation": "“运动”指身体活动，与“科学”没有反义关系。"}, {"text": "美食", "is_correct": false, "explanation": "“美食”指好吃的食物，与“科学”没有反义关系。"}], "correct_answer": "迷信", "explanations": {"迷信": "正确：“科学”与“迷信”是一对反义词，前者讲究证据和规律，后者缺乏依据。", "音乐": "“音乐”是艺术形式，与“科学”没有反义关系。", "运动": "“运动”指身体活动，与“科学”没有反义关系。", "美食": "“美食”指好吃的食物，与“科学”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "迷信", "is_correct": true, "explanation": "正确：“科学”与“迷信”是一对反义词，前者讲究证据和规律，后者缺乏依据。"}, {"text": "花园", "is_correct": false, "explanation": "“花园”指种花草的场所，与“科学”没有反义关系。"}, {"text": "旅游", "is_correct": false, "explanation": "“旅游”指出行游览，与“科学”没有反义关系。"}, {"text": "游戏", "is_correct": false, "explanation": "“游戏”指供人娱乐的活动，与“科学”没有反义关系。"}], "correct_answer": "迷信", "explanations": {"迷信": "正确：“科学”与“迷信”是一对反义词，前者讲究证据和规律，后者缺乏依据。", "花园": "“花园”指种花草的场所，与“科学”没有反义关系。", "旅游": "“旅游”指出行游览，与“科学”没有反义关系。", "游戏": "“游戏”指供人娱乐的活动，与“科学”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "科学是研究世界怎么运行的知识。", "primary_collocate": null, "pronunciation": "kē xué", "ipa": "kʰɤ˥ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "我觉得科学很有意思。", "target_word": "科学", "complexity_tier": "T3", "furigana": "kē xué", "sentence_source": "generated"}, {"text": "科学能告诉我们天为什么会下雨。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想长大以后研究科学。", "target_word": "科学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学让我们的生活越来越方便。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学需要认真做实验。", "target_word": "科学", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多人小时候对科学很感兴趣。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学证明，地球绕着太阳转。", "target_word": "科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好科学，需要多问为什么。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人一辈子都在研究科学。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学告诉我们，水到零度会变成冰。", "target_word": "科学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "科学家", "label": "复合"}, {"form": "科學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "研究自然和世界规律的系统知识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1994afce-084b-4c4b-8b0f-90dace7d412c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科学", "is_correct": true, "explanation": "正确：“科学”指研究世界规律的知识，可以说“很有意思”，符合语境。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是一种疾病，不是可以被评价“很有意思”的对象。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾是废弃物，与“很有意思”的评价不协调。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“有意思”用于事物或想法，不说“眼睛很有意思”。"}], "explanations": {"科学": "正确：“科学”指研究世界规律的知识，可以说“很有意思”，符合语境。", "感冒": "语义：感冒是一种疾病，不是可以被评价“很有意思”的对象。", "垃圾": "语义：垃圾是废弃物，与“很有意思”的评价不协调。", "眼睛": "搭配：“有意思”用于事物或想法，不说“眼睛很有意思”。"}, "sentence_index": 0, "correct_answer": "科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位很有名的科学，发明了很多东西。", "explanation": "这里应该用〈科学家〉。“科学”指知识体系，不指人；从事研究的人要用〈科学家〉。"}, {"text": "他读了很多书，科学很深厚。", "explanation": "这里应该用〈学问〉。“科学”指知识体系，不能用来形容一个人的学识深厚。"}, {"text": "今天的科学很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。“科学”指知识体系，不能用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科学", "is_correct": true, "explanation": "正确：科学可以证明地球绕太阳转，符合语境。"}, {"text": "传说", "is_correct": false, "explanation": "语义：传说没有可靠证据，不能用来“证明”事实。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦是个人的想象，无法证明天文事实。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不能用来证明事实，与“证明”搭配不当。"}], "explanations": {"科学": "正确：科学可以证明地球绕太阳转，符合语境。", "传说": "语义：传说没有可靠证据，不能用来“证明”事实。", "梦": "语义：梦是个人的想象，无法证明天文事实。", "脚步": "搭配：“脚步”不能用来证明事实，与“证明”搭配不当。"}, "sentence_index": 6, "correct_answer": "科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店的科学很热闹。", "explanation": "这里应该用〈生意〉。“科学”是知识体系，不能形容商店的热闹程度；商店热闹要说〈生意〉。"}, {"text": "他每天坐着科学去上班。", "explanation": "这里应该用〈地铁〉。“科学”是知识体系，不能当作交通工具乘坐。"}, {"text": "他的科学今天感冒了。", "explanation": "这里应该用〈学生〉。“科学”是知识体系，不会感冒；会感冒的主语应是人，如〈学生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "数学是一个很有用的科学。", "corrected_sentence": "数学是一门很有用的科学。", "error_description": "“科学”作为学科，应用量词“门”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要用科学地方法解决问题。", "corrected_sentence": "我们要用科学的方法解决问题。", "error_description": "“科学”修饰名词“方法”时应用“的”，不能用“地”；“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消费", "is_correct": true, "explanation": "正确：“生产”与“消费”是一对反义词，前者是制造产品，后者是使用产品。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”指停下来不做事，与“生产”没有反义关系。"}, {"text": "旅游", "is_correct": false, "explanation": "“旅游”指出行游览，与“生产”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指慢慢地走，与“生产”没有反义关系。"}], "correct_answer": "消费", "explanations": {"消费": "正确：“生产”与“消费”是一对反义词，前者是制造产品，后者是使用产品。", "休息": "“休息”指停下来不做事，与“生产”没有反义关系。", "旅游": "“旅游”指出行游览，与“生产”没有反义关系。", "散步": "“散步”指慢慢地走，与“生产”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "消费", "is_correct": true, "explanation": "正确：“生产”与“消费”是一对反义词，前者是制造产品，后者是使用产品。"}, {"text": "睡觉", "is_correct": false, "explanation": "“睡觉”指休息入睡，与“生产”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指用声音表演歌曲，与“生产”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”指快速地跑，与“生产”没有反义关系。"}], "correct_answer": "消费", "explanations": {"消费": "正确：“生产”与“消费”是一对反义词，前者是制造产品，后者是使用产品。", "睡觉": "“睡觉”指休息入睡，与“生产”没有反义关系。", "唱歌": "“唱歌”指用声音表演歌曲，与“生产”没有反义关系。", "跑步": "“跑步”指快速地跑，与“生产”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做出有用的东西。", "primary_collocate": null, "pronunciation": "shēng chǎn", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家工厂生产汽车。", "target_word": "生产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们工厂每天生产一万个杯子。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民在田里生产粮食。", "target_word": "生产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个工厂生产的牛奶很好喝。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新工厂开始生产电视了。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在小镇上生产过很多鞋。", "target_word": "生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家自己生产药，不用买。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们正忙着生产新手机。", "target_word": "生产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，工厂今天不生产。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器一天能生产一千双袜子。", "target_word": "生产", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生产了", "label": "体标"}, {"form": "生产过", "label": "体标"}, {"form": "生产线", "label": "复合"}, {"form": "生產", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工厂或农民制造出产品、粮食等物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1994afce-084b-4c4b-8b0f-90dace7d412c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产", "is_correct": true, "explanation": "正确：工厂“生产”汽车，指制造产品，符合语境。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的主语应是人，工厂不能驾驶汽车。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，汽车不能吃，与语境不符。"}, {"text": "旅行", "is_correct": false, "explanation": "配价：“旅行”是不及物动词，后面不能直接带“汽车”作宾语。"}], "explanations": {"生产": "正确：工厂“生产”汽车，指制造产品，符合语境。", "驾驶": "搭配：“驾驶”的主语应是人，工厂不能驾驶汽车。", "吃": "语义：“吃”指进食，汽车不能吃，与语境不符。", "旅行": "配价：“旅行”是不及物动词，后面不能直接带“汽车”作宾语。"}, "sentence_index": 0, "correct_answer": "生产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事生产了很大的影响。", "explanation": "这里应该用〈产生〉。“生产”指制造物品或粮食，不能与“影响”搭配。"}, {"text": "他每天都在生产笑话。", "explanation": "这里应该用〈讲〉。笑话不是产品，“生产”的对象应是物品。"}, {"text": "他生产了一首很好听的歌。", "explanation": "这里应该用〈创作〉。“生产”指制造物品或粮食，写歌、作曲要用〈创作〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产", "is_correct": true, "explanation": "正确：国家自己制造药品，符合“不用买”的语境。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”与后文“不用买”矛盾，不能用在这里。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”的对象是照片、影视等，不能说“拍药”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱药”。"}], "explanations": {"生产": "正确：国家自己制造药品，符合“不用买”的语境。", "购买": "语义：“购买”与后文“不用买”矛盾，不能用在这里。", "拍": "搭配：“拍”的对象是照片、影视等，不能说“拍药”。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱药”。"}, "sentence_index": 6, "correct_answer": "生产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家学校每年生产一百个学生。", "explanation": "这里应该用〈培养〉。“生产”指制造物品或粮食，学生是人，要用〈培养〉。"}, {"text": "妈妈每天在厨房生产三顿饭。", "explanation": "家里做饭应用〈做〉，〈生产〉指大规模制造产品，不用于日常做饭。"}, {"text": "他每天都生产很多好主意。", "explanation": "这里应该用〈想出〉。主意不是产品，不能用“生产”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂每天生产三十个汽车。", "corrected_sentence": "这家工厂每天生产三十辆汽车。", "error_description": "量词错误：“汽车”的量词应为“辆”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家工厂明年能生产了五万双袜子。", "corrected_sentence": "这家工厂明年能生产五万双袜子。", "error_description": "“明年”指将来，“能”加动词表示将来的能力，动词后不能再加“了”，应说“明年能生产五万双袜子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
