INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20278, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "表示某样东西是某个人的或者属于某个群体。", "primary_collocate": null, "pronunciation": "shǔ yú", "ipa": "ʂu˨˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "这本书属于我。", "target_word": "属于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间属于小王。", "target_word": "属于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果属于水果。", "target_word": "属于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他属于我们这个小组。", "target_word": "属于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片不属于你，不要拿走。", "target_word": "属于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京属于北方城市。", "target_word": "属于", "complexity_tier": "T3", "furigana": "Běijīng shǔyú běifāng chéngshì.", "sentence_source": "generated"}, {"text": "这块地属于一家大公司。", "target_word": "属于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得自己不属于这里。", "target_word": "属于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成功属于努力的人。", "target_word": "属于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝色属于冷色。", "target_word": "属于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不属于", "label": "否定"}], "register": "通用", "sense_fingerprint": "归某人所有或归入某一类别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ddbf6c1-65b5-4c28-9abb-1fe3d7a1f8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等于", "is_correct": false, "explanation": "语义：“等于”表示数量或意义相同，书和人不能“相等”。"}, {"text": "属于", "is_correct": true, "explanation": "正确。“属于”表示某样东西归某人所有，符合“这本书属于我”的意思。"}, {"text": "拥有", "is_correct": false, "explanation": "语义：“拥有”的主语应是拥有者，这里把书说成拥有人，关系颠倒。"}, {"text": "配", "is_correct": false, "explanation": "搭配：“配”用于物与物之间的相配，不能用于人。"}], "explanations": {"等于": "语义：“等于”表示数量或意义相同，书和人不能“相等”。", "属于": "正确。“属于”表示某样东西归某人所有，符合“这本书属于我”的意思。", "拥有": "语义：“拥有”的主语应是拥有者，这里把书说成拥有人，关系颠倒。", "配": "搭配：“配”用于物与物之间的相配，不能用于人。"}, "sentence_index": 0, "correct_answer": "属于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天属于星期三。", "explanation": "这里应该用〈是〉。“属于”表示事物归属于某人或某类，不能用来说明日期。"}, {"text": "我每天都属于跑步。", "explanation": "这里应该用〈练习〉。“属于”表示归属，不能用来说明进行某种活动；“练习”可以与“跑步”搭配。"}, {"text": "他属于一块面包。", "explanation": "这里应该用〈吃〉。“属于”表示归属，不能表示吃下某物；“他吃了一块面包”才是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "位于", "is_correct": false, "explanation": "语义：“位于”后面接地点，“一家大公司”不是地点。"}, {"text": "属于", "is_correct": true, "explanation": "正确。“属于”表示土地归某个机构所有，符合“这块地属于……”的意思。"}, {"text": "高于", "is_correct": false, "explanation": "语义：“高于”用于比较高低，土地与公司之间不能这样比较。"}, {"text": "收购", "is_correct": false, "explanation": "搭配：“收购”的主语是买方，“这块地”不能用来收购公司。"}], "explanations": {"位于": "语义：“位于”后面接地点，“一家大公司”不是地点。", "属于": "正确。“属于”表示土地归某个机构所有，符合“这块地属于……”的意思。", "高于": "语义：“高于”用于比较高低，土地与公司之间不能这样比较。", "收购": "搭配：“收购”的主语是买方，“这块地”不能用来收购公司。"}, "sentence_index": 6, "correct_answer": "属于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书属于五页。", "explanation": "这里应该用〈有〉。“属于”表示归属或归类，不用来说明有多少页。"}, {"text": "我们的课属于下午三点。", "explanation": "这里应该用〈在〉。“属于”表示归属或归类，不能用来说明课程的时间；表示时间要用“在……”。"}, {"text": "我的朋友属于一个苹果。", "explanation": "这里应该用〈拥有〉。“属于”的主语是被归属的事物，这里说朋友属于苹果，与“拥有”的方向颠倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块土地属于了国家。", "corrected_sentence": "这块土地属于国家。", "error_description": "错误在“属于了”：“属于”是表示归属的状态动词，不能加“了”表示完成；应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份资料属于在学校。", "corrected_sentence": "这份资料属于学校。", "error_description": "错误在“属于在”：“属于”后面直接接归属的对象，不能加“在”；应为“属于学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
