INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20284, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人有困难时，你去做点事让他好过一点。", "primary_collocate": null, "pronunciation": "bāng zhù", "ipa": "paŋ˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "谢谢你帮助我学中文。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常常帮助有困难的同学。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮助了很多生病的老人。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们都愿意帮助我们。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想帮助他，但是不知道怎么做。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友帮助我找到了新工作。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶年纪大了，爸爸常常帮助她做家务。", "target_word": "帮助", "complexity_tier": "T3", "furigana": "nǎinai niánjì dà le, bàba chángcháng bāngzhù tā zuò jiāwù", "sentence_source": "generated"}, {"text": "同学们互相帮助，一起做完了作业。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她总是帮助别人，大家都喜欢她。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该帮助那位迷路的老人。", "target_word": "帮助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "帮助了", "label": "体标"}, {"form": "帮助过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，在别人有困难时出力或出主意，使对方得到好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ddbf6c1-65b5-4c28-9abb-1fe3d7a1f8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20284, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "帮助", "is_correct": true, "explanation": "正确：听到的是“帮助”bāngzhù，指出力或出主意使别人好过一点。"}, {"text": "绑住", "is_correct": false, "explanation": "绑住 bǎngzhù 与 帮助 bāngzhù 第一音节声调不同（bǎng 第三声，bāng 第一声），意思是绑住。"}, {"text": "保住", "is_correct": false, "explanation": "保住 bǎozhù 与 帮助 bāngzhù 第一音节韵母不同（-o 与 -ng）且声调不同，意思是保住。"}, {"text": "抱住", "is_correct": false, "explanation": "抱住 bàozhù 与 帮助 bāngzhù 第一音节韵母与声调都不同，意思是抱住。"}, {"text": "帮主", "is_correct": false, "explanation": "帮主 bāngzhǔ 与 帮助 bāngzhù 第二音节声调不同（zhǔ 第三声，zhù 第四声），意思是帮派的首领。"}], "explanations": {"帮助": "正确：听到的是“帮助”bāngzhù，指出力或出主意使别人好过一点。", "绑住": "绑住 bǎngzhù 与 帮助 bāngzhù 第一音节声调不同（bǎng 第三声，bāng 第一声），意思是绑住。", "保住": "保住 bǎozhù 与 帮助 bāngzhù 第一音节韵母不同（-o 与 -ng）且声调不同，意思是保住。", "抱住": "抱住 bàozhù 与 帮助 bāngzhù 第一音节韵母与声调都不同，意思是抱住。", "帮主": "帮主 bāngzhǔ 与 帮助 bāngzhù 第二音节声调不同（zhǔ 第三声，zhù 第四声），意思是帮派的首领。"}, "sentence_index": null, "correct_answer": "帮助"}, "level_3": {"options": [{"text": "帮助", "is_correct": true, "explanation": "正确：“谢谢”之后接帮助对方的行为，“帮助我学中文”符合语境。"}, {"text": "阻碍", "is_correct": false, "explanation": "语义：“阻碍”指妨碍，与“谢谢”的感激语境相反，“谢谢你阻碍我学中文”不通。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不同意，与“谢谢”前后矛盾，句意不通。"}, {"text": "打断", "is_correct": false, "explanation": "搭配：“打断”多接讲话、思路等，“打断我学中文”搭配不自然。"}], "explanations": {"帮助": "正确：“谢谢”之后接帮助对方的行为，“帮助我学中文”符合语境。", "阻碍": "语义：“阻碍”指妨碍，与“谢谢”的感激语境相反，“谢谢你阻碍我学中文”不通。", "反对": "语义：“反对”表示不同意，与“谢谢”前后矛盾，句意不通。", "打断": "搭配：“打断”多接讲话、思路等，“打断我学中文”搭配不自然。"}, "sentence_index": 0, "correct_answer": "帮助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们帮助你的决定。", "explanation": "这里应该用〈支持〉。“帮助”针对需要援助的人，对别人的决定表示赞同要用“支持”。"}, {"text": "我们帮助了那间破旧的房子。", "explanation": "这里应该用〈修缮〉。帮助的对象是人，破旧的房子要修缮，不能说帮助房子。"}, {"text": "我帮助她的勇气。", "explanation": "这里应该用〈欣赏〉。“帮助”指给人实际援助，不用于欣赏对方的品质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20284, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "帮助", "is_correct": true, "explanation": "正确：听到的是“帮助”bāngzhù，指出力或出主意使别人好过一点。"}, {"text": "包住", "is_correct": false, "explanation": "包住 bāozhù 与 帮助 bāngzhù 第一音节韵母不同（-o 与 -ng），意思是包住。"}, {"text": "扳住", "is_correct": false, "explanation": "扳住 bānzhù 与 帮助 bāngzhù 第一音节韵母不同（-n 与 -ng），意思是用力拉住或握紧。"}, {"text": "绷住", "is_correct": false, "explanation": "绷住 bēngzhù 与 帮助 bāngzhù 第一音节主要元音不同（ē 与 ā），意思是绷紧、撑住。"}], "explanations": {"帮助": "正确：听到的是“帮助”bāngzhù，指出力或出主意使别人好过一点。", "包住": "包住 bāozhù 与 帮助 bāngzhù 第一音节韵母不同（-o 与 -ng），意思是包住。", "扳住": "扳住 bānzhù 与 帮助 bāngzhù 第一音节韵母不同（-n 与 -ng），意思是用力拉住或握紧。", "绷住": "绷住 bēngzhù 与 帮助 bāngzhù 第一音节主要元音不同（ē 与 ā），意思是绷紧、撑住。"}, "sentence_index": null, "correct_answer": "帮助"}, "level_3": {"options": [{"text": "帮助", "is_correct": true, "explanation": "正确：“爸爸常常帮助她做家务”指爸爸替年纪大的奶奶分担家务，符合语境。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”指思念过去的人或事，不能用来表示正在进行的家务帮忙，句意不通。"}, {"text": "打听", "is_correct": false, "explanation": "搭配：“打听”一般接消息、情况，不接“她做家务”，搭配不当。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：“原谅”针对过错，句中没有需要原谅的事，句意不通。"}], "explanations": {"帮助": "正确：“爸爸常常帮助她做家务”指爸爸替年纪大的奶奶分担家务，符合语境。", "怀念": "语义：“怀念”指思念过去的人或事，不能用来表示正在进行的家务帮忙，句意不通。", "打听": "搭配：“打听”一般接消息、情况，不接“她做家务”，搭配不当。", "原谅": "语义：“原谅”针对过错，句中没有需要原谅的事，句意不通。"}, "sentence_index": 6, "correct_answer": "帮助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师帮助了他的错误。", "explanation": "这里应该用〈批评〉。“帮助”针对需要帮助的人，指出错误要用“批评”。"}, {"text": "他帮助了历史。", "explanation": "这里应该用〈研究〉。“帮助”的对象是人，历史不能被帮助，研究历史要用“研究”。"}, {"text": "工程师帮助了这座桥。", "explanation": "这里应该用〈设计〉。“帮助”的对象是人，桥是被设计出来的，应用“设计”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年他帮助我了很多次。", "corrected_sentence": "去年他帮助了我很多次。", "error_description": "错误：“帮助我了”；正确：“帮助了我”。动词后面的“了”要紧跟动词，“我”是宾语，应放在“了”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们互帮助，度过了难关。", "corrected_sentence": "我们互相帮助，度过了难关。", "error_description": "错误：“互帮助”不是规范说法；应为“互相帮助”。“互相”是表示彼此的副词，应放在动词“帮助”之前，“互”不能拆出来单独修饰“帮助”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就是马上做，不等一会儿。", "primary_collocate": null, "pronunciation": "lì kè", "ipa": "li˥˩ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "听到电话响，他立刻跑过去了。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说“开始”，我们立刻写字。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到家以后，请立刻给我打电话。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看见红灯，司机立刻停下车。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他应该立刻去医院。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一回到家，就立刻洗手。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了，妈妈立刻抱起他。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课铃一响，学生们立刻站起来。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现钥匙不见了，她立刻回头找。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，他立刻告诉了朋友。", "target_word": "立刻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示马上做，不拖延", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ceb66b7-4790-48b5-8313-3c93963dc888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立刻", "is_correct": true, "explanation": "正确：“立刻”表示马上做，不等一会儿，与“听到电话响”后的即时反应相符。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示一贯不变，与“听到电话响”后的一次性动作不合。"}, {"text": "渐渐", "is_correct": false, "explanation": "语义：“渐渐”表示逐步变化，不能用来描述听到电话后一下子跑过去的瞬间动作。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”表示不常发生，与“跑过去了”这种一次性完成的动作不搭配。"}], "explanations": {"立刻": "正确：“立刻”表示马上做，不等一会儿，与“听到电话响”后的即时反应相符。", "始终": "语义：“始终”表示一贯不变，与“听到电话响”后的一次性动作不合。", "渐渐": "语义：“渐渐”表示逐步变化，不能用来描述听到电话后一下子跑过去的瞬间动作。", "偶尔": "搭配：“偶尔”表示不常发生，与“跑过去了”这种一次性完成的动作不搭配。"}, "sentence_index": 0, "correct_answer": "立刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他立刻学了三年汉语。", "explanation": "这里应该用〈一直〉。“立刻”表示马上做某事，不能和“三年”这种时段搭配；表示持续的动作要说“一直”。"}, {"text": "他立刻在这家公司干了十年。", "explanation": "这里应该用〈长期〉。“立刻”指动作马上发生，不能与“十年”这类长时段连用；长期的经历要说“长期”或“一直”。"}, {"text": "我立刻吃过饭了，所以不饿。", "explanation": "这里应该用〈刚刚〉。“立刻”表示动作马上发生，不表示刚过去不久；刚完成的动作要说“刚刚吃过饭了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立刻", "is_correct": true, "explanation": "正确：“立刻”表示马上行动，与“孩子哭了”后妈妈马上抱起他的情形相符。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”表示动作缓慢，与“孩子哭了”需要马上安抚的情形相矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续不断，不与“抱起”这种一次性完成的动作搭配。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示一贯不变，与“孩子哭了”这一次具体情形不合。"}], "explanations": {"立刻": "正确：“立刻”表示马上行动，与“孩子哭了”后妈妈马上抱起他的情形相符。", "慢慢": "语义：“慢慢”表示动作缓慢，与“孩子哭了”需要马上安抚的情形相矛盾。", "一直": "搭配：“一直”表示持续不断，不与“抱起”这种一次性完成的动作搭配。", "始终": "语义：“始终”表示一贯不变，与“孩子哭了”这一次具体情形不合。"}, "sentence_index": 6, "correct_answer": "立刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他立刻是我的老师。", "explanation": "这里应该用〈原来〉。“立刻”修饰马上发生的动作，不能用来说明早已存在的身份；说明一直如此要用“原来是”。"}, {"text": "这把椅子立刻很旧了。", "explanation": "这里应该用〈渐渐〉。“立刻”指动作即刻发生，不能描述“很旧”这种慢慢形成的状态；慢慢变化要说“渐渐变旧了”。"}, {"text": "听到消息，他立刻很高兴。", "explanation": "这里应该用〈顿时〉。“立刻”修饰动作，不修饰“很高兴”这类形容词谓语；突然出现的心情变化要说“顿时很高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈立刻立刻接了电话。", "corrected_sentence": "妈妈立刻接了电话。", "error_description": "错误在于“立刻”重复出现：副词“立刻”只用一次，放在动词“接”之前。应说“妈妈立刻接了电话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他立刻的站了起来。", "corrected_sentence": "他立刻站了起来。", "error_description": "错误在于“立刻”后面多加了“的”。“立刻”是副词，修饰动词时不加“的”，应说“立刻站了起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
