INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "作家就是用写故事和书来工作的人。", "primary_collocate": null, "pronunciation": "zuò jiā", "ipa": "tsuɔ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "这位作家写了很多有名的小说。", "target_word": "作家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位作家每天早上都在咖啡馆写书。", "target_word": "作家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作家的新书下个月就要出版了。", "target_word": "作家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最喜欢的作家是老舍。", "target_word": "作家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就想当作家，所以每天都写日记。", "target_word": "作家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家住在山里，一个人安静地写作。", "target_word": "作家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本小说的作家今天来书店，很多读者排队请他签名。", "target_word": "作家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人说，作家要多看、多想、多写。", "target_word": "作家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家的故事让很多孩子爱上了读书。", "target_word": "作家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家访问了我们学校，还给同学们讲了他的经历。", "target_word": "作家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "女作家", "label": "复合"}, {"form": "青年作家", "label": "复合"}, {"form": "作家协会", "label": "复合"}], "register": "中性", "sense_fingerprint": "写小说、散文等作品的人，职业身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '447b2f2c-611b-4adc-a6ed-b618209aaf2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作家", "is_correct": true, "explanation": "作家：写小说、散文等作品的人，符合“写了很多有名的小说”的句意。"}, {"text": "读者", "is_correct": false, "explanation": "语义：“读者”是读作品的人，不写作品，与“写了很多有名的小说”不符。"}, {"text": "作曲家", "is_correct": false, "explanation": "搭配：“作曲家”通常谱写乐曲，不说“写小说”，搭配不当。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”做饭，与“写小说”无关，句子不通。"}], "explanations": {"作家": "作家：写小说、散文等作品的人，符合“写了很多有名的小说”的句意。", "读者": "语义：“读者”是读作品的人，不写作品，与“写了很多有名的小说”不符。", "作曲家": "搭配：“作曲家”通常谱写乐曲，不说“写小说”，搭配不当。", "厨师": "语义：“厨师”做饭，与“写小说”无关，句子不通。"}, "sentence_index": 0, "correct_answer": "作家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位作家谱写了很多动听的乐曲。", "explanation": "这里应该用〈作曲家〉。谱写乐曲的是作曲家，作家写的是小说、散文等文字作品。"}, {"text": "这位作家每天在工地上盖房子。", "explanation": "这里应该用〈工人〉或〈建筑工人〉。盖房子的是建筑工人，作家的工作是写作，不做建筑。"}, {"text": "这位作家治好了很多病人。", "explanation": "这里应该用〈医生〉。治病的是医生，作家的工作是写作，不做治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作家", "is_correct": true, "explanation": "作家：写这本小说的人，与“请他签名”的语境相符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“这本小说的司机”不通，司机不写作品。"}, {"text": "护士", "is_correct": false, "explanation": "语义：“这本小说的护士”不通，护士与写作无关。"}, {"text": "警察", "is_correct": false, "explanation": "语义：“这本小说的警察”不通，警察与写作无关。"}], "explanations": {"作家": "作家：写这本小说的人，与“请他签名”的语境相符。", "司机": "语义：“这本小说的司机”不通，司机不写作品。", "护士": "语义：“这本小说的护士”不通，护士与写作无关。", "警察": "语义：“这本小说的警察”不通，警察与写作无关。"}, "sentence_index": 6, "correct_answer": "作家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位作家做了很多好吃的菜。", "explanation": "这里应该用〈厨师〉。做菜的是厨师，作家不以做饭为职业。"}, {"text": "这位作家修好了很多坏掉的电脑。", "explanation": "这里应该用〈修理工〉。修电脑的是修理工，作家的工作是写作。"}, {"text": "这位作家种了很多庄稼。", "explanation": "这里应该用〈农民〉。种庄稼的是农民，作家不以种地为职业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只作家的新书卖得很好。", "corrected_sentence": "这位作家的新书卖得很好。", "error_description": "“作家”指人，量词应用“位”，不能用“只”（“只”多用于动物）。应说“这位作家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天写作，很作家的样子。", "corrected_sentence": "他每天写作，很有作家的样子。", "error_description": "“有作家的样子”是固定说法，这里漏掉了“有”。应说“很有作家的样子”，“很作家”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
