INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20300, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一样东西变得和以前不一样。", "primary_collocate": null, "pronunciation": "gǎi biàn", "ipa": "kai˨˩˦ pjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他想改变自己的生活。", "target_word": "改变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我的习惯改变了。", "target_word": "改变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一本书改变了他的想法。", "target_word": "改变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气改变了我们的计划。", "target_word": "改变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以改变主意吗？", "target_word": "改变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把房间的样子改变了。", "target_word": "改变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行改变了我对城市的看法。", "target_word": "改变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会改变我的决定。", "target_word": "改变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间改变了很多东西。", "target_word": "改变", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想改变学习的方法。", "target_word": "改变", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改变了", "label": "体标"}, {"form": "改变着", "label": "体标"}, {"form": "改变过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使事物变得与原来不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53331fef-4a2b-4af8-8ea1-ed5c509c92d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20300, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下载", "is_correct": false, "explanation": "语域：“下载”是技术用语，不说“下载自己的生活”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，生活不能被吃，不能说“想吃自己的生活”。"}, {"text": "改变", "is_correct": true, "explanation": "正确：“改变”指让生活变得与原来不同，与“他想”和“自己的生活”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用液体，与生活无关。"}], "explanations": {"下载": "语域：“下载”是技术用语，不说“下载自己的生活”。", "吃": "语义：“吃”指进食，生活不能被吃，不能说“想吃自己的生活”。", "改变": "正确：“改变”指让生活变得与原来不同，与“他想”和“自己的生活”搭配。", "喝": "语义：“喝”指饮用液体，与生活无关。"}, "sentence_index": 0, "correct_answer": "改变"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快改变了作业里的错误。", "explanation": "这里应该用〈改正〉。改变指使事物不同于原来，纠正错误要说改正。"}, {"text": "我们终于改变了这个问题。", "explanation": "这里应该用〈解决〉。改变指使事物不同于原来，解决问题要说解决。"}, {"text": "医生改变了他的病。", "explanation": "这里应该用〈治疗〉。改变不能用于病，治好病要说治疗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出发", "is_correct": false, "explanation": "配价：“出发”是不及物动词，不能带“看法”作宾语。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：“砍伐”指砍树，与人的看法无关。"}, {"text": "改变", "is_correct": true, "explanation": "正确：“改变”指让看法变得与原来不同，与“这次旅行”和“我对城市的看法”搭配。"}, {"text": "烘烤", "is_correct": false, "explanation": "搭配：“烘烤”用于食物，不能说烘烤看法。"}], "explanations": {"出发": "配价：“出发”是不及物动词，不能带“看法”作宾语。", "砍伐": "语义：“砍伐”指砍树，与人的看法无关。", "改变": "正确：“改变”指让看法变得与原来不同，与“这次旅行”和“我对城市的看法”搭配。", "烘烤": "搭配：“烘烤”用于食物，不能说烘烤看法。"}, "sentence_index": 6, "correct_answer": "改变"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用一本书改变了一台电脑。", "explanation": "这里应该用〈换〉。改变指使事物变得不同，用物品互换要说换。"}, {"text": "天气预报改变了明天会下雨。", "explanation": "这里应该用〈预测〉。改变指使事物变得不同，推断未来的天气要说预测。"}, {"text": "他改变了一封信到北京。", "explanation": "这里应该用〈寄〉。改变指使事物变得不同，把信送到远处要说寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把房间改变了办公室。", "corrected_sentence": "他把房间改变成了办公室。", "error_description": "补语缺失：“改变”后面要用“成”引出结果，应说“改变成了办公室”，不能直接接结果宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他会不改变自己的习惯。", "corrected_sentence": "他不会改变自己的习惯。", "error_description": "否定词位置错误：“不会”要放在“会”之前，应说“不会改变”，不能说“会不改变”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6006d7-9289-404a-bd33-5cf9c717080e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
