INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20306, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变成", "primary_collocate": null, "pronunciation": "chéng wéi", "ipa": "ʈʂʰɤŋ˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他想成为一名医生。", "target_word": "成为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明长大后成为了老师。", "target_word": "成为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "努力工作，你会成为好经理。", "target_word": "成为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城成为了很有名的地方。", "target_word": "成为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就想成为歌手。", "target_word": "成为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们成为了很好的朋友。", "target_word": "成为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怎样才能成为足球运动员？", "target_word": "成为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书成为了今年最热的书。", "target_word": "成为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都希望成为有钱人。", "target_word": "成为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好汉语，会让你成为更好的翻译。", "target_word": "成为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成为了", "label": "体标"}, {"form": "成為", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由一种状态或身份变为另一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0cc0c3-2668-4386-9dc2-289c59985202') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成为", "is_correct": true, "explanation": "“成为”表示变为某种身份，与“一名医生”搭配。"}, {"text": "担任", "is_correct": false, "explanation": "搭配：“担任”后接职务，如“班长”“主任”，不说“担任医生”。"}, {"text": "学习", "is_correct": false, "explanation": "配价：“学习”后接学科或内容，“学习一名医生”不成立。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”后接学校或学历，不能直接带“一名医生”作宾语。"}], "explanations": {"成为": "“成为”表示变为某种身份，与“一名医生”搭配。", "担任": "搭配：“担任”后接职务，如“班长”“主任”，不说“担任医生”。", "学习": "配价：“学习”后接学科或内容，“学习一名医生”不成立。", "毕业": "配价：“毕业”后接学校或学历，不能直接带“一名医生”作宾语。"}, "sentence_index": 0, "correct_answer": "成为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二乘三成为了六。", "explanation": "这里应该用〈等于〉。表示数学上的相等要用“等于”，“成为”表示变为某种身份或状态，不能表示两个数相等。"}, {"text": "他的体重成为了六十公斤。", "explanation": "这里应该用〈达到〉。“成为”表示变为某种身份或角色，数量或程度的达到要用“达到”。"}, {"text": "今天成为了星期三。", "explanation": "这里应该用〈是〉。日期、时间的判断直接用“是”，“成为”强调经过变化后获得的身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成为", "is_correct": true, "explanation": "“成为”表示变为某种身份，与“足球运动员”搭配。"}, {"text": "加入", "is_correct": false, "explanation": "搭配：“加入”后接团体或组织，不接职业身份。"}, {"text": "退役", "is_correct": false, "explanation": "配价：“退役”是不及物动词，后面不能直接接人。"}, {"text": "考上", "is_correct": false, "explanation": "搭配：“考上”后接学校或单位，不接“足球运动员”。"}], "explanations": {"成为": "“成为”表示变为某种身份，与“足球运动员”搭配。", "加入": "搭配：“加入”后接团体或组织，不接职业身份。", "退役": "配价：“退役”是不及物动词，后面不能直接接人。", "考上": "搭配：“考上”后接学校或单位，不接“足球运动员”。"}, "sentence_index": 6, "correct_answer": "成为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直成为班里的第一名。", "explanation": "这里应该用〈保持〉。“成为”表示由变化而得到的新身份，持续不变要用“保持”。"}, {"text": "我成为了二十岁。", "explanation": "这里应该用〈满〉。年龄的达到要用“满”，“成为”表示变为某种身份或状态。"}, {"text": "他成为了大学。", "explanation": "这里应该用〈进入〉。“成为”后接身份名词，学校这类机构要用“进入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她大学毕业后成为着护士。", "corrected_sentence": "她大学毕业后成为了护士。", "error_description": "错误在于“成为”后不能用“着”。“成为”表示变化已经完成，应说“成为了”，把“着”换成“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时曾经成为了过一名作家。", "corrected_sentence": "他年轻时曾经成为过一名作家。", "error_description": "错误在于“成为”后同时用了“了”和“过”。表示曾经有过某种身份用“成为过”，“了”和“过”不能叠用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
